SELECT 'moj-all-verified-judgments-review-002-chunk-168' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"0b51380e-d5ec-52fb-b313-a6335ea57c74","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -بيع -اخاء عقار بعد البيع -سداد اجره فترة البقاء بعد االفراغ ودفع اجره محاماة [ طلبان عارضان] -وجوب الوفاء بالعقود -احلكم بإخاء العقار -تأجيل النظر يف طلب عارض حتى توفر مسوغات البت فيه .","document_number":"34187682","case_number":"33336901","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/14","year":"1434","subject":"عقار -بيع -اخاء عقار بعد البيع -سداد اجره فترة البقاء بعد االفراغ ودفع اجره محاماة [ طلبان عارضان] -وجوب الوفاء بالعقود -احلكم بإخاء العقار -تأجيل النظر يف طلب عارض حتى توفر مسوغات البت فيه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/14 :‬ه‬\n                ‫ُ‬                ‫َر ْق ُم َّ‬\n                   ‫الص ِّك‪34187682 :‬‬\n                  ‫َر ْق ُم الدعوى‪33336901 :‬‬\n  ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34273196‬تاريخه‪1434/7/19 :‬هـ‬\n\n\n‫عقــار ‪ -‬بيــع ‪ -‬اخــاء عقــار بعــد البيــع ‪ -‬ســداد اجــره فتــرة البقــاء‬\n‫بعــد االفــراغ ودفــع اجــره محامــاة [ طلبــان عارضــان] ‪ -‬وجــوب الوفــاء‬\n‫بالعقــود ‪ -‬احلكــم بإخــاء العقــار ‪ -‬تأجيــل النظــر يف طلــب عــارض‬\n                                       ‫حتــى توفــر مســوغات البــت فيــه ‪.‬‬\n\n\n\n\n                         ‫آم ُنوا َأوْفُ وا ِبا ْل ُع ُقودِ)‬ ‫‪ .1‬قوله تعالى ( َيا َأ ُّي َها ا َّلذِ َ‬\n                                                         ‫ين َ‬\n                                         ‫‪ .2‬املادة (‪ )81‬من نظام املرافعات الشرعية‬\n\n\n\n\n‫ادعــى املدعــي وكالــة عــن إحــدى الشــركات ضــد املدعــى عليــه‬\n‫وكالــة أن الشــركة موكلتــه قــد اشــترت عقــار ًا مــن املدعــى عليــه‬\n‫مبينـ ًا موقعــه وصفتــه بالدعــوى بثمــن وقــدره ثمامنائــة ألــف ريــال اســتلمها‬\n‫املدعــى عليــه إال أن املدعــى عليــه مــا زال ســاكن ًا بالعقــار وطالــب‬\n‫املدعــي وكالــة بإلــزام املدعــى عليــه بإخــاء العقــار وأجــرة املثــل مــدة‬\n‫بقــاء املدعــى عليــه وإلزامــه بأجــرة احملامــاة ‪ -‬أجــاب املدعــى عليــه‬\n‫باإلنــكار وقــرر أن الــذي اشــترى العقــار شــخص آخــر وان املدعــى عليــه‬\n‫أصالــة اشــترط أن يبقــى يف الــدور األرضــي مــدة ســنتني ‪ -‬اطلــع ناظــر‬\n‫القضيــة علــى صــك العقــار فوجــد انــه مت التهميــش علــى صــك امللكيــة‬\n\n                                                                                                       ‫‪418‬‬\n\f      ‫بانتقــال ملكيــة العقــار للشــركة املدعيــة مقابــل ثمامنائــة ألــف ريــال ‪-‬‬\n      ‫آم ُنــوا َأ ْو ُفــوا ِبا ْل ُع ُقــود)‬\n                                            ‫(يــا َأ ُّي َهــا ا َلّذِ يـ َـن َ‬\n                                                                             ‫قــرر ناظــر القضيــة ولقولــه تعالــى َ‬\n      ‫ولعــدم ثبــوت شــرط ينــايف ذلــك فقــد صــدر احلكــم بإخــاء املدعــى‬\n      ‫عليــه أصالــة للعقــار وتأجيــل النظــر يف الطلبــات العارضــة حلــن توفــر‬\n      ‫مســوغات البــت فيهــا ‪ -‬قــرر املدعــى عليــه عــدم القناعــة ‪ -‬صــدر قــرار‬\n                     ‫محكمــة االســتئناف مبنطقــة عســير باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي‪ ...‬يف احملكمــة العامــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بنجــران برقــم ‪ 33336901‬وتاريــخ ‪1433/05/16‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33916339‬وتاريــخ ‪ 1433/05/16‬ه ـ حضــر‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم الوكيــل الشــرعي عــن‬\n      ‫شــركة ‪........‬مبوجــب الوكالــة رقــم ‪........‬وتاريــخ ‪1433/03/26‬ه ـ‬\n      ‫والتــي تخولــه حــق التقاضــي أمــام جميــع جهــات التقاضــي وجميــع جلــان‬\n      ‫التســوية والهيئــات القضائيــة والقانونيــة ولــه احلــق يف إقامــة الدعــاوى‬\n      ‫وتقــدمي البينــات واملرافعــة واملدافعــة واملخاصمــة وغيــر ذلــك وحضــر‬\n      ‫حلضــوره املدعــى عليــه وكالــة ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫ا عــن املدعــى عليــه ابنــه‪ ...‬مبوجــب صــك الوكالــة‬    ‫رقــم بصفتــه وكي ـ ً‬\n      ‫الصــادر مــن كتابــة العــدل الثانيــة بشــرق الريــاض برقــم ‪........‬وتاريــخ‬\n      ‫‪1434/04/07‬ه ـ والتــي تخولــه حــق املطالبــة وإقامــة الدعــاوى واملرافعــة‬\n      ‫واملدافعــة وســماع الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار وغيــر‬\n      ‫ذلــك فادعــى املدعــي قائــا يف دعــواه أن الشــركة موكلتــي اشــترت‬\n\n‫‪419‬‬\n\f‫مــن املدعــى عليــه أصالــة منــز ًال يقــع يف حــي ‪........‬ذي الصــك رقــم ‪........‬‬\n‫وتاريــخ ‪1395/02/06‬ه ـ والبالــغ مســاحتها ســبعمائة وخمســة وثالثــون‬\n‫متــر ًا مربع ـ ًا وحدودهــا كمــا يلــي ‪ :‬شــما ًال بطــول ثالثــن متــر ًا يليهــا‬\n‫األرض رقــم ‪ 149‬وجنوب ـ ًا بطــول ثالثــن متــر ًا يليهــا الشــارع رقــم ‪88‬‬\n‫بعــرض ‪ 15‬م وشــرقا بطــول أربعــة وعشــرين متــر ًا وخمســن ســم يليهــا‬\n‫األرض رقــم ‪ 152‬وغرب ـ ًا بطــول أربعــة وعشــرين متــر ًا وخمســن ســم‬\n‫يليهــا األرض رقــم ‪ 148‬للمدعــو ‪ ... /‬ومت اإلفــراغ للشــركة موكلتــي‬\n‫يف ‪1432/11/17‬ه ـ مقابــل مبلــغ وقــدره ثمامنائــة ألــف ريــال ســعودي‬\n‫اســتلمها املدعــى عليــه مبوجــب شــيك صــادر مــن مصــرف ‪ ...‬والزال‬\n‫املدعــى عليــه يف املنــزل ولــم يخــرج منــه حتــى هــذا التاريــخ أطلــب إلــزام‬\n‫املدعــى عليــه بإخــاء العقــار وإلزامــه بدفــع أجــرة املثــل عــن الفتــرة التــي‬\n‫كان العقــار حتــت يــده بعــد اإلفــراغ وإلزامــه بدفــع أجــرة احملامــاة‬\n‫هــذه دعــواي وبعــرض مــا جــاء يف الدعــوى علــى املدعــى عليــه وكال ـ ًة‬\n‫ا مــا ذكــره املدعــي وكالــة مــن أن موكلــي بــاع املنــزل‬          ‫أجــاب قائ ـ ً‬\n‫املذكــور علــى شــركة ‪ ...‬غيــر صحيــح وإمنــا الصحيــح أنــه باعــه علــى‬\n‫شــخص يدعــى مببلــغ وقــدره تســعمائة وخمســون ألــف ريــال ســعودي‬\n‫اســتلم موكلــي مــن مبلغ ـ ًا وقــدره مائــة وخمســون ألــف ريــال واســتلم‬\n‫موكلــي مــن البنــك مبلغ ـ ًا وقــدره ثمامنائــة ألــف ريــال ســعودي وقــد‬\n‫اشــترط عليــه أن يبقــى يف املنــزل مــدة ســنتني يف الــدور األرضــي أمــا‬\n‫الــدور العلــوي فقــد اســتلمه وقــام بتأجيــره هــذه إجابتــي وبعــرض ذلــك‬\n‫علــى املدعــي وكالــة مــا ذكــر املدعــى عليــه وكال ـ ًة غيــر صحيــح‬\n‫والصحيــح مــا ذكرتــه أنــا فاملشــتري هــي موكلتــي وليــس للشــخص‬\n‫املذكــور أي صفــة يف البيــع هكــذا أجــاب و بســؤاله البينــة علــى مــا‬\n\n\n                                                                                        ‫‪420‬‬\n\f      ‫ذكــر أبــرز صــك العقــار املذكــور بعاليــه وقــد قمــت ســابق ًا بالكتابــة‬\n      ‫ملصــدره كتابــة عــدل منطقــة ‪ ...‬لالستفســار عــن ســريان مفعولــه وذلــك‬\n      ‫برقــم ‪ 34750289‬وتاريــخ ‪1434/03/25‬ه ـ فوردنــا اجلــواب منهــم برقــم‬\n      ‫‪ 34792132‬وتاريــخ ‪1434/04/01‬ه ـ املقيــد لدينــا باحملكمــة برقــم‬\n      ‫‪ 34811508‬وتاريــخ ‪1434/04/02‬ه ـ املتضمــن مطابقــة الصــك لســجله‬\n      ‫وباإلطــاع علــى أصــل الصــك وجدتــه تضمــن انتقــال ملكيــة العقــار‬\n      ‫لصالــح شــركة ‪........‬يف ‪1432/11/17‬ه ـ مبقابــل مبلــغ وقــدره ثمامنائــة‬\n      ‫ألــف ريــال ســعودي وبســؤال املدعــي وكالــة عــن عالقتــه بالشــركة‬\n      ‫ا أنــي موظــف لديهــم أتقاضــى راتبـ ًا ثابتـ ًا هكــذا‬  ‫املوكلــة أجــاب قائـ ً‬\n      ‫ا إخــاء‬  ‫أجــاب وبســؤاله عــن طلبــه األصلــي يف الدعــوى أجــاب قائ ـ ً‬\n      ‫املدعــى عليــه أصال ـ ًة مــن العقــار فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وإلقــرار املدعــى عليــه أصالــة لــدى كاتــب العــدل ببيــع العقــار‬\n      ‫علــى الشــركة املدعيــة مقابــل مبلــغ وقــدره ثمامنائــة ألــف ريــال ســعودي‬\n      ‫ولكــون إخــاء العقــار مــن مقتضيــات عقــد البيــع ولعــدم ثبــوت شــرط‬\n      ‫ينــايف ذلــك ولقولــه تعالــى ‪ ( :‬يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود )‬\n      ‫وللمــادة احلاديــة والثمانــن مــن نظــام املرافعــات الشــرعية وملــا تقــدم كله‬\n      ‫فقــد حكمــت بإخــاء املدعــى عليــه أصالــة العقــار املذكــور وقــررت‬\n      ‫تأجيــل النظــر يف الطلبــات العارضــة األخــرى حلــن توفــر مســوغات البــت‬\n      ‫فيهــا مبــا تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــررا عــدم‬\n      ‫قناعتهمــا باحلكــم وطلبــا اســتئناف احلكــم لــدى محكمــة االســتئناف‬\n      ‫وجــرى إفهامهمــا باســتالم نســخة احلكــم يف هــذا اليــوم وأن عليهمــا‬\n      ‫أن يتقدمــا بالالئحــة االعتراضيــة خــال ثالثــن يوم ـ ًا تبــدأ مــن هــذا‬\n      ‫اليــوم وأنــه إذا انقضــت املــدة ولــم يتقــدم أحدهمــا بالئحتــه فــإن حقــه يف‬\n\n\n‫‪421‬‬\n\f‫االعتــراض يســقط وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/04/14‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n‫فلــدي أنــا القاضــي باحملكمــة العامــة بنجــران والقائــم بعمــل املكتــب‬\n‫القضائــي الســادس فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبنطقــة عســير برقــم ‪ 341251409‬وتاريــخ ‪1434/07/26‬ه ـ برفقهــا‬\n‫القــرار الصــادر مــن الدائــرة احلقوقيــة الثالثــة برقــم ‪ 34273196‬وتاريــخ‬\n‫‪1434/07/19‬ه ـ ونــص احلاجــة منــه ‪ ( :‬وبدراســة الصــك وصــورة ضبطه‬\n‫واملذكرتــن االعتراضيتــن وأوراق املعاملــة لــم يظهــر مــا يوجــب‬\n‫االعتــراض لــذا قررنــا املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬قاضــي اســتئناف ختمــه‬\n‫وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه‬\n‫) وحتــى ال يخفــى جــرى حتريــره وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n        ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/28‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n‫الثالثــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة بنجــران برقــم ‪ 331943923‬وتاريــخ‬\n‫‪1434/5/13‬ه ـ اخلاصــة بدعــوى‪ /‬وكالــة ضــد‪ /‬وكالــة بشــأن إخــاء‬\n‫عقــار املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪ /‬برقــم ‪34187682‬‬\n‫وتاريــخ ‪1433/4/14‬ه ـ املتضمــن حكــم فضيلته مبا هو مدون ومفصل‬\n‫فيــه وبدراســة الصــك وصــورة ضبطــه واملذكرتــن االعتراضيتــن‬\n‫وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض لــذا قررنــا املوافقــة علــى‬\n‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                            ‫وســلم ‪.‬‬\n                                                                                       ‫‪422‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":418,"source_page_end":422,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9a639991c0292197b2b43b4f7a9800fc02222d343e4a573c175b0188460b185f","normalized_text_hash":"67ff70f3d0463cc6d87f509e102874748b27e28f14e6122218ae9bc3c4f784fe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p418-34187682"},{"id":"ac8d2fc3-ab9e-5e98-9f30-c94c58f5f31d","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -تداخل عقارات -قيام طريف اخلصومة بشراء العقار من باقي الورثة وتقسيم امللكية والنسبة املشاعة بينهما -قيام املدعية ببناء بعض اإلنشاءات -االختاف حول النسبة املشاعة -تكييف الدعوى دائر بن كونه وعد ا أو بيع ا معلق ا على شرط مجهول -الوعد غير ملزم والبيع املعلق على شرط مجهول غير صحيح -شرط بحث الواقعة أن تكون منتجة -رد الدعوى واخاء سبيل املدعى عليها .","document_number":"33359710","case_number":"156780615","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/28","year":"1434","subject":"عقار -تداخل عقارات -قيام طريف اخلصومة بشراء العقار من باقي الورثة وتقسيم امللكية والنسبة املشاعة بينهما -قيام املدعية ببناء بعض اإلنشاءات -االختاف حول النسبة املشاعة -تكييف الدعوى دائر بن كونه وعد ا أو بيع ا معلق ا على شرط مجهول -الوعد غير ملزم والبيع املعلق على شرط مجهول غير صحيح -شرط بحث الواقعة أن تكون منتجة -رد الدعوى واخاء سبيل املدعى عليها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33359710:‬تاريخه‪1433/7/28 :‬هـ‬\n                       ‫رقم الدعوى‪156780615 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34177916‬تاريخه‪1434/4/2 :‬هـ‬\n\n\n      ‫عقــار ‪ -‬تداخــل عقــارات‪ -‬قيــام طــريف اخلصومة بشــراء العقــار من باقي‬\n      ‫الورثــة وتقســيم امللكيــة والنســبة املشــاعة بينهمــا‪ -‬قيــام املدعيــة ببنــاء‬\n      ‫بعــض اإلنشــاءات‪ -‬االختــاف حــول النســبة املشــاعة‪ -‬تكييــف الدعــوى‬\n      ‫دائــر بــن كونــه وعــد ًا أو بيعـ ًا معلقـ ًا علــى شــرط مجهــول‪ -‬الوعــد غيــر‬\n      ‫ملــزم والبيــع املعلــق علــى شــرط مجهــول غيــر صحيــح‪ -‬شــرط بحــث‬\n         ‫الواقعــة أن تكــون منتجــة‪ -‬رد الدعــوى واخــاء ســبيل املدعــى عليهــا ‪.‬‬\n\n\n\n\n      ‫‪ .1‬جــاء يف كشــاف القنــاع (‪( )402/7‬النــوع الثالــث مــن الشــروط‬\n      ‫الفاســدة ‪ :‬أن يشــترط البائــع شــرط ًا يعلــق البيــع عليــه كقولــه‬\n      ‫بعتــك إن جئتنــي بكــذا أو بعتــك إن رضــي فــان وكــذا تعليــق الشــراء‬\n      ‫كقبلــت إن جــاء زيــد ونحــوه فــا يصــح البيــع ألن مقتضــى البيــع نقــل‬\n                                ‫امللــك حــال التبايــع والشــرط هنــا مينعــه) ‪.‬‬\n      ‫‪ .2‬جــاء يف املجمــوع للنــووي ص‪( 28‬وال يجــوز تعليــق البيــع علــى شــرط‬\n      ‫مســتقبل كمجــيء الشــهر وقــدوم احلــاج ألنــه بيــع غــرض مــن غيــر‬\n                                                             ‫حاجــة فلــم يجــز )‪.‬‬\n\n\n\n\n‫‪423‬‬\n\f‫قامــت املدعيــة واملدعــى عليهــا بشــراء عقــار مــن باقــي الورثــة كان‬\n‫مملــوك ًا لوالدهمــا‪ ،‬قامــا بتقســيم ذلــك العقــار فيمــا بينهمــا واتفقــا‬\n‫علــى حتديــد النســبة املشــاعة‪ ،‬كمــا اتفقــا علــى أنــه يف حالــة قيــام‬\n‫املدعيــة ببنــاء إنشــاءات جديــدة يتــم تعديــل النســبة املشــاعة لتكــون‬\n‫مناصفــة فيمــا بينهمــا‪ ،‬األظهــر يف تكييــف مقتضــى هــذه الدعــوى‬\n‫دائــر بــن كونــه وعــد ًا أو بيع ـ ًا معلق ـ ًا علــى شــرط مجهــول واألول غيــر‬\n‫ملــزم والثانــي غيــر صحيــح عنــد اجلمهــور‪ ،‬وألن شــرط بحــث الواقعــة أن‬\n‫تكــون منتجــة‪ ،‬وملــا كانــت هــذه الواقعــة غيــر منتجــة عنــد بحثهــا فقــد‬\n‫حكمــت احملكمــة بعــدم اســتحقاق املدعيــة ملــا تدعيــه ورد دعواهــا‬\n                            ‫صادقــت محكمــة اإلســتئناف علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة العامــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة الرئيــس‬\n‫برقــم ‪ 15678‬واملقيــدة بأســاس احملكمــة برقــم ‪ 3169016‬وتاريــخ‬\n‫‪1431/7/3‬ه ـ ويف يــوم األربعــاء ‪1433/3/2‬ه ـ حضــرت ‪ .....‬بالســجل‬\n‫املدنــي رقــم ‪.....‬واملعــرف بهــا مــن ‪.....‬بالســجل املدنــي رقــم ‪.....‬وحضــر‬\n‫حلضورهمــا ‪ .....‬بالســجل املدنــي رقــم ‪.....‬وكيــا عــن ‪.....‬مبوجــب صــك‬\n‫الوكالــة الصــادر مــن كتابــة عــدل الثانيــة مبكــة املكرمــة برقــم‬\n‫‪ 22393‬وتاريــخ ‪1426/6/5‬ه ـ واملخــول لــه فيهــا حــق املدافعــة واملرافعــة‬\n‫وســماع الدعــاوي وتقــدمي البينــات وقبــول احلكــم واالعتــراض عليــه‬\n\n                                                                                     ‫‪424‬‬\n\f      ‫وادعــت األولــى قائلــة ‪ :‬لقــد كان مــن اجلــاري يف ملــك والــدي رحمــه‬\n      ‫اهلل كامــل العمــارة أرضــا وبنــاء الكائنــة بالعزيزيــة بالضفــة الغربيــة‬\n      ‫تقســيم أربعــة القطعــة رقــم ‪ 403‬يف املخطــط رقــم ‪ 32/21/1‬ومســاحتها‬\n      ‫شــرقا وغربــا عشــرون متــرا وشــماال وجنوبــا خمســة وعشــرون متــرا‬\n      ‫ويحدهــا شــرقا شــارع عرضــه عشــرة أمتــار وغربــا شــارع عرضــه ســتة‬\n      ‫أمتــار وشــماال القطعــة رقــم ‪ 404‬وجنوبــا القطعــة رقــم ‪ 402‬ومســاحتها‬\n      ‫اإلجماليــة خمســمائة متــر مربــع واملشــتملة حينهــا علــى بــدروم ودوريــن‬\n      ‫متكــرر يف كل دور شــقتني وكل شــقة أربــع غــرف مبنافعهــا‬\n      ‫الشــرعية وشــقة يف الــدور الثالــث مكونــة مــن أربــع غــرف مبنافعهــا‬\n      ‫الشــرعية واململوكــة لــه مبوجــب الصــك الصــادر مــن كتابــة عــدل‬\n      ‫برقــم ‪ 4/122/161‬وتاريــخ ‪1409/4/17‬ه ـ وبعــد أن تــويف والــدي ‪.....‬‬\n      ‫وانحصر ارثه يف ‪..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... .....‬قمت أنا‬\n      ‫وشــقيقتي املدعــى عليهــا بشــراء نصيــب البقيــة مبليــون ريــال بعــد أن قــام‬\n      ‫الورثــة بتقســيم العقــار جلزئــن اجلــزء األول البدروم والــدوران املتكرران‬\n      ‫يف كل دور شــقتان وأمــا اجلــزء اآلخــر فهــو الــدور الثالــث املكــون مــن‬\n      ‫شــقة بأربــع غــرف مبنافعهــا مــع الســطح اشــتريت الثانــي ودفعــت مائــة‬\n      ‫وخمســن ألــف ريــال للورثــة والباقــي دفعتــه شــقيقتي مقابــل اجلــزء األول‬\n      ‫علــى أن يكــون لــي احلــق بالتصــرف يف الــدور لــو رغبــت اضافــة أدوار‬\n      ‫أو شــقق أخــرى وأن يكــون مدخــل العمــارة للجميــع وأمــا حصــص املــاء‬\n      ‫والصــرف الصحــي فعلــي الربــع والباقــي عليهــا إال إن أضفــت شــقة يف‬\n      ‫الــدور الثالــث فيكــون علــي الثلــث والثلثــان عليهــا وإن أنشــأت دورا‬\n      ‫رابعــا فعلــي النصــف والنصــف اآلخــر عليهــا وملــا قمنــا بإجــراء اإلفــراغ‬\n      ‫لــدى كتابــة العــدل اتفقــت وإياهــا علــى أن النســبة املشــاعة يف األرض‬\n\n\n‫‪425‬‬\n\f‫خمســة وثمانــن يف املائــة لهــا وخمســة عشــر يف املائــة لــي ‪ ،‬علــى أنــي إن‬\n‫أجريــت أي إضافــة يف املبنــى فتعــدل النســبة املشــاعة يف األرض أي أنــي‬\n‫أن أكملــت الــدور الثالــث وأضفــت الرابــع فتكــون النســبة مناصفــة‬\n‫بيننــا ثــم قمــت بإكمــال الــدور الثالــث وإنشــاء الــدور الرابــع وأكملــت‬\n‫فــوق الرابــع مبيتــات وكنــت يف يــوم األحــد ‪1429/6/10‬ه ـ اتفقــت معها‬\n‫علــى أن احلــوش ملــك ‪.....‬واحلــوش اجلانبــي علــى ميــن الداخــل إلــى العمــارة‬\n‫ممــر مشــترك للجميــع وال يحــق اســتخدامه الشــخصي إال بعــد الرجــوع‬\n‫إلــى املالــك ‪ .....‬واألســطح ملكــي ويجــوز ل‪.....‬االســتفادة مــن ســطح‬\n‫املبيتــات فقــط ملنافــع املــاء وأجهــزة االســتقبال واملصعــد يتــم التنســيق‬\n‫بنــاء علــى وضــع بــاب بالــدور األول فقــط مــن قبــل ‪.....‬و املبانــي حســب‬\n‫املتفــق عليــه البــدروم والــدور األرضــي والــدور األول ملــك ل‪ .....‬والــدور‬\n‫الثانــي والــدور الثالــث والســطح واملبيتــات يكــون لــي وأمــا األرض تبقــى‬\n‫النســبة مبــا يحكــم بــه القضــاء لــذا فقــد أقمــت دعواي لديكــم للفصل‬\n‫يف النســبة املشــاعة مــن األرض وأطلــب تعديلهــا إلــى أن يكــون لــي‬\n‫النصــف مشــاعا مــن األرض والنصــف اآلخــر لهــا هــذه دعــواي وبعرضــه‬\n‫علــى وكيــل املدعــى عليهــا قــال مــا ذكرتــه املدعيــة كلــه صحيــح إال‬\n‫قولهــا بأنهــا اشــترطت أنهــا إن أضافــت أدوارا فتعــدل احلصــص علــى‬\n‫وفــق األنقــاض وأن القســمة حصلــت بــن الورثــة قبــل البيــع فهــذا غيــر‬\n‫صحيــح والصحيــح أن القســمة حصلــت بعــد الشــراء مشــاعا بــن الورثــة‬\n‫وهــل يعقــل أن موكلتــي التــي اشــترت (‪ )%85‬مــن األرض توافــق علــى‬\n‫الســماح لهــا باالرتفــاع علــى قــدر مــا تشــاء وكلمــا ارتفعــت ينقــص حقهــا‬\n‫جبــرا لــذا فــإن موكلتــي تطلــب رد دعواهــا وبعرضــه علــى املدعيــة قالــت‬\n‫الصحيــح مــا ادعيــت بــه ولــم تــأت بذكــر لــأرض علــى انفــراد وعبارتهــا‬\n\n\n                                                                                      ‫‪426‬‬\n\f      ‫التــي قالتهــا لــي إن اضفــت مبانــي فلــك نصــف العمــارة أ‪.‬ه ـ فقــرر وكيل‬\n      ‫املدعــى عليهــا قائــا‪ :‬مــا ذكرتــه مــن هــذه العبــارة ال علــم لي بهــا وأما ما‬\n      ‫ذكرتــه مــن األرض لــم يكــن لهــا ذكــر فصحيــح وموكلتــي تتمســك‬\n      ‫مبــا صــرح بــه يف الصــك أ‪.‬ه ـ ثــم حضــرت املدعيــة أصالــة وحضــرت‬\n      ‫حلضورهــا املدعــى عليهــا ‪ .....‬وحتمــل الســجل املدنــي رقــم ‪.....‬وقــد‬\n      ‫وردنــا االستفســار عــن صــك امللكيــة مــن كتابــة عــدل برقــم ‪1/1928‬‬\n      ‫وتاريــخ ‪1433/3/14‬ه ـ ومضمونــه أن صــورة الصــك رقــم ‪4/122/161‬‬\n      ‫يف ‪1409/4/17‬ه ـ مطابقــة لســجلها وســارية املفعــول حتــى تاريخــه أ‪.‬ه ـ‬\n      ‫فســألتهما إن كان لديهمــا مــا يضيفانــه فأجابــا بالنفــي عليــه وبعــد‬\n      ‫قفــل بــاب املرافعــة وبعــد تأمــل الدعــوى واإلجابــة وألن املدعيــة تطلــب يف‬\n      ‫دعواهــا إنفــاذ مقتضــى مــا تدعيــه مــن اتفــاق بينهــا وبــن املدعــى عليهــا‬\n      ‫بأنهــا متــى قامــت بزيــادة قــدر األنقــاض فإنهــا تســتحق مقابلــه نصيب ـ ًا‬\n      ‫مشــاع ًا مــن األرض وأنهــا قامــت بزيــادة قــدره وتطلــب مقابلــه إفــراغ جــزء‬\n      ‫مشــاع مــن األرض وألن األظهــر يف تكييــف مقتضــى دعــوى املدعيــة‬\n      ‫دائــر بــن كونــه وعــد ًا أو بيع ـ ًا معلق ـ ًا علــى شــرط مجهــول أمــا األول‬\n      ‫فغيــر ملــزم علــى قــول اجلماهيــر وأمــا اآلخــر فغيــر صحيــح علــى قــول‬\n      ‫اجلمهــور قــال يف كشــاف القنــاع (النــوع الثالــث مــن الشــروط الفاســدة‬\n      ‫‪ :‬أن يشــترط البائــع شــرط ًا يعلــق البيــع عليــه كقولــه بعتــك إن جئتنــي‬\n      ‫بكــذا أو بعتــك إن رضــي فــان وكــذا تعليــق الشــراء كقبلــت إن جــاء‬\n      ‫زيــد ونحــوه فــا يصــح البيــع ألن مقتضــى البيــع نقــل امللــك حــال التبايــع‬\n      ‫والشــرط هنــا مينعــه) كتــاب البيــع (‪ )402/7‬وقــال يف املجمــوع للنــووي‬\n      ‫«وال يجــوز تعليــق البيــع علــى شــرط مســتقبل كمجــيء الشــهر وقــدوم‬\n      ‫احلــاج ألنــه بيــع غــرض مــن غيــر حاجــة فلــم يجــز « كتــاب بيــوع ص ‪28‬‬\n\n\n‫‪427‬‬\n\f‫عليــه وألن مــن شــرط بحــث الواقعــة أن تكــون منتجــة وألن دعواهــا وإن‬\n‫ثبتــت غيــر صحيحــة وال يلــزم املدعــى عليهــا شــيئ ًا مبقتضاهــا هــذا مــن‬\n‫جهــة ومــن جهــة أخــرى فــإن املدعيــة أقــرت بــأن املدعــى عليهــا لــم تتفــق‬\n‫ا وارد ًا علــى‬ ‫معهــا علــى األرض علــى انفــراد بــل إقرارهــا كان مجم ـ ً‬\n‫ا لألنقــاض فقــط دون األرض وهــو مــا‬          ‫العمــارة عليــه فيكــون محتم ـ ً‬\n‫ال تنكــره املدعــى عليهــا وبــن األرض واألنقــاض جميعـ ًا ممــا يضعــف‬\n‫دعــوى املدعيــة مــع قيــام هــذا االحتمــال لــذا وملــا تقــدم فلــم يظهــر لــي‬\n‫اســتحقاق املدعيــة ملــا تدعيــه ورددت دعواهــا وأخليــت ســبيل املدعــى‬\n‫عليهــا مــن هــذه املطالبــة وبــه حكمــت وجــرى النطــق بــه يف يــوم الســبت‬\n‫‪1433/7/26‬ه ـ وبعرضــه عليهمــا قــررت املدعــى عليهــا القناعــة وأمــا‬\n‫املدعيــة فعدمهــا وطلبــت متكينهــا مــن االعتــراض فأفهمتهــا مبراجعــة‬\n‫احملكمــة يــوم االثنــن القــادم لهــا مــن بعــده ثالثــون يومـ ًا تقــدم خاللهــا‬\n‫الئحتهــا االعتراضيــة فــإن لــم تفعــل يســقط حقهــا يف االعتــراض‬\n‫ويكتســب احلكــم الصفــة القطعيــة ‪،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                      ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده ويف هــذا اليــوم االثنــن ‪1433/12/27‬ه ـ فتــح‬\n‫ضبــط القضيــة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف برقــم‬\n‫‪ 332125702‬وتاريــخ ‪1433/12/1‬ه ـ وبرفقهــا قــرار الدائــرة احلقوقيــة‬\n‫الثانيــة رقــم ‪ 33469714‬وتاريــخ ‪1433/11/29‬ه ـ ونــص احلاجــة منــه‬\n‫«وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا‬\n‫لفضيلتــه إلرفــاق صــورة مصدقــة مــن ســجل الصــك رقــم ‪5/100/629‬‬\n‫يف ‪1430/10/17‬هـ وما عليها من تهميشات»أ‪.‬هـ عليه أجيب أصحاب‬\n‫الفضيلــة وفقهــم اهلل بأنــه ال يوجــد للصــك ســجل لكونــه انهــاء وهــو يف‬\n\n\n                                                                                       ‫‪428‬‬\n\f      ‫نظــام احلاســب ال ســجل لــه لــذا جــرى إرفــاق صــورة مصدقــه مــن ضبطــه‬\n                     ‫‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده ويف هــذا اليــوم الثالثــاء ‪1434/2/12‬ه ـ فتــح ضبــط‬\n      ‫القضيــة وقــد وردتنــا املعاملة من محكمة االســتئناف برقم ‪34105994‬‬\n      ‫وتاريــخ ‪1434/1/26‬ه ـ وبرفقهــا قــرار الدائــرة احلقوقيــة الثانيــة رقــم‬\n      ‫‪ 3417343‬وتاريــخ ‪1434/1/20‬ه ـ ونــص احلاجــة منــه «وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلتــه إلجــراء‬\n      ‫املقتضــى الشــرعي حيــال دعــوى املدعيــة وذلــك لســماع بينتهــا إن كان‬\n      ‫لهــا بينــة أو حتليــف املدعــى عليهــا «أ‪.‬ه ـ عليــه أجيــب أصحــاب الفضيلــة‬\n      ‫بأنــي أشــرت ملوجــب ‪ ...‬بحــث هــذه الواقعــة وهــو تكييفهــا بأنهــا دائــرة‬\n      ‫بــن كونهــا عقــدا معلقــا علــى شــرط أو وعــدا وكالهمــا غيــر ملزمــن‬\n      ‫وأن مــن شــرط بحــث الواقعــة القضائيــة أن تكــون منتجــة وهــو غيــر‬\n      ‫متحقــق يف هــذه الدعــوى كمــا قــررت ذلــك مفصــا يف تســبيب احلكــم‬\n      ‫لــذا فلــم يظهــر موجــب إلجــراء ذلــك والرجــوع عــن احلكــم وأمــرت‬\n      ‫بإحلاقــه علــى الصــك وســجله وإعادتــه حملكمــة االســتئناف وصلــى اهلل‬\n                            ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 34230600‬وتاريــخ‬\n      ‫‪1434/2/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪.....‬‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33359710‬وتاريــخ‬\n      ‫‪1433/7/28‬ه ـ ‪ ،‬املتضمــن دعــوى ‪.....‬ضــد ‪ ،.....‬وبدراســة الصــك‬\n\n\n‫‪429‬‬\n\f‫وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                                           ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪430‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":423,"source_page_end":430,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9081de4e238d7b7d1d190e482295f89e460f04f0b91001a336e4d30cd7cb7417","normalized_text_hash":"8febc43940e76e6bb0c912908ab5f173d0f51f24517a45360b88c19e6f34b028","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p423-33359710"},{"id":"3bc949bb-493a-5d04-ba1c-78ae1e03d767","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء منحة أرض -الوعد باإلفراغ -بيع ما ال ميلك - احلكم بإعادة املبلغ وفسخ عقد البيع.","document_number":"33433302","case_number":"333670","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/22","year":"1434","subject":"عقار -شراء منحة أرض -الوعد باإلفراغ -بيع ما ال ميلك - احلكم بإعادة املبلغ وفسخ عقد البيع.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33433302 :‬تاريخه ‪1433/10/22 :‬هـ‬\n                             ‫رقم الدعوى ‪333670 :‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34201062:‬تاريخه‪1434/04/29:‬هـ‬\n\n\n       ‫عقــار ‪ -‬شــراء منحــة أرض ‪ -‬الوعــد باإلفــراغ ‪ -‬بيــع مــا ال ميلــك ‪-‬‬\n                                    ‫احلكــم بإعــادة املبلــغ وفســخ عقــد البيــع‪.‬‬\n\n\n\n\n                         ‫نهي النبي صلى اهلل عليه وسلم عن بيع ما ال ميلك ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــى بأنــه اشــتري مــن املدعــى عليــه أمــر منحــة أرض وأنــه ســلم‬\n       ‫الثمــن للمدعــى عليــه‪ -‬طلــب املدعــى إلــزام املدعــى عليــه بإفــراغ األرض‬\n       ‫لــه‪ -‬أقــر املدعــى عليــه وكالــة مبــا جــاء يف دعــوى املدعــى وقــرر املدعــى‬\n       ‫عليــه وكالــة بــأن أوراق اعتمــاد املنحــة مازالــت لــدى اجلهــات املختصــة‬\n       ‫ومتــى مــا اســتلم موكلــه األوراق فإنــه مســتعد باإلفــراغ للمدعــى‪ -‬قــرر‬\n       ‫املدعــى بأنــه ســأل عــن املعاملــة ولــم يجــد لهــا أي رقــم وطلــب املدعــى‬\n       ‫إلــزام املدعــى عليــه بإعــادة املبلــغ الــذي اســتلمه منــه‪ -‬حيــث أن املدعــى‬\n       ‫عليــه بــاع مــاال ميلــك لــذ صــدر احلكــم بالــزام املدعــى عليــه بإعــادة املبلــغ‬\n       ‫املدعــى بــه للمدعــى‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‪ -‬لوحــظ علــى‬\n       ‫احلكــم مــن محكمــة االســتئناف بأنــه البــد مــن فســخ العقــد البيــع ثــم‬\n       ‫احلكــم بإعــادة املبلــغ‪ -‬اضــاف القاضــي احلكــم بفســخ عقــد البيــع‬\n                               ‫وبطالنــه‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n‫‪431‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 333670‬وتاريــخ ‪1433/03/29‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 338426‬وتاريــخ ‪1433/01/01‬ه ـ ففــي يــوم األربعــاء‬\n‫املوافــق ‪1433/06/18‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 34‬وفيهــا‬\n‫حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وحضــر‬\n‫حلضــوره ‪ ...‬ســعودي اجلنســية حســب الســجل املدنــي رقــم ‪ ...‬بصفتــه‬\n‫وكيــا عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الطائــف‬\n‫رقــم ‪ 18350‬يف ‪1433/3/28‬ه ـ وبســؤال املدعــي عــن دعــواه قــال‬\n‫اشــتريت مــن املدعــى عليــه هــذا احلاضــر منحــة أرض مبوجــب عقــد‬\n‫مبــرم بيننــا وأوعدنــي بإعطائــي األمــر الســامي الكــرمي بعــد شــهر‬\n‫مــن تاريــخ العقــد ‪1431/8/28‬ه ـ ولــم يــويف مبــا أوعدنــي اطلــب الزامــه‬\n‫بإفــراغ هــذه األرض هــذه دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب‬\n‫ا لــذا رفعــت‬  ‫قائــا اطلــب مهلــة لإلجابــة علــى هــذه الدعــوى مفص ـ ً‬\n‫اجللســة ويف جلســة أخــرى حضــر الطرفــان وجــري ســؤال املدعــى عليــه‬\n‫هــل أحضــر إجابــة علــى مــا جــاء يف دعــوى املدعــي فقــال نعــم كل مــا‬\n‫جــاء يف دعــوى املدعــي كلــه صحيــح جملــة وتفصيــا وموكلــي قــد بــاع‬\n‫هــذه األرض بقيمــة ســبعة وثالثــن ألــف وخمســمائة ريــال علــى املدعــي‬\n‫وأوراق اعتمادهــا مازالــت موجــوده يف الديــوان امللكــي العتمادهــا‬\n‫ومتــي مــا أســتلم أوراقهــا فهــو مســتعد بإفراغهــا للمدعــي هكــذا أجــاب‬\n‫وبعــرض ذلــك علــى املدعــي قــال مــا جــاء يف أجابتــه مــن أن أوراق األرض‬\n\n                                                                                   ‫‪432‬‬\n\f      ‫مازالــت يف الديــوان امللكــي فهــذا غيــر صحيــح فأنــا ســئلت عنهــا ولــم‬\n      ‫أجــد لهــا أي رقــم وأطلــب إعــادة مــا اســتلمه املدعــى عليــه أصالــه مــن‬\n      ‫مبالــغ البالــغ ســبعة وثالثــن ألــف وخمســمائة ريــال وبنــاء علــى الدعــوي‬\n      ‫واإلجابــة وحيــث أن املدعــى عليــه قــد بــاع علــى املدعــي مــا ال ميلــك وقــد‬\n      ‫نهــي نبينــا محمــد عليــه الصــاة والســام بيــع املســلم ألخيــه املســلم مــاال‬\n      ‫ميلــك فلجميــع مــا ســبق فقــد حكمــت علــى املدعــى عليــه ‪...‬بــأن يرجــع‬\n      ‫للمدعــي ‪...‬املبلــغ املســلم لــه البالــغ ســبعة وثالثــن ألــف وخمســمائة ريــال‬\n      ‫وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه وكالــه قــرر عــدم‬\n      ‫القناعــة بهــذا احلكــم وطلــب رفعهــا إلــى محكمــة اإلســتئناف بتقــدمي‬\n      ‫الئحــة اعتراضيــة وجــري تســليمه صــوره مــن هــذا احلكــم يف هــذا‬\n      ‫اليــوم وجــري إفهامــه بــأن لــه ثالثــن يــوم تبــدأ مــن هــذا اليــوم وتنتهــي يف‬\n      ‫‪1433/11/21‬ه ـ ويف حــال عــدم تقدميــه الالئحــة يف التاريــخ املذكــور‬\n      ‫أعــاه يســقط حقــه يف االعتــراض ويكتســب هــذا احلكــم الصفــة‬\n      ‫القطعيــة ففهــم ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/10/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫برقــم ‪ 34390235‬يف ‪1434/02/17‬ه ـ وبرفقهــا قــرار املالحظــة رقــم‬\n      ‫‪ 3422764‬يف ‪1434/01/26‬ه ـ املتضمــن وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت إعادتهــا لفضيلــة حاكمهــا‬\n      ‫لكونــه حكــم بــرد املبلــغ ولــم يحكــم بفســخ البيــع فعلــى فضيلتــه‬\n      ‫تضمــن حكمــه بفســخ البيــع أ‪.‬ه ـ عليــه فأجيــب عمــا ذكــره أصحــاب‬\n      ‫الفضيلــة بأنــي أضيــف إلــى مــا حكمــت احلكــم بفســخ البيــع ليكــون‬\n      ‫احلكــم كالتالــي ‪ :‬وبنــاء علــى الدعــوى واإلجابــة وحيــث أن املدعــى‬\n\n\n‫‪433‬‬\n\f‫عليــه قــد بــاع علــى املدعــي مــا ال ميلــك وقــد نهــى نبينــا محمــد عليــه‬\n‫الصــاة والســام بيــع املســلم ألخيــه املســلم مــا ال ميلــك فلجميــع مــا ســبق‬\n‫فقــد حكمــت بفســخ البيــع وبطالنــه وإلــزام املدعــى عليــه ‪...‬بــأن يرجــع‬\n‫للمدعــي ‪...‬املبلــغ املســلم لــه البالــغ ســبعة وثالثــن ألــف وخمســمائة ريــال‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1434/04/01‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا الصــك رقــم ‪ 33433302‬يف ‪1433/10/22‬ه ـ املظهــر عليــه‬\n‫قــرار محكمــة االســتئناف رقــم ‪ 34201062‬يف ‪1434/04/29‬ه ـ‬\n‫املتضمــن املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر وبــاهلل التوفيــق‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                              ‫‪ 1434/05/20‬ه ـ ‪.‬‬\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى احلكــم الصــادر مــن‬\n‫فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد‬\n‫‪ 33433302‬وتاريــخ ‪ 1433/10/22‬هـ ـ واملتضمــن دعــوى‪... /‬ضــد‪/‬‬\n                                            ‫‪...‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق‪ .‬وصلــى اهلل‬\n                       ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n\n                                                                                      ‫‪434‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":431,"source_page_end":434,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0bb788b9f99a001b8f06c264b51c0993e3c3d2344d101caf3653e9d28864baf1","normalized_text_hash":"80813e71fea37ee7fb64458ad170e52b9780e28133a5e9962653253134a38195","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p431-33433302"},{"id":"1c71f34f-2b9e-5edd-8cc0-90c31ef4a5d6","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -تداخل أراضي -ما تنازل به املدعي يف حكم الساقط والساقط ال يعود -تقدير التداخل يف األرض عن طريق قسم اخلبراء -ال يحل مال امرئ مسلم أال بطيب نفس منه -احلكم برد دعوى املدعي وإخاء سبيل املدعى عليه .","document_number":"342935","case_number":"33476125","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/5","year":"1434","subject":"عقار -تداخل أراضي -ما تنازل به املدعي يف حكم الساقط والساقط ال يعود -تقدير التداخل يف األرض عن طريق قسم اخلبراء -ال يحل مال امرئ مسلم أال بطيب نفس منه -احلكم برد دعوى املدعي وإخاء سبيل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك‪ 342935:‬تاريخه‪1434/1/5:‬هـ‬\n                       ‫رقم الدعوى‪33476125:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3443904‬تاريخه‪1434/2/23 :‬هـ‬\n\n\n      ‫عقــار ‪ -‬تداخــل أراضــي ‪ -‬مــا تنــازل بــه املدعــي يف حكــم الســاقط‬\n      ‫والســاقط ال يعــود ‪ -‬تقديــر التداخــل يف األرض عــن طريــق قســم‬\n      ‫اخلبــراء ‪ -‬ال يحــل مــال امــرئ مســلم أال بطيــب نفــس منــه ‪ -‬احلكــم‬\n                         ‫بــرد دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (ال يحــل مــال امــرئ مســلم إال بطيــب‬\n                                                                    ‫نفــس منــه)‪.‬‬\n                                      ‫‪ .2‬القاعدة الفقهية‪ :‬الساقط ال يعود ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه ميلــك قطعــة االرض اململوكــة‬\n      ‫بالصــك الصــادر مــن كتابــة عــدل املدينــة املنــورة ويحدهــا قبلــة املربــع‬\n      ‫رقــم واحــد وســبعون واململــوك للمدعــى عليــه وقــد دخــل علــى أرضــه‬\n      ‫بعــرض متــر وثالثــة وثالثــون ســنتمتر بطــول احلــد وطولــه خمســة‬\n      ‫وعشــرون متــر ًا ويطلــب رفــع يــده عنــه هكــذا ادعــى ‪ -‬أجــاب املدعــى‬\n      ‫عليــه بعــدم املصادقــة علــى الدعــوى ‪ -‬جــرى الكتابــة لقســم اخلبــراء‬\n      ‫لتطبيــق الصكــوك علــى املوقــع فــورد جوابهــم املتضمــن أن صــك‬\n      ‫املدعــي يتداخــل مــع صــك املدعــى عليــه وأن املدعــي قــد تنــازل عــن‬\n\n‫‪435‬‬\n\f‫هــذا اجلــزء املتداخــل وذلــك حســب رخصــة االنشــاء املرفقــة صورتهــا ‪-‬‬\n‫صــادق املدعــي علــى تنازلــه عــن التداخــل محــل الدعــوى لــدى املكتــب‬\n‫الهندســي ودفــع بأنــه وقــع مكره ـ ًا لتتــم إجــراءات اســتخراج رخصــة‬\n‫العمــارة ‪ -‬قــرر املدعــي يف جلســة أخــرى بــأن املدعــى عليــه قــد رفــع‬\n‫يــده عمــا هــو داخــل يف رخصتــه وال يطالبــه بخصوصــه بشــيء ويطالبــه‬\n‫مبــا تنــازل عنــه مكرهــا لــدى املكتــب الهندســي ‪ -‬ومبــا أن املدعــي‬\n‫قــد أقــر أنــه تنــازل عمــا يطالــب بــه وذكــر إكراهــا إن ثبــت فهــو ال‬\n‫يؤثــر علــى تنازلــه والســاقط ال يعــود وبتنازلــه فقــد دخــل املتنــازل يف ملــك‬\n‫غيــره وال يحــل مــال امــرئ مســلم إال بطيــب نفــس منــه ومبــا أن املدعــى‬\n‫عليــه قــد رفــع يــده عمــا تداخــل يف ملــك املدعــي ممــا ســبق اإلشــارة‬\n‫إليــه‪ -‬ملــا تقــدم احلكــم بــرد دعــوى املدعــي ‪ -‬قنــع املدعــى عليــه باحلكــم‬\n‫واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n             ‫الســابعة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫‪.........‬القاضــي يف احملكمــة العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامة باملدينة املنورة‪/‬املســاعد‬\n‫برقــم ‪ 33476125‬وتاريــخ ‪ 1433/07/20‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 331362501‬وتاريــخ ‪ 1433/07/20‬ه ـ ففــي يــوم االحــد املوافــق‬\n‫‪1433/8/25‬هـ حضر ‪ .........‬ســعودي بالســجل املدني رقم ‪.........‬وادعى‬\n‫ا اننــي‬\n       ‫علــى احلاضــر معــه ‪.........‬ســعودي بالســجل املدنــي رقــم ‪.........‬قائـ ً‬\n‫املــك قطعــة االرض املقامــة بهــا عمــارة والواقعــة خــارج بــاب العنبريــة‬\n\n                                                                                        ‫‪436‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":435,"source_page_end":436,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e39d28be68d3a8112de883dcc8bf4c31493db2581cadf1b58826e1294b6a9a1c","normalized_text_hash":"c091d3b329cc747ff7117c8576d872993270fdee02b45e556b73eec718f27177","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p435-342935"},{"id":"2579073c-548e-5bf6-97f7-cd9ae5484a16","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -تنازع حول ملكية عقار -املطالبة برفع يد عن األرض - توف اإلجراءات النظامية -إيقافصك ملكية األرض لم يس الدعوى حلني استكمال اإلجراءات النظامية للصك -وقف الدعوى تعليقي ا -عدم اكتساب صك حجة االستحكام القطعية إال بعد تصديق محكمة اإلستئناف يف حالة وجود اعتراض -التثبت من صحة الصكوك من اجلهات الرسمية .","document_number":"33479865","case_number":"33408392","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/27","year":"1434","subject":"عقار -تنازع حول ملكية عقار -املطالبة برفع يد عن األرض - توف اإلجراءات النظامية -إيقافصك ملكية األرض لم يس الدعوى حلني استكمال اإلجراءات النظامية للصك -وقف الدعوى تعليقي ا -عدم اكتساب صك حجة االستحكام القطعية إال بعد تصديق محكمة اإلستئناف يف حالة وجود اعتراض -التثبت من صحة الصكوك من اجلهات الرسمية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33479865 :‬تاريخه‪1433/12/27 :‬هـ‬\n                   ‫رقم الدعوى‪33408392 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34201067‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n ‫عقــار ‪ -‬تنــازع حــول ملكيــة عقــار ‪ -‬املطالبــة برفــع يــد عــن األرض ‪-‬‬\n ‫ـتوف اإلجــراءات النظاميــة ‪ -‬إيقــاف‬‫صــك ملكيــة األرض لــم يسـ ِ‬\n ‫الدعوى حلني اســتكمال اإلجراءات النظامية للصك ‪ -‬وقف الدعوى‬\n ‫تعليقيـ ًا ‪ -‬عــدم اكتســاب صــك حجــة االســتحكام القطعيــة إال بعــد‬\n ‫تصديــق محكمــة اإلســتئناف يف حالــة وجــود اعتــراض ‪ -‬التثبــت مــن‬\n                               ‫صحــة الصكــوك مــن اجلهــات الرســمية ‪.‬‬\n\n\n\n       ‫‪ .1‬املادة ‪ 2/83‬من نظام املرافعات الشرعية والئحته التنفيذية ‪.‬‬\n ‫‪ .2‬املــادة الرابعــة واخلمســون بعــد املائتــن مــن نظــام املرافعات الشــرعية‬\n                                                       ‫والئحتــه التنفيذية ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه اعتــدى علــى أرضــه ويطلــب‬\n ‫رفــع يــده عــن األرض ‪ -‬حيــث قــام املدعــى عليــه بتعقيــم معظــم أرض‬\n ‫املدعــي معتدي ـ ًا عليهــا ‪ -‬أجــاب املدعــى عليــه باإلنــكار وأنــه قــام‬\n ‫بتعقيــم األرض التــي حتــت يــده واململوكــة لــه مبوجــب صــك شــرعي‬\n ‫وقــد آلــت لــه عــن طريــق الشــراء ‪ -‬أجــاب املدعــي بــأن األرض قــد آلــت‬\n ‫لــه باألحيــاء مبوجــب حجــة االحــكام الصــادرة مــن احملكمــة ‪ -‬باطــاع‬\n\n                                                                                    ‫‪440‬‬\n\f      ‫ناظــر القضيــة علــى صــك ملكيــة املدعــي وجــد أنــه ُصــرف النظــر عــن‬\n      ‫معارضــة البلديــة ولــم يرفــع لالســتئناف وهــذا اإلجــراء إجــراء ناقــص‬\n      ‫غيــر مكتمــل لإلجــراءات النظاميــة وال يكتســب فيــه احلكــم القطعية‬\n      ‫وذلــك وفقـ ًا ملــا جــاء يف املــادة الرابعــة واخلمســن بعــد املائتــن مــن نظــام‬\n      ‫ـاء علــى املــادة الثالثــة‬\n                               ‫املرافعــات الشــرعية والئحتهــا التنفيذيــة ‪ -‬لــذا وبنـ ً‬\n      ‫والثمانــن مــن نظــام املرافعــات الشــرعية ونصهــا (إذا رأت احملكمــة‬\n      ‫تعليــق حكمهــا يف موضــوع الدعــوى علــى الفصــل يف مســألة أخــرى‬\n      ‫يتوقــف عليهــا احلكــم فتأمــر بوقــف الدعــوى ومبجــرد زوال ســبب‬\n      ‫التوقــف يكــون للخصــوم طلــب الســير يف الدعوى)ا‪.‬ه ـ والالئحــة الثانية‬\n      ‫مــن ذات املــادة ونصهــا(إذا أمــر القاضــي بوقــف الدعــوى حســب هــذه‬\n      ‫املــادة أو رفــض طلــب اخلصــوم فيصــدر قــرار ًا بذلــك ويعامــل مــن لــم يقنــع‬\n      ‫مبوجــب تعليمــات التمييــز)‪ -‬احلكــم بإيقــاف الدعــوى حلــن اســتكمال‬\n      ‫املدعــي أصالــة اإلجــراءات النظاميــة وتصديــق متلكــه مــن محكمــة‬\n      ‫االســتئناف ‪ -‬اعتــرض املدعــي علــى احلكــم بالئحــة ‪ -‬صــدق احلكــم‬\n                                                              ‫مــن محكمــة اإلســتئناف ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بينبــع‪ /‬املســاعد برقــم ‪ 33408392‬وتاريــخ ‪1433/06/17‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 331139502‬وتاريــخ ‪ 1433/06/17‬ه ـ‬\n      ‫ففــي يــوم األحــد املوافــق‪ 1433/08/25‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 11 : 30‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n\n‫‪441‬‬\n\f‫ا عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬    ‫رقــم ‪ ...‬بصفتــه وكيـ ً‬\n‫عــدل محافظــة أملــج ‪ 2/5‬وتاريــخ ‪1433/06/18‬ه ـ والتــي تخولــه حــق‬\n‫املرافعــة واملدافعــة بخصــوص األرض الواقعــة يف ينبــع برقــم ‪1960‬‬\n‫وحضــور اجللســات وقبــول احلكــم واالعتــراض عليــه وطلــب اليمــن‬\n‫والتنــازل واالبــراء والقبــض وإقامــة البينــة وحضــر حلضــوره ‪ ...‬ســعودي‬\n‫ا عــن ‪ ...‬مبوجــب‬  ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بصفتــه وكيـ ً‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جده برقم‬\n‫‪ 18439‬وتاريــخ ‪1431/02/26‬ه ـ والتــي تخولــه حــق املرافعــة واملدافعــة‬\n‫وســماع البينــات واجلــرح والتعديــل واإلقــرار واإلنــكار والصلــح والتنــازل‬\n‫ا يف دعــواه إن‬  ‫والقناعــة باحلكــم ورفضــه وادعــى املدعــي وكالــة قائ ـ ً‬\n‫مــن اجلــاري يف ملــك موكلــي األرض الواقعــة يف (‪ )....‬بالكيلــو الســابع‬\n‫شــرق محافظــة ينبــع ومســاحتها(‪ )75,000‬خمســة وســبعون ألــف متــر‬\n‫ويحدهــا مــن الشــمال ‪ ....‬بطــول (‪ )500‬خمســمائة متــر ومــن اجلنــوب ‪....‬‬\n‫بطــول (‪ )500‬خمســمائة متــر ومــن الشــرق ‪ .....‬بطــول (‪ )300‬ثالثمائــة‬\n‫متــر ومــن الغــرب ملــك ألحــد األشــخاص بطــول(‪ )300‬ثالثمائــة متــر‬\n‫وهــي آيلــة إلــى موكلــي باإلحيــاء الشــرعي مبوجــب الصــك الصــادر‬\n‫مــن محكمــة ينبــع مــن القاضــي بهــا الشــيخ ‪ ...‬رئيــس احملكمــة آن‬\n‫ذاك برقــم ‪ 296‬وتاريــخ ‪1400/06/04‬ه ـ وقــد قــام املدعــى عليــه أصالــة‬\n‫باالعتــداء علــى معظــم أرض موكلــي آنفــة الذكــر وعقمهــا أطلــب رفــع‬\n‫يــد املدعــى عليــه أصالــة عــن اجلــزء املتداخــل مــع أرض موكلــي و مــا‬\n‫ال هكــذا‬  ‫أقامــه عليهــا مــن عقــوم وعــدم التعــرض مللــك موكلــي مســتقب ً‬\n‫ادعــى وبعــرض دعــوى املدعــي وكالــة علــى املدعــى عليــه وكالــة‬\n‫أجــاب بقولــه مــا جــاء يف دعــوى املدعــي وكالــة غيــر صحيــح وموكلــي‬\n\n\n                                                                                  ‫‪442‬‬\n\f      ‫لــم يعقــم غيــر أرضــه التــي حتــت يــده واململوكــة لــه مبوجــب الصــك‬\n      ‫الشــرعي الصــادر مــن كتابــة عــدل ينبــع برقــم ‪ 3/4/839‬وتاريــخ‬\n      ‫‪1410/05/04‬ه ـ واحملــدودة مــن اجلنــوب األســفلت بطــول (‪)1,200‬‬\n      ‫ألــف ومئتــا متــر وشــرق ًا مزرعــة ‪ ...‬بطــول (‪ )1,500‬ألــف وخمســمائة‬\n      ‫متــر وشــما ًال ‪ ...‬بطــول (‪ )1,200‬ألــف ومئتــا متــر وغرب ـ ًا ملــك ‪ ...‬بطــول‬\n      ‫(‪ )1,500‬ألــف وخمســمائة متــر وهــي آيلــة إلــى موكلــي بالشــراء مــن‬\n      ‫‪ ...‬مبوجــب التهميــش املظهــر علــى الصــك هكــذا أجــاب ثــم ســألت‬\n      ‫املدعــي وكالــة عــن صــك متلــك موكلــه لــأرض املدعــى بهــا فأبــرز‬\n      ‫الصــك املذكــور بعاليــه وباالطــاع عليــه وجدتــه كمــا ذكــر املدعــي‬\n      ‫وكالــة وســألت املدعــى عليــه وكالــة عــن صــك متلــك موكلــه لــأرض‬\n      ‫التــي دفــع بتملكهــا فأبــرز الصــك املذكــور بعاليــه وباالطــاع عليــه‬\n      ‫وجدتــه كمــا ذكــر املدعــى عليــه وكالــة ثــم أمــرت بالكشــف علــى‬\n      ‫كال الصكــن بإرســالهما إلــى مصدريهمــا ويف جلســة أخــرى لــدي‬\n      ‫أنــا ‪ ...‬القاضــي باحملكمــة العامــة بينبــع والقائــم بعمــل الشــيخ ‪ ...‬ففــي‬\n      ‫هــذا اليــوم الثالثــاء املوافــق ‪1433/10/10‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫التاســعة صباحــا وفيهــا حضــر وكيــل املدعــي ووكيــل املدعــى عليــه‬\n      ‫وقــد وردنــا خطــاب كاتــب العدل رقــم ‪ 33/7/5/68‬يف ‪1433/9/23‬هـ‬\n      ‫بــأن الصــك رقــم ‪ 3/4/839‬يف ‪1410/5/4‬ه ـ الصــادر مــن كاتــب‬\n      ‫العــدل ‪ ...‬ســاري املفعــول واملفــرغ ‪ ...‬ثــم طلبــت مــن املدعــي توضيــح اجلــزء‬\n      ‫املعتــدى عليــه ووضــع كروكــي لــه وبيــان أطوالــه وحــدوده ويف جلســة‬\n      ‫أخــرى لــدي أنــا ‪ ....‬حضــر الطرفــان وجــرى ســؤال املدعــي وكالــة هــل‬\n      ‫أحضــر املطلــوب منــه يف اجللســة املاضيــة فأجــاب بقولــه إننــي لــم أســتطع‬\n      ‫إحضــار املطلــوب وأطلــب مهلــة جللســة قادمــة فأجبتــه لطلبــه وأفهمتــه‬\n\n\n‫‪443‬‬\n\f‫بــأن املطلــوب منــه جــزء ال يتجــزأ مــن دعــواه فــإن لــم يحضــره يف اجللســة‬\n‫القادمــة فأعتبــره غيــر محــرر لدعــواه ويصــرف النظــر عــن طلبــه ففهــم‬\n‫ذلــك وقــد ســبق الكتابــة لرئيــس قســم الســجالت باحملكمــة باخلطــاب‬\n‫ذي الرقــم ‪ 331613801‬وتاريخ‪1433/08/27‬ه ـ لإلفــادة عــن ســريان‬\n‫مفعــول الصــك رقــم ‪ 514‬وتاريــخ ‪1400/05/03‬ه ـ مــن عدمهــا فوردنــا‬\n‫خطابهــم ذي الرقــم ‪ 331613801‬وتاريــخ ‪1433/08/27‬ه ـ املتضمــن‬\n‫«نفيدكــم أنــه بالبحــث يف ســجالت اإلدارة لدينــا تبــن أن الصــك‬\n‫مطابــق لســجله فقط)ا‪.‬ه ـ ثــم جــرى اطالعــي علــى صــك ملكيــة‬\n‫مــوكل املدعــي الصــادر مــن احملكمــة العامــة بينبــع برقــم ‪ 514‬وتاريــخ‬\n‫‪1400/06/04‬ه ـ املتضمــن ثبــوت متلــك ‪ ....‬لكافــة املزرعــة املذكــورة‬\n‫واحملــدودة واملوضحــة مســاحتها بعاليــه ثبوتـ ًا صحيحـ ًا شــرعي ًا وصــرف‬\n‫النظــر عــن معارضــة البلديــة ا‪.‬ه ـ ومبــا أن صــك حجــة االســتحكام‬\n‫املذكــور آنف ـ ًا معتــرض عليــه مــن البلديــة وقــد صــرف النظــر عــن‬\n‫معارضتهــا ولــم يرفــع احلكــم إلــى محكمــة االســتئناف لتصديقــه‬\n‫وهــذا اإلجــراء إجــراء ناقــص غيــر مكتمــل لإلجــراءات النظاميــة وال‬\n‫يكتســب فيــه احلكــم القطعيــة وذلــك وفق ـ ًا ملــا جــاء يف املــادة الرابعــة‬\n‫واخلمســن بعــد املائتــن مــن نظــام املرافعــات الشــرعية والئحتهــا‬\n‫ـاء علــى املــادة الثالثــة والثمانــن مــن نظــام املرافعــات‬‫التنفيذيــة لــذا وبنـ ً‬\n‫الشــرعية ونصهــا «إذا رأت احملكمــة تعليــق حكمهــا يف موضــوع‬\n‫الدعــوى علــى الفصــل يف مســألة أخــرى يتوقــف عليهــا احلكــم فتأمــر‬\n‫بوقــف الدعــوى ومبجــرد زوال ســبب التوقــف يكــون للخصــوم طلــب‬\n‫الســير يف الدعوى)ا‪.‬ه ـ والالئحــة الثانيــة مــن ذات املــادة ونصهــا(إذا أمــر‬\n‫القاضــي بوقــف الدعــوى حســب هــذه املــادة أو رفــض طلــب اخلصــوم‬\n\n\n                                                                                          ‫‪444‬‬\n\f      ‫فيصــدر قــرار ًا بذلــك ويعامــل مــن لــم يقنع مبوجــب تعليمــات التمييز)ا‪.‬هـ‬\n      ‫فقــد قــررت إيقــاف الدعــوى حلــن اســتكمال املدعــي أصالــة اإلجــراءات‬\n      ‫النظاميــة وتصديــق متلكــه مــن محكمــة االســتئناف وبعــرض ذلــك علــى‬\n      ‫املدعــي وكالــة قــرر عــدم قناعتــه بــه وطلــب االســتئناف مســتعد ًا بتقــدمي‬\n      ‫الئحــة اعتراضيــة فأجبتــه لطلبــه وأفهمتــه بــأن عليــه مراجعــة احملكمــة‬\n      ‫خــال عشــرة أيــام الســتالم نســخة مــن القــرار ومــن ثــم تقــدمي الئحتــه‬\n      ‫االعتراضيــة خــال ثالثــن يومـ ًا مــن تاريــخ االســتالم ففهــم ذلــك وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف ‪ 1433/11/28‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى احلكــم الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ...‬باحملكمــة العامــة بينبــع واملســجل بعــدد ‪33479865‬‬\n      ‫وتاريــخ ‪ 1433/12/27‬هـ ـ واملتضمــن دعــوى‪ ... /‬ضــد‪ ... /‬واحملكــوم‬\n      ‫فيــه مبــا دون باطنــه وبدراســة احلكــم وصــورة ضبطــه تقــررت املوافقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                       ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪445‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":440,"source_page_end":445,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"84a0cad1648f9c111fb36a18316ad7f3b356913662050d9c2ba8fdc5acf928c8","normalized_text_hash":"fd54d77bb952ad29fa9ff81bb8241875c4d2b37440c201be0f3a35f1534aa01c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p440-33479865"},{"id":"092e2bb6-bf92-5249-8590-36f964995025","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء عقار باألقساط -مماطلة املدعى عليه يف سداد املبلغ املتبقي -النص يف عقد البيع أنه يف حالة تأخر القسط أكثر من ثالثة أشهر فإن البيع يعتبر الغيا وتكون األقساط املدفوعة مقابل اإليجار -صرف النظر عن دعوى املدعى واخاء سبيل املدعى عليه","document_number":"34169935","case_number":"32540968","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة وبن على املعاملة احملالة لنا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/23","year":"1434","subject":"عقار -شراء عقار باألقساط -مماطلة املدعى عليه يف سداد املبلغ املتبقي -النص يف عقد البيع أنه يف حالة تأخر القسط أكثر من ثالثة أشهر فإن البيع يعتبر الغيا وتكون األقساط املدفوعة مقابل اإليجار -صرف النظر عن دعوى املدعى واخاء سبيل املدعى عليه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34169935 :‬تاريخه ‪1434/3/23 :‬هـ‬\n                  ‫رقم الدعوى ‪32540968 :‬‬\n             ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34297874:‬تاريخه‪1434/08/15:‬هـ‬\n\n\n‫عقــار‪ -‬شــراء عقــار باألقســاط‪ -‬مماطلــة املدعــى عليــه يف ســداد املبلــغ‬\n‫املتبقــي‪ -‬النــص يف عقــد البيــع أنــه يف حالــة تأخــر القســط أكثــر مــن‬\n‫ثالثــة أشــهر فــإن البيــع يعتبــر الغيــا وتكــون األقســاط املدفوعــة مقابــل‬\n‫اإليجــار‪ -‬صــرف النظــر عــن دعــوى املدعــى واخــاء ســبيل املدعــى عليــه‬\n                                                            ‫مــن هــذه الدعــوى‬\n\n\n\n        ‫‪ -1‬قول النبي صلى اهلل عليه وسلم ( املسلمون على شروطهم )‬\n‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم ( البينــة علــى املدعــي واليمــن‬\n                                                                ‫علــى مــن أنكــر)‬\n‫‪ -3‬قــال البهوتــي رحمــة اهلل يف كشــاف القنــاع (وإن قــال البائــع ان‬\n‫بعتــك تنقدنــي الثمــن الــى ثالثــة أيــام أو إلــى مــدة معلومــة أقــل مــن‬\n‫ذلــك أو أكثــر وإال فــا بيــع بيننــا صــح البيــع وهــو قــول عمــر كشــرط‬\n‫اخليــار ويفســخ البيــع إن لــم يفعــل أي إن لــم ينقــده املشــترى الثمــن يف‬\n                                                                            ‫املــدة)‬\n                                  ‫‪ -4‬املادة ‪ 55‬من نظام املرافعات الشرعية‬\n\n\n\n\n                                                                                       ‫‪446‬‬\n\f      ‫حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه ووردت إفــادة رئيــس‬\n      ‫املركــز بعــدم جتــاوب املدعــى عليــه لــذا قــرر القاضــي الســير يف نظــر‬\n      ‫الدعــوى غيابي ـ ًا بنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية‪-‬‬\n      ‫ادعــى املدعــى وكالــة بــأن موكلــه اشــترى مــن املدعــى عليــه العقــار‬\n      ‫اململــوك لــه ( ذكــر موقــع العقــار ومســتند التملــك ) مببلــغ قــدره مائــه‬\n      ‫وتســعون ألــف ريــال وذلــك بتاريــخ ‪14320/4/1‬هــ‪ ،‬علــى أقســاط‬\n      ‫شــهرية‪ -‬دفــع موكلــه مائــه وأربعــن ألــف ريــال وتبقــي خمســون ألــف‬\n      ‫ريــاال‪ -‬أصبــح املدعــى عليــه مياطلــه يف اســتالم املبلــغ املتبقــي‪ -‬طلــب‬\n      ‫املدعــى وكالــة إلــزام املدعــى عليــه بإفــراغ العقــار ملوكلــه واســتالم‬\n      ‫باقــي القيمــة‪ -‬حضــر املدعــى عليــه وكالــه وصــادق علــى الدعــوى ودفــع‬\n      ‫بــأن املدعــى هــو مــن ماطــل يف ســداد األقســاط يف حينهــا بدايــة مــن‬\n      ‫القســط الــذي حــل بتاريــخ ‪1425/11/30‬ه ـ ومــا بعــده‪ -‬تضمــن العقــد‬\n      ‫شــرط ًا أنــه يف حــال تأخــر القســط أكثــر مــن ثالثــة أشــهر فــان البيــع‬\n      ‫يعتبــر الغي ـ ًا وتكــون األقســاط التــي دفعــت مقابــل إيجــار شــهري‬\n      ‫لكــون املدعــى ســاكن يف العقــار منــذ ذلــك التاريــخ‪ -‬طلــب املدعــى‬\n      ‫عليــه وكالــه فســخ عقــد البيــع وبطالنــه وإلغائــه وإلــزام املدعــى بدفــع‬\n      ‫اإليجــار الواجــب عليــه مــن تاريــخ ‪1425/11/30‬هــ‪ -‬أجــاب املدعــى‬\n      ‫وكالــه بــأن الشــرط املذكــور وان مت ذكــره يف العقــد إال أنــة يعتبــر‬\n      ‫شــرط ًا فاســد ًا ألنــه يحــول البيــع الــذي مت صحيح ـ ًا إلــى إيجــار فيبطــل‬\n      ‫الشــرط ويصــح البيــع‪ -‬قــرر املدعــى أصالــة أن آخــر قســط دفعــه بتاريــخ‬\n      ‫‪1425/10/30‬ه ـ وحصلــت لــه ظــروف وتأخــر يف دفــع قســطني ورفــض‬\n\n‫‪447‬‬\n\f‫البائــع أخــذ املبلــغ بعــد ذلــك‪ -‬جــرى إفهــام املدعــى أصالــة بــأن لــه ميــن‬\n‫املدعــى عليــه علــى امتناعــه عــن اخــذ املبلــغ احلــال يف وقتــه احملــدد فقــال‬\n‫ال أرض بيمينــه‪ -‬لقولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم‬\n‫) وقولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــى واليمــن علــى مــن‬\n‫أنكــر) فقــدر صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــى وأخلــى‬\n‫ســبيل املدعــى عليــه مــن هــذه الدعــوى وأفهــم املدعــى بــأن له ميــن املدعى‬\n‫عليــه متــى مــاراد كمــا أفهــم املدعــى عليــه بــأن لــه مطالبــة املدعــي‬\n‫بأجــره العقــار بدعــوى مســتقلة بعــد اكتســاب احلكــم القطعيــة‪ -‬لــم‬\n‫يقنــع املدعــى باحلكــم‪ -‬لوحــظ علــى احلكــم مــن محكمــة االســتئناف‬\n‫مبالحظــات أهمهــا أنــه ينبغــي بحــث مســألة أثــر ذلــك الشــرط يف صحــة‬\n‫عقــد البيــع‪ -‬أجــاب القاضــي بــأن اشــتراط البائــع علــى املشــتري بأنــه اذا‬\n‫لــم يســلمه ثمــن البيــع يف مــدة محــدودة وإال فــا بيــع بينهمــا اشــتراط‬\n‫صحيــح ونقــل عــن البهوتــي رحمــة اهلل كالمـ ًا يف ذلــك‪ -‬صــدق احلكــم‬\n                                                       ‫مــن محكمــة االســتئناف‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n‫ـاء‬\n‫فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة وبنـ ً‬\n‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n‫املكرمة برقم ‪ 32540968‬وتاريخ ‪1432/11/19‬هـ املقيدة باحملكمة‬\n‫برقــم ‪ 321477680‬وتاريــخ ‪1432/11/19‬ه ـ ففــي يــوم األربعــاء‬\n‫‪1433/2/10‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباح ـ ًا للنظــر يف‬\n‫دعــوى ‪...‬ضــد ‪ ...‬وفيهــا حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل‬\n\n                                                                                        ‫‪448‬‬\n\f      ‫املدنــي رقــم ‪...‬بالوكالــة عــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة مبكــة‬\n      ‫املكرمــة برقــم ‪ 32899‬يف ‪1432/11/17‬ه ـ واملخــول لــه يف الوكالــة‬\n      ‫حــق إقامــة وســماع عمــوم الدعــاوي واملطالبــات املقامــة منــه أو ضــده ويف‬\n      ‫املرافعــة واملدافعــة ومراجعــة الدوائــر احلكوميــة واحملاكــم الشــرعية‬\n      ‫وحضــور اجللســات وتقــدمي البينــات وســماع احلكــم وقبولــه والقناعــة بــه‬\n      ‫مــن عدمهــا ويف اجلــرح والتعديــل ‪ ...‬الــخ ولــم يحضــر املدعــى عليــه وال مــن‬\n      ‫ميثلــه بوكالــة شــرعية وقــد وردنــا مــن رئيــس مركــز جعرانــة اخلطــاب‬\n      ‫رقــم ‪ 201/8/1‬يف ‪1433/1/1‬ه ـ املتضمــن بــأن املدعــى عليــه ‪...‬غيــر‬\n      ‫متجــاوب حســب إقــرار منــدوب املركــز املرفــق وباالطــاع علــى إقــرار‬\n      ‫املنــدوب وجــد أنــه يتضمــن بــأن املدعــى عليــه اســتعد باملراجعــة ولــم‬\n      ‫يراجــع وهــذا يــدل علــى عــدم جتاوبــه وكان ذلــك بعــد تكــرار إبالغــه‬\n      ‫للمــرة الثالثــة أ‪-‬ه ـ ومرفــق ذلــك يف املعاملــة وحيــث األمــر مــا ذكــر‬\n      ‫ولعــدم جتــاوب املدعــى عليــه لــذا فقــد قــررت النظــر يف القضيــة ضــده‬\n      ‫غيابيـ ًا حســب املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية‬\n      ‫ا ‪-:‬‬ ‫ولوائحهــا التنفيذيــة وبســؤال املدعــي وكالــة عــن دعــواه ادعــى قائـ ً‬\n      ‫إن موكلــي قــد اشــترى مــن املدعــى عليــه العقــار اململــوك لــه والواقــع يف‬\n      ‫اجلعرانــة مبكــة املكرمــة مبوجــب الصــك الصــادر برقــم ‪1/203/62‬‬\n      ‫يف ‪1414/1/9‬ه ـ وال أعلــم مصــدره مببلــغ وقــدره مائــة وتســعون ألــف‬\n      ‫ريــال وذلــك بتاريــخ ‪1420/4/1‬ه ـ علــى أقســاط شــهرية بواقــع ألفــن‬\n      ‫وخمســمائة ريــال ملــدة ســنة ثــم ألفــي ريــال شــهري ًا حتــى نهايــة املبلــغ وقــد‬\n      ‫دفــع للمدعــى عليــه مبلغـ ًا وقــدره مائــة وأربعــون ألــف ريــال وتبقــى يف ذمــة‬\n      ‫موكلــي لــه خمســون ألــف ريــال وقــد أصبــح مياطــل يف اســتالم املبلــغ‬\n\n\n‫‪449‬‬\n\f‫ا أطلــب إلــزام املدعــى‬‫وموكلــي مســتعد بدفــع املبلــغ املتبقــي لــه كامـ ً‬\n‫عليــه بإفــراغ العقــار لــي واســتالم باقــي قيمتــه هــذه دعــواي ولطلــب‬\n‫حضــور املدعــى عليــه وإلحضــار املدعــي وكالــة بيناتــه علــى صحــة‬\n‫دعــواه وحلضــور املدعــي أصالــة ثــم إنــه يف يــوم االثنــن ‪1433/4/26‬ه ـ‬\n‫الســاعة التاســعة والنصــف صباح ـ ًا افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي وكالــة واملدعــي أصالــة ‪......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدني رقم ‪...‬وحضر حلضورهما ‪...‬ا‪ ...‬ســعودي اجلنســية مبوجب الســجل‬\n‫املدنــي رقــم ‪...‬بالوكالــة عــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدني‬\n‫رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة مبكــة‬\n‫املكرمــة برقــم ‪ 7792‬يف ‪1433/2/23‬ه ـ جلــد ‪ 5134‬واملخــول لــه يف‬\n‫الوكالــة حــق مراجعــة الدوائــر احلكوميــة القضائيــة واإلداريــة وحضور‬\n‫اجللســات واملرافعــة واملدافعــة وإحضــار البينــات وتعديلهــا وســماع‬\n‫الشــهود وطلــب حتليــف اليمــن واالعتــراض ‪...‬الــخ وبعــرض دعــوى‬\n‫املدعــي وكالــة علــى املدعــى عليــه وكالــة أجــاب قائ ـاً‪ :‬أطلــب مهلــة‬\n‫للرجــوع ملوكلــي وســؤاله وأجيــب يف اجللســة القادمــة فأجبتــه لطلبــه‬\n‫ورفعــت اجللســة لذلــك ثــم إنــه يف يــوم االثنــن ‪1433/6/23‬ه ـ الســاعة‬\n‫احلاديــة عشــرة والنصــف صباحـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه وكالــة وبســؤال املدعــى عليــه وكالــة اإلجابــة‬\n‫علــى دعــوى املدعــي وكالــة أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي وكالــة‬\n‫يف دعــواه مــن كــون موكلــه اشــترى مــن موكلــي العقــار اململــوك لــه‬\n‫والواقــع يف اجلعرانــه يف مكــة املكرمــة مبوجــب الصــك الصــادر برقــم‬\n‫‪ 1/203/62‬يف ‪1414/1/9‬ه ـ مببلــغ وقــدره مائــة وتســعون ألــف ريــال‬\n‫بتاريــخ ‪1420/4/10‬ه ـ علــى أقســاط شــهرية بواقــع ألفــن وخمســمائة‬\n\n\n                                                                                  ‫‪450‬‬\n\f      ‫ريــال ملــدة ســنة ثــم ألفــي ريــال شــهري ًا حتــى نهايــة املبلــغ وأن موكلــي قــد‬\n      ‫اســتلم منــه حتــى اآلن مبلغـ ًا وقــدره مائــة وأربعــون ألــف ريــال فهــذا كلــه‬\n      ‫صحيــح ولكــن املدعــي أصبــح بعــد ذلــك مياطــل يف ســداد األقســاط‬\n      ‫يف حينهــا بدايــة مــن القســط الــذي حــل بتاريــخ ‪1425/11/30‬ه ـ ومــا‬\n      ‫بعــده وقــد تضمــن العقــد شــرط ًا وهــو أنــه يف حالــة تأخــر القســط أكثــر‬\n      ‫مــن ثالثــة أشــهر فــإن البيــع يعتبــر الغيـ ًا وتكــون األقســاط التــي دفعــت‬\n      ‫مقابــل إيجــار شــهري وذلــك لكونــه ســاكن ًا يف العقــار منــذ ذلــك‬\n      ‫التاريــخ وحتــى اآلن والصــك األساســي يف حوزتــي وباســمي حالي ـ ًا لــذا‬\n      ‫فــإن موكلــي يطلــب احلكــم بفســخ عقــد البيــع وبطالنــه وإلغائــه وإلــزام‬\n      ‫املدعــى عليــه بدفــع اإليجــار الواجــب عليــه مــن تاريــخ ‪1425/11/30‬ه ـ‬\n                      ‫وحتــى اآلن بواقــع ألفــن ريــال شــهري ًا هكــذا أجــاب وقــرر‬\n      ‫احلمــد هلل وحــده وبعــد‪ ،‬ففــي يــوم االثنــن ‪1433/4/26‬ه ـ الســاعة‬\n      ‫التاســعة والنصــف صباح ـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫وكالــة واملدعــي أصالــة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪...‬وحضــر حلضورهمــا ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدني‬\n      ‫رقــم ‪...‬بالوكالــة عــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪...‬مبوجــب الوكالــة الصــادرة مــن كتابة العــدل الثانية مبكة املكرمة‬\n      ‫برقــم ‪ 7792‬يف ‪1433/2/23‬ه ـ جلــد ‪ 5134‬واملخــول لــه يف الوكالــة‬\n      ‫حــق مراجعــة الدوائــر احلكوميــة القضائيــة واإلداريــة وحضــور اجللســات‬\n      ‫واملرافعــة واملدافعــة وإحضــار البينــات وتعديلهــا وســماع الشــهود وطلــب‬\n      ‫حتليــف اليمــن واالعتــراض ‪...‬الــخ وبعــرض دعــوى املدعــي وكالــة‬\n      ‫علــى املدعــى عليــه وكالــة أجــاب قائـاً‪ :‬أطلــب مهلــة للرجــوع ملوكلــي‬\n      ‫وســؤاله وأجيــب يف اجللســة القادمــة فأجبتــه لطلبــه ورفعــت اجللســة لذلك‬\n\n\n‫‪451‬‬\n\f‫إلــى يــوم االثنــن ‪1433/6/23‬ه ـ الســاعة احلاديــة عشــرة صباحـاً‪ ،‬وباهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                              ‫يف ‪1433/4/26‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ ،‬ففــي يــوم االثنــن ‪1433/6/23‬ه ـ الســاعة‬\n‫احلاديــة عشــرة والنصــف صباحـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه وكالــة وبســؤال املدعــى عليــه وكالــة اإلجابــة‬\n‫علــى دعــوى املدعــي وكالــة أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي وكالــة‬\n‫يف دعــواه مــن كــون موكلــه اشــترى مــن موكلــي العقــار اململــوك لــه‬\n‫والواقــع يف اجلعرانــه يف مكــة املكرمــة مبوجــب الصــك الصــادر برقــم‬\n‫‪ 1/203/62‬يف ‪1414/1/9‬ه ـ مببلــغ وقــدره مائــة وتســعون ألــف ريــال‬\n‫بتاريــخ ‪1420/4/10‬ه ـ علــى أقســاط شــهرية بواقــع ألفــن وخمســمائة‬\n‫ريــال ملــدة ســنة ثــم ألفــي ريــال شــهري ًا حتــى نهايــة املبلــغ وأن موكلــي قــد‬\n‫اســتلم منــه حتــى اآلن مبلغـ ًا وقــدره مائــة وأربعــون ألــف ريــال فهــذا كلــه‬\n‫صحيــح ولكــن املدعــي أصبــح بعــد ذلــك مياطــل يف ســداد األقســاط‬\n‫يف حينهــا بدايــة مــن القســط الــذي حــل بتاريــخ ‪1425/11/30‬ه ـ ومــا‬\n‫بعــده وقــد تضمــن العقــد شــرط ًا وهــو أنــه يف حالــة تأخــر القســط أكثــر‬\n‫مــن ثالثــة أشــهر فــإن البيــع يعتبــر الغيـ ًا وتكــون األقســاط التــي دفعــت‬\n‫مقابــل إيجــار شــهري وذلــك لكونــه ســاكن ًا يف العقــار منــذ ذلــك‬\n‫التاريــخ وحتــى اآلن والصــك األساســي يف حوزتــي وباســمي حالي ـ ًا لــذا‬\n‫فــإن موكلــي يطلــب احلكــم بفســخ عقــد البيــع وبطالنــه وإلغائــه وإلــزام‬\n‫املدعــى عليــه بدفــع اإليجــار الواجــب عليــه مــن تاريــخ ‪1425/11/30‬ه ـ‬\n‫وحتــى اآلن بواقــع ألفــن ريــال شــهري ًا هكــذا أجــاب وقــرر وبعــرض‬\n‫ذلــك علــى املدعــي وكالــة قــال أطلــب مهلــة للرجــوع ملوكلــي وســؤاله‬\n\n\n                                                                                           ‫‪452‬‬\n\f      ‫وأجيــب يف اجللســة القادمــة فأجبتــه لطلبــه ورفعــت اجللســة لذلــك إلــى‬\n      ‫يــوم الثالثــاء ‪1433/9/12‬ه ـ الســاعة احلاديــة عشــرة صباح ـ ًا ‪ ،‬وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                                      ‫يف ‪1433/6/23‬ه ـ‬\n      ‫وبعــرض ذلــك علــى املدعــي وكالــة قــال أطلــب مهلــة للرجــوع ملوكلــي‬\n      ‫وســؤاله وأجيــب يف اجللســة القادمــة فأجبتــه لطلبــه ثم إنــه يف يوم الثالثاء‬\n      ‫‪1433/9/12‬ه ـ الســاعة احلاديــة عشــرة صباحــا افتتحــت اجللســة وفيهــا‬\n      ‫حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة‬\n      ‫شــرعية وكان قــد قــدم املدعــى عليــه وكالــة اعتــذرا عــن حضــور هــذه‬\n      ‫اجللســة لعــدم تواجــده يف مكــة وبســؤال املدعــي وكالــة عمــا وعــد بــه‬\n      ‫يف اجللســة املاضيــة مــن إحضــار رده علــى إجابــة املدعــى عليــه وكالــة‬\n      ‫أبــرز ردا مكونــا مــن ورقتــن ومطبــوع باحلاســب اآللــي ومــؤرخ يف‬\n      ‫‪1433/9/11‬ه ـ وهــذا نصــه ‪ « :‬تقــدم املدعــى عليــه مبذكــرة دفــع مــن‬\n      ‫خاللهــا بــأن العقــد هــو شــريعة املتعاقديــن وبــأن العقــد احلاكــم للعالقــة‬\n      ‫العقديــة بــن الطرفــن حــوى علــى شــرط يقول بأن العقد يعتبر مفســوخا‬\n      ‫والغيــا وال يعمــل بــه ويكــون البيــت املبــاع مؤجــرا علــى املشــتري يف حالة‬\n      ‫عــدم التــزام املشــتري بدفــع ثمــن املنــزل خــال ثالثــة أشــهر‪ (.‬الـ ــرد ) أوال‬\n      ‫‪ :‬املدعــى عليــه ارتكــن علــى شــرط فاســخ لــم يتحقــق فالبيــع صحيــح‬\n      ‫حيــث اســتوفى كافــة شــروطه الشــرعية الالزمــة إلجنــازه مــن إيجــاب‬\n      ‫وقبــول وتراضــي بــن البائــع واملشــتري ووقــع البيــع علــى مــا يجــوز بيعــة‬\n      ‫شــرعا وال توجــد شــائبة تشــوب البيــع‪ .‬ثانيــا ‪ :‬املشــتري هــو مــن جلــأ إلــى‬\n      ‫القضــاء الشــرعي إلجبــار البائــع علــى إكمــال العقــد وال توجــد قرينــة‬\n      ‫تثبــت أن املدعــي امتنــع عــن تســليم باقــي ثمــن البيــت حيــث قــام بســداد‬\n\n\n‫‪453‬‬\n\f‫مبلــغ مائــة وأربعــون ألــف ريــال مــن إجمالــي ثمــن األرض والبائــع هــو مــن‬\n‫رفــض اســتالم باقــي املبلــغ‪ .‬ثالثــا ‪ :‬مــن جلــأ إلــى القضــاء الشــرعي هــو‬\n‫املشــتري وليــس البائــع ومــن ثــم فــا ميكــن للبائــع أن يطلــب االعتــداد‬\n‫بالتأخــر عــن إكمــال باقــي ثمــن املنــزل ألنــه لــو كان حريصــا علــى‬\n‫ذلــك لــكان هــو مــن بــدر باللجــوء للقضــاء الشــرعي طالبـ ًا إعمــال ذلــك‬\n‫الشــرط ولكــن مــن جلــأ للقضــاء هــو املشــتري طالبــا إلــزام البائــع بعــدم‬\n‫املماطلــة يف اســتالم باقــي قيمــة املنــزل وإلــزام املالــك باإلفــراغ الشــرعي‬\n‫للمنــزل مــع مالحظــة أن مــا قــام بــه موكلــي مــن صيانة وبنــاء تقدر مبائة‬\n‫ون‬ ‫وخمســن ألــف ريــال‪ .‬رابعــا ‪ :‬قو ُلــه ص َّلــى اهلل عليــه وسـلَّم‪ْ (( :‬ال ُْسـل ُِم َ‬\n    ‫ا ًال )) ‪ ،‬وقــولُ‬    ‫امــا‪َ ،‬أ ْو َحـ َّـر َم َح ـ َ‬\n                                                        ‫وطه ِْم‪ِ ،‬إال َشـ ْـر ًطا َأ َحــلَّ َح َر ً‬\n                                                                                                  ‫َع َلــى ُشـ ُـر ِ‬\n ‫ـروط ))‪ .‬فهــذا يــدلُّ‬      ‫الشـ ِ‬     ‫ـوق عنـ َـد ُّ‬‫قاطـ ُـع احلقـ ِ‬ ‫اهلل عنــه‪َ (( :‬م ِ‬  ‫رضــي ُ‬    ‫عمـ َـر ِ‬\n‫ـف‬    ‫ـزوم الوفــا ِء بهــا‪ ،‬مــا لــم ُتخا ِلـ ِ‬  ‫الص َّحـ ُة ولـ ُ‬\n                                                                   ‫ـروط ِّ‬  ‫الشـ ِ‬    ‫علــى أن األصــلَ يف ُّ‬\n‫الشــريع َة والشــرط الــذي يحتــج بــه املدعــى عليــه البائــع هــو شــرط فاســد‬                             ‫َّ‬\n‫كونــه يحــول البيــع الــذي مت صحيحــا إلــى إيجــار فيبطل الشــرط ويصح‬\n‫البيــع‪ .‬لــذا وبنــاء علــى كل مــا تقــدم نلتمــس احلكــم بإلــزام البائــع‬\n‫باســتالم باقــي الثمــن وقــدرة خمســون ألــف ريــال وإلزامــه باإلفــراغ‬\n‫الشــرعي للمنــزل» مقدمــه املدعــي وكالــة وحلضــور املدعــى عليــه أو‬\n‫وكيلــه فقــد رفعــت اجللســة ثــم إنــه يف يــوم الثالثــاء ‪1433/12/28‬ه ـ‬\n‫الســاعة العاشــرة صباحـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة‬\n‫واملدعــي أصالــة واملدعــى عليــه وكالــة واملدعــى عليــه أصالــة ‪...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وقــد جــرى منــي االطــاع علــى‬\n‫عقــد املبايعــة املبــرم بــن الطرفــن برقــم ‪ 54‬يف ‪1420/4/10‬ه ـ مطبــوع‬\n‫علــى ورق تابــع ملكتــب ‪...‬للخدمــات العقاريــة فوجــد يتضمــن بيــع املدعــى‬\n\n\n                                                                                                                       ‫‪454‬‬\n\f      ‫عليــه ‪ ...‬علــى املدعــي ‪...‬عقــاره الواقــع يف اجلعرانــة اململــوك لــه مبوجــب‬\n      ‫الصــك رقــم ‪ 1/203/62‬يف ‪1414/1/9‬ه ـ مببلــغ وقــدره مائــة وتســعون‬\n      ‫ألــف ريــال علــى أقســاط شــهرية بواقــع ألفــن وخمســمائة ريــال شــهري ًا‬\n      ‫ا وقــد‬ ‫ملــدة ســنة والباقــي ألفــن ريــال شــهري ًا حتــى نهايــة املبلــغ كام ـ ً‬\n      ‫تضمــن العقــد شــرطان همــا‪ -1 :‬عــدم اإلفــراغ إال بعــد التســديد ‪ -2‬إذا‬\n      ‫تأخــر القســط أكثــر مــن ثالثــة أشــهر فيعتبــر البيــع الغي ـ ًا واألقســاط‬\n      ‫التــي دفعــت مقابــل إيجــار شــهري ويف آخــرة توقيــع البائــع وبصمــة إبهــام‬\n      ‫املشــتري وشــهادة كل مــن ‪...‬و‪...‬أ‪.‬ه ـ مرفــق صــورة منــه يف املعاملــة‬\n      ‫وبعــرض العقــد علــى املدعــي أصالــة قــال العقــد صحيــح وقــد بصمــت‬\n      ‫عليــه هكــذا قــرر وبســؤاله هــل أنــت حالي ـ ًا ســاكن يف العقــار؟ فقــال‬\n      ‫نعــم ســاكن فيــه هكــذا قــرر وبســؤال املدعــى عليــه وكالــة عــن‬\n      ‫صــك العقــار محــل الدعــوى أبــرز صــورة منــه وهــو صــادر مــن كتابــة‬\n      ‫العــدل األولــى مبكــة املكرمــة برقــم ‪ 1/203/62‬يف ‪1414/1/9‬ه ـ‬\n      ‫فوجــد يتضمــن متلــك ‪ ...‬للعقــار املوصــوف باطنــه والواقــع يف اجلعرانــة‬\n      ‫شــرق مســجد ‪ ...‬ومرفــق صــورة منــه يف املعاملــة وبســؤال املدعــي متــى‬\n      ‫آخــر قســط قمــت بدفعــه للمدعــى عليــه؟ فقــال أخــر قســط هــو بتاريــخ‬\n      ‫‪1425/10/30‬ه ـ ومــا بعــده لــم يتــم دفعــه هكــذا قــرر وبســؤاله عــن‬\n      ‫ســبب عــدم دفعــه باقــي األقســاط التــي حلــت؟ فقــال حصــل لــي ظــرف‬\n      ‫وتأخــرت يف دفــع بعــض األقســاط وعنــد ذهابــي لدفعهــا رفــض املدعــى‬\n      ‫عليــه ذلــك هكــذا قــرر وبســؤاله كــم األقســاط التــي قمــت بالتأخــر‬\n      ‫يف دفعهــا يف حينهــا؟ فقــال شــهران فقــط ورفــض البائــع أخــذ املبلــغ بعــد‬\n                                                                     ‫ذلــك هكــذا قــرر‬\n      ‫احلمد هلل وحده وبعد ففي يوم الثالثاء‪1434/3/17‬هـ الســاعة العاشــرة‬\n\n\n‫‪455‬‬\n\f‫والنصــف صباحـ ًا افتتحــت اجللســة وفيها حضر املدعــي وكالة واملدعي‬\n‫أصالــة واملدعــى عليــه وكالــة واملدعــى عليــه أصالــة فجــرت محاولــة‬\n‫الصلــح بــن الطرفــن فلــم يصطلحــا وكان قــد جــرت الكتابــة منــي‬\n‫لرئيــس كتابــة العــدل األولــى مبكــة املكرمــة باخلطــاب رقــم ‪341355‬‬\n‫يف ‪1434/1/3‬ه ـ مــن أجــل االستفســار عــن الصــك رقــم ‪ 1/203/62‬يف‬\n‫‪1414/1/9‬هـ فوردنا اجلواب برقم ‪ 345104‬يف ‪1434/1/19‬هـ مفاده ‪:‬‬\n‫بأن صورة الصك رقم ‪ 1/203/62‬يف ‪1414/1/19‬هـ مطابقة لســجلها‬\n‫وســارية املفعــول حتــى تاريخــه أ‪.‬ه ـ عنــد ذلــك أفهمــت املدعــي أصالــة بأن‬\n‫لــه ميــن املدعــى عليــه علــى امتناعــه عــن أخــذ املبلــغ احلــال يف وقته احملدد‬\n‫فقــال ‪ :‬ال أرضــى بيمينــه فجــرى ســؤال الطرفــن هــل لديكمــا مــا‬\n‫تريــدان إضافتــه ؟ فقــاال ‪ :‬ليــس لدينــا ســوى مــا قدمنــاه ونطلــب الفصــل‬\n‫يف القضيــة هكــذا قــررا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وبعــد دراســة القضيــة وتأملهــا وبعــد االطــاع علــى العقــد املبــرم بــن‬\n‫الطرفــن برقــم ‪ 54‬يف ‪1420/4/10‬ه ـ واملتضمــن شــرط بأنــه إذا تأخــر‬\n‫القســط أكثــر مــن ثالثــة أشــهر فيعتبــر البيــع الغي ـ ًا واألقســاط التــي‬\n‫دفعــت مقابــل إيجــار شــهري ونظــرا ملصادقــة الطرفــن عليــه وإلقــرار‬\n‫املدعــي بتأخــره عــن ســداد بعــض األقســاط يف وقتهــا احملــدد ولقــول‬\n‫النبــي صلــى اهلل عليــه وســلم ‪ « :‬املســلمون علــى شــروطهم « ومبــا أنــه ال‬\n‫بينــة للمدعــي علــى امتنــاع املدعــى عليــه علــى اســتالم بعــض األقســاط‬\n‫يف وقتهــا احملــدد ولــم يــرض بيمــن املدعــى عليــه ولقــول النبــي صلــى‬\n‫اهلل عليــه وســلم ‪ « :‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر «‬\n‫لذلــك كلــه فقــد صرفــت النظــر عــن دعــوى املدعــي وأخليــت ســبيل‬\n‫املدعــى عليــه مــن هــذه الدعــوى وبذلــك حكمــت وأفهمــت املدعــي بــأن‬\n\n\n                                                                                        ‫‪456‬‬\n\f      ‫لــه ميــن املدعــى عليــه متــى مــا أراد كمــا أفهمــت املدعــى عليــه بــأن لــه‬\n      ‫مطالبــة املدعــي بأجــرة العقــار بدعــوى مســتقلة بعــد اكتســاب احلكــم‬\n      ‫القطعيــة‪ ،‬وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n      ‫بــه واملدعــي عدمهــا وطلــب االســتئناف بالئحــة اعتراضيــة فجــرى‬\n      ‫إفهامــه بــأن عليــه التقــدم للمحكمــة يــوم األحــد القــادم ‪1434/3/22‬ه ـ‬\n      ‫الســتالم نســخة مــن صــك احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن‬\n      ‫يومــا مــن التاريــخ املذكــور وإذا لــم يتقــدم بذلــك خــال املــدة املذكــورة‬\n      ‫فسيســقط حقــه بطلــب االســتئناف وسيكتســب احلكــم القطعيــة‪،‬‬\n      ‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم‪ .‬حــرر يف ‪1434/3/17‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬ففــي يــوم األحــد ‪1434/7/16‬ه ـ افتتحــت‬\n      ‫اجللســة وكان قــد جــرى منــي بعــث املعاملــة حملكمة االســتئناف مبكة‬\n      ‫املكرمــة باخلطــاب رقــم ‪ 321477680‬يف ‪1434/5/21‬ه ـ فعــادت إلــي‬\n      ‫بخطــاب فضيلــة رئيــس محكمــة االســتئناف مبكة املكرمــة املكلف‬\n      ‫رقــم ‪ 321477680‬يف ‪1434/6/20‬ه ـ وبرفقــه قــرار الدائــرة احلقوقيــة‬\n      ‫الثانيــة مبحكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 34243845‬يف‬\n      ‫‪1434/6/18‬ه ـ املتضمــن بعــد املقدمــة مــا نصــه ‪ « :‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه تقــرر باألكثريــة إعادتهــا لفضيلتــه ملالحظــة مــا يلــي‬\n      ‫‪ -1 -:‬بحــث مســألة أثــر ذلــك الشــرط يف صحــة عقــد البيــع ‪ -2‬املدعــي‬\n      ‫ذكــر بأنــه لــم يتأخــر إال عــن شــهرين فــا بــد مــن عــرض ذلــك علــى‬\n      ‫املدعــى عليــه وأخــذ إجابتــه علــى ذلــك ‪ -3‬حكــم فضيلتــه يحتــاج إلــى‬\n      ‫تأمــل وإعــادة نظــر لترجــح جانــب املدعــي نظــر ًا الرتفــاع أســعار العقارات‬\n      ‫يف الوقــت الراهــن ارتفاع ـ ًا فاحش ـ ًا قــد يجعــل بعــض البائعــن يســعون‬\n\n\n‫‪457‬‬\n\f‫إلبطــال البيــع وفســخه طمعـ ًا يف املــال وعلــى فضيلتــه أخــذ هــذا اجلانــب‬\n‫بعــن االعتبــار ‪ -4‬املدعــى عليــه ذكــر يف دفعــه أن العقد يتضمن شــرط ًا‬\n‫وهــو أنــه يف حالــة تأخــر القســط أكثــر مــن ثالثــة أشــهر فــإن البيــع يعتبر‬\n‫الغيــا فــإن املتعــن علــى مصــدر الصــك مطالبــة املدعــى عليــه بصحــة مــا‬\n‫دفــع بــه مــن تأخــر املدعــي عــن ثالثــة أقســاط وســماع بينتــه ويف حــال‬\n‫عــدم وجــود البينــة يفهــم بــأن لــه ميــن املدعــي علــى نفــي مــا دفــع بــه‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ ،،،‬قاضي اســتئناف ‪...‬توقيعه وختمه الشــخصي قاضي اســتئناف ‪...‬‬\n‫توقيعــه وختمــه الشــخصي رئيــس الدائــرة ‪...‬توقيعــه وختمــه الشــخصي‬\n‫موافــق علــى احلكــم « وعليــه أجيــب أصحــاب الفضيلــة وفقنــي اهلل‬\n‫وإياهــم للعلــم النافــع والعمــل الصالــح مبــا يلــي ‪ :‬أوال ‪ :‬اشــتراط البائــع‬\n‫علــى املشــتري بأنــه يف حالــة إذا لــم يســلمه ثمــن املبيــع يف مــدة محــددة‬\n‫وإال فــا بيــع بينهمــا اشــتراط صحيــح وقــد نــص علــى ذلــك العلمــاء‬\n‫رحمهــم اهلل قــال البهوتــي رحمــه اهلل يف كشــاف القنــاع مــا نصــه ‪:‬‬\n‫« وإن قــال البائــع إن بعتــك تنقدنــي الثمــن إلــى ثالثــة أيــام أو إلــى مــدة‬\n‫معلومــة أقــل مــن ذلــك أو أكثــر وإال فــا بيــع بيننــا صــح البيــع وهــو‬\n‫قــول عمــر كشــرط اخليــار وينفســخ البيــع إن لــم يفعــل أي إن لــم ينقــده‬\n‫املشــتري الثمــن يف املــدة « ثانيــا ‪ :‬مفهــوم مــن كالم املدعــى عليــه يف‬\n‫إجابتــه علــى الدعــوى ومــا بعدهــا مــن أن املشــتري الــذي هــو املدعــي قــد‬\n‫تأخــر عــن الســداد أكثــر مــن ثالثــة أشــهر ولذلــك جــرى طلــب البينــة‬\n‫منــه علــى ذلــك ثالثــا ‪ :‬جــرى منــي ســابقا طلــب البينــة مــن املدعــى عليــه‬\n‫علــى أن املدعــي قــد تأخــر عــن ســداد ثالثــة أقســاط وجــرى رصــد بينتــه‬\n‫يف ضبــط القضيــة يف الصفحــة رقــم ( ‪ ) 3‬لذلــك وبعــد اإلجابــة لــم يظهــر‬\n\n\n                                                                                      ‫‪458‬‬\n\f      ‫لــي ســوى مــا أجريتــه وحكمــت بــه‪ ،‬وأمــرت بإحلــاق ذلــك يف صكــه‬\n      ‫وســجله‪ ،‬وإعــادة املعاملــة حملكمــة االســتئناف مبكــة املكرمــة‬\n      ‫إلكمــال الزمهــا‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/7/16‬ه ـ‬\n      ‫تظهيــرات الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف مبكــة‬\n      ‫املكرمــة احلمــد هلل وحــده وبعــد ‪ ،‬فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n      ‫‪ 34169935‬وتاريــخ ‪1434/3/23‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪...‬‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة وأصدرنــا القــرار رقــم‬\n      ‫‪ 34297874‬وتاريــخ ‪1434/8/15‬ه ـ املتضمــن املوافقــة باألكثريــة‬\n      ‫علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬قاضــي اســتئناف ‪ ...‬توقيعــه ختمــه‬\n      ‫الشــخصي قاضــي اســتئناف ‪ ...‬توقيعــه ختمــه الشــخصي رئيــس الدائــرة‬\n      ‫‪...‬توقيعــه ختمــه الشــخصي ولــه وجهــة نظــر أه ـ وحتــى ال يخفــى جــرى‬\n      ‫بيانــه ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه صحبــه‬\n                                                    ‫وســلم حــرر يف ‪1434/9/13‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 321477680‬وتاريــخ‬\n      ‫‪1434/7/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪...‬القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪34169935‬‬\n      ‫وتاريــخ ‪1434/3/23‬ه ـ ‪ ،‬املتضمــن دعــوى ‪ ...‬ضــد ‪ ،...‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم بعــد االجــراء االخيــر ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                 ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫‪459‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":446,"source_page_end":459,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b6833a4eccebb1ebaa3fbc9ac784817a282768850aad8d9f1f0991818195012d","normalized_text_hash":"90cebdba84e4c560f1cd46f89e560ea06ed547dbd366b83e52306f8d8667d440","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p446-34169935"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"0b51380e-d5ec-52fb-b313-a6335ea57c74","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -بيع -اخاء عقار بعد البيع -سداد اجره فترة البقاء بعد االفراغ ودفع اجره محاماة [ طلبان عارضان] -وجوب الوفاء بالعقود -احلكم بإخاء العقار -تأجيل النظر يف طلب عارض حتى توفر مسوغات البت فيه .","document_number":"34187682","case_number":"33336901","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بنجران","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/14","year":"1434","subject":"عقار -بيع -اخاء عقار بعد البيع -سداد اجره فترة البقاء بعد االفراغ ودفع اجره محاماة [ طلبان عارضان] -وجوب الوفاء بالعقود -احلكم بإخاء العقار -تأجيل النظر يف طلب عارض حتى توفر مسوغات البت فيه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/14 :‬ه‬\n                ‫ُ‬                ‫َر ْق ُم َّ‬\n                   ‫الص ِّك‪34187682 :‬‬\n                  ‫َر ْق ُم الدعوى‪33336901 :‬‬\n  ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34273196‬تاريخه‪1434/7/19 :‬هـ‬\n\n\n‫عقــار ‪ -‬بيــع ‪ -‬اخــاء عقــار بعــد البيــع ‪ -‬ســداد اجــره فتــرة البقــاء‬\n‫بعــد االفــراغ ودفــع اجــره محامــاة [ طلبــان عارضــان] ‪ -‬وجــوب الوفــاء‬\n‫بالعقــود ‪ -‬احلكــم بإخــاء العقــار ‪ -‬تأجيــل النظــر يف طلــب عــارض‬\n                                       ‫حتــى توفــر مســوغات البــت فيــه ‪.‬‬\n\n\n\n\n                         ‫آم ُنوا َأوْفُ وا ِبا ْل ُع ُقودِ)‬ ‫‪ .1‬قوله تعالى ( َيا َأ ُّي َها ا َّلذِ َ‬\n                                                         ‫ين َ‬\n                                         ‫‪ .2‬املادة (‪ )81‬من نظام املرافعات الشرعية‬\n\n\n\n\n‫ادعــى املدعــي وكالــة عــن إحــدى الشــركات ضــد املدعــى عليــه‬\n‫وكالــة أن الشــركة موكلتــه قــد اشــترت عقــار ًا مــن املدعــى عليــه‬\n‫مبينـ ًا موقعــه وصفتــه بالدعــوى بثمــن وقــدره ثمامنائــة ألــف ريــال اســتلمها‬\n‫املدعــى عليــه إال أن املدعــى عليــه مــا زال ســاكن ًا بالعقــار وطالــب‬\n‫املدعــي وكالــة بإلــزام املدعــى عليــه بإخــاء العقــار وأجــرة املثــل مــدة‬\n‫بقــاء املدعــى عليــه وإلزامــه بأجــرة احملامــاة ‪ -‬أجــاب املدعــى عليــه‬\n‫باإلنــكار وقــرر أن الــذي اشــترى العقــار شــخص آخــر وان املدعــى عليــه‬\n‫أصالــة اشــترط أن يبقــى يف الــدور األرضــي مــدة ســنتني ‪ -‬اطلــع ناظــر‬\n‫القضيــة علــى صــك العقــار فوجــد انــه مت التهميــش علــى صــك امللكيــة‬\n\n                                                                                                       ‫‪418‬‬\n\f      ‫بانتقــال ملكيــة العقــار للشــركة املدعيــة مقابــل ثمامنائــة ألــف ريــال ‪-‬‬\n      ‫آم ُنــوا َأ ْو ُفــوا ِبا ْل ُع ُقــود)‬\n                                            ‫(يــا َأ ُّي َهــا ا َلّذِ يـ َـن َ‬\n                                                                             ‫قــرر ناظــر القضيــة ولقولــه تعالــى َ‬\n      ‫ولعــدم ثبــوت شــرط ينــايف ذلــك فقــد صــدر احلكــم بإخــاء املدعــى‬\n      ‫عليــه أصالــة للعقــار وتأجيــل النظــر يف الطلبــات العارضــة حلــن توفــر‬\n      ‫مســوغات البــت فيهــا ‪ -‬قــرر املدعــى عليــه عــدم القناعــة ‪ -‬صــدر قــرار‬\n                     ‫محكمــة االســتئناف مبنطقــة عســير باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي‪ ...‬يف احملكمــة العامــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بنجــران برقــم ‪ 33336901‬وتاريــخ ‪1433/05/16‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33916339‬وتاريــخ ‪ 1433/05/16‬ه ـ حضــر‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم الوكيــل الشــرعي عــن‬\n      ‫شــركة ‪........‬مبوجــب الوكالــة رقــم ‪........‬وتاريــخ ‪1433/03/26‬ه ـ‬\n      ‫والتــي تخولــه حــق التقاضــي أمــام جميــع جهــات التقاضــي وجميــع جلــان‬\n      ‫التســوية والهيئــات القضائيــة والقانونيــة ولــه احلــق يف إقامــة الدعــاوى‬\n      ‫وتقــدمي البينــات واملرافعــة واملدافعــة واملخاصمــة وغيــر ذلــك وحضــر‬\n      ‫حلضــوره املدعــى عليــه وكالــة ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫ا عــن املدعــى عليــه ابنــه‪ ...‬مبوجــب صــك الوكالــة‬    ‫رقــم بصفتــه وكي ـ ً‬\n      ‫الصــادر مــن كتابــة العــدل الثانيــة بشــرق الريــاض برقــم ‪........‬وتاريــخ‬\n      ‫‪1434/04/07‬ه ـ والتــي تخولــه حــق املطالبــة وإقامــة الدعــاوى واملرافعــة‬\n      ‫واملدافعــة وســماع الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار وغيــر‬\n      ‫ذلــك فادعــى املدعــي قائــا يف دعــواه أن الشــركة موكلتــي اشــترت‬\n\n‫‪419‬‬\n\f‫مــن املدعــى عليــه أصالــة منــز ًال يقــع يف حــي ‪........‬ذي الصــك رقــم ‪........‬‬\n‫وتاريــخ ‪1395/02/06‬ه ـ والبالــغ مســاحتها ســبعمائة وخمســة وثالثــون‬\n‫متــر ًا مربع ـ ًا وحدودهــا كمــا يلــي ‪ :‬شــما ًال بطــول ثالثــن متــر ًا يليهــا‬\n‫األرض رقــم ‪ 149‬وجنوب ـ ًا بطــول ثالثــن متــر ًا يليهــا الشــارع رقــم ‪88‬‬\n‫بعــرض ‪ 15‬م وشــرقا بطــول أربعــة وعشــرين متــر ًا وخمســن ســم يليهــا‬\n‫األرض رقــم ‪ 152‬وغرب ـ ًا بطــول أربعــة وعشــرين متــر ًا وخمســن ســم‬\n‫يليهــا األرض رقــم ‪ 148‬للمدعــو ‪ ... /‬ومت اإلفــراغ للشــركة موكلتــي‬\n‫يف ‪1432/11/17‬ه ـ مقابــل مبلــغ وقــدره ثمامنائــة ألــف ريــال ســعودي‬\n‫اســتلمها املدعــى عليــه مبوجــب شــيك صــادر مــن مصــرف ‪ ...‬والزال‬\n‫املدعــى عليــه يف املنــزل ولــم يخــرج منــه حتــى هــذا التاريــخ أطلــب إلــزام‬\n‫املدعــى عليــه بإخــاء العقــار وإلزامــه بدفــع أجــرة املثــل عــن الفتــرة التــي‬\n‫كان العقــار حتــت يــده بعــد اإلفــراغ وإلزامــه بدفــع أجــرة احملامــاة‬\n‫هــذه دعــواي وبعــرض مــا جــاء يف الدعــوى علــى املدعــى عليــه وكال ـ ًة‬\n‫ا مــا ذكــره املدعــي وكالــة مــن أن موكلــي بــاع املنــزل‬          ‫أجــاب قائ ـ ً‬\n‫املذكــور علــى شــركة ‪ ...‬غيــر صحيــح وإمنــا الصحيــح أنــه باعــه علــى‬\n‫شــخص يدعــى مببلــغ وقــدره تســعمائة وخمســون ألــف ريــال ســعودي‬\n‫اســتلم موكلــي مــن مبلغ ـ ًا وقــدره مائــة وخمســون ألــف ريــال واســتلم‬\n‫موكلــي مــن البنــك مبلغ ـ ًا وقــدره ثمامنائــة ألــف ريــال ســعودي وقــد‬\n‫اشــترط عليــه أن يبقــى يف املنــزل مــدة ســنتني يف الــدور األرضــي أمــا‬\n‫الــدور العلــوي فقــد اســتلمه وقــام بتأجيــره هــذه إجابتــي وبعــرض ذلــك‬\n‫علــى املدعــي وكالــة مــا ذكــر املدعــى عليــه وكال ـ ًة غيــر صحيــح‬\n‫والصحيــح مــا ذكرتــه أنــا فاملشــتري هــي موكلتــي وليــس للشــخص‬\n‫املذكــور أي صفــة يف البيــع هكــذا أجــاب و بســؤاله البينــة علــى مــا‬\n\n\n                                                                                        ‫‪420‬‬\n\f      ‫ذكــر أبــرز صــك العقــار املذكــور بعاليــه وقــد قمــت ســابق ًا بالكتابــة‬\n      ‫ملصــدره كتابــة عــدل منطقــة ‪ ...‬لالستفســار عــن ســريان مفعولــه وذلــك‬\n      ‫برقــم ‪ 34750289‬وتاريــخ ‪1434/03/25‬ه ـ فوردنــا اجلــواب منهــم برقــم‬\n      ‫‪ 34792132‬وتاريــخ ‪1434/04/01‬ه ـ املقيــد لدينــا باحملكمــة برقــم‬\n      ‫‪ 34811508‬وتاريــخ ‪1434/04/02‬ه ـ املتضمــن مطابقــة الصــك لســجله‬\n      ‫وباإلطــاع علــى أصــل الصــك وجدتــه تضمــن انتقــال ملكيــة العقــار‬\n      ‫لصالــح شــركة ‪........‬يف ‪1432/11/17‬ه ـ مبقابــل مبلــغ وقــدره ثمامنائــة‬\n      ‫ألــف ريــال ســعودي وبســؤال املدعــي وكالــة عــن عالقتــه بالشــركة‬\n      ‫ا أنــي موظــف لديهــم أتقاضــى راتبـ ًا ثابتـ ًا هكــذا‬  ‫املوكلــة أجــاب قائـ ً‬\n      ‫ا إخــاء‬  ‫أجــاب وبســؤاله عــن طلبــه األصلــي يف الدعــوى أجــاب قائ ـ ً‬\n      ‫املدعــى عليــه أصال ـ ًة مــن العقــار فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة وإلقــرار املدعــى عليــه أصالــة لــدى كاتــب العــدل ببيــع العقــار‬\n      ‫علــى الشــركة املدعيــة مقابــل مبلــغ وقــدره ثمامنائــة ألــف ريــال ســعودي‬\n      ‫ولكــون إخــاء العقــار مــن مقتضيــات عقــد البيــع ولعــدم ثبــوت شــرط‬\n      ‫ينــايف ذلــك ولقولــه تعالــى ‪ ( :‬يــا أيهــا الذيــن آمنــوا أوفــوا بالعقــود )‬\n      ‫وللمــادة احلاديــة والثمانــن مــن نظــام املرافعــات الشــرعية وملــا تقــدم كله‬\n      ‫فقــد حكمــت بإخــاء املدعــى عليــه أصالــة العقــار املذكــور وقــررت‬\n      ‫تأجيــل النظــر يف الطلبــات العارضــة األخــرى حلــن توفــر مســوغات البــت‬\n      ‫فيهــا مبــا تقــدم حكمــت وبعــرض احلكــم علــى الطرفــن قــررا عــدم‬\n      ‫قناعتهمــا باحلكــم وطلبــا اســتئناف احلكــم لــدى محكمــة االســتئناف‬\n      ‫وجــرى إفهامهمــا باســتالم نســخة احلكــم يف هــذا اليــوم وأن عليهمــا‬\n      ‫أن يتقدمــا بالالئحــة االعتراضيــة خــال ثالثــن يوم ـ ًا تبــدأ مــن هــذا‬\n      ‫اليــوم وأنــه إذا انقضــت املــدة ولــم يتقــدم أحدهمــا بالئحتــه فــإن حقــه يف‬\n\n\n‫‪421‬‬\n\f‫االعتــراض يســقط وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/04/14‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده أمــا بعــد‬\n‫فلــدي أنــا القاضــي باحملكمــة العامــة بنجــران والقائــم بعمــل املكتــب‬\n‫القضائــي الســادس فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبنطقــة عســير برقــم ‪ 341251409‬وتاريــخ ‪1434/07/26‬ه ـ برفقهــا‬\n‫القــرار الصــادر مــن الدائــرة احلقوقيــة الثالثــة برقــم ‪ 34273196‬وتاريــخ‬\n‫‪1434/07/19‬ه ـ ونــص احلاجــة منــه ‪ ( :‬وبدراســة الصــك وصــورة ضبطه‬\n‫واملذكرتــن االعتراضيتــن وأوراق املعاملــة لــم يظهــر مــا يوجــب‬\n‫االعتــراض لــذا قررنــا املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬قاضــي اســتئناف ختمــه‬\n‫وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس الدائــرة ختمــه وتوقيعــه‬\n‫) وحتــى ال يخفــى جــرى حتريــره وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n        ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/28‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n‫الثالثــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة بنجــران برقــم ‪ 331943923‬وتاريــخ‬\n‫‪1434/5/13‬ه ـ اخلاصــة بدعــوى‪ /‬وكالــة ضــد‪ /‬وكالــة بشــأن إخــاء‬\n‫عقــار املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪ /‬برقــم ‪34187682‬‬\n‫وتاريــخ ‪1433/4/14‬ه ـ املتضمــن حكــم فضيلته مبا هو مدون ومفصل‬\n‫فيــه وبدراســة الصــك وصــورة ضبطــه واملذكرتــن االعتراضيتــن‬\n‫وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض لــذا قررنــا املوافقــة علــى‬\n‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                            ‫وســلم ‪.‬‬\n                                                                                       ‫‪422‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":418,"source_page_end":422,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9a639991c0292197b2b43b4f7a9800fc02222d343e4a573c175b0188460b185f","normalized_text_hash":"67ff70f3d0463cc6d87f509e102874748b27e28f14e6122218ae9bc3c4f784fe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p418-34187682"},{"id":"ac8d2fc3-ab9e-5e98-9f30-c94c58f5f31d","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -تداخل عقارات -قيام طريف اخلصومة بشراء العقار من باقي الورثة وتقسيم امللكية والنسبة املشاعة بينهما -قيام املدعية ببناء بعض اإلنشاءات -االختاف حول النسبة املشاعة -تكييف الدعوى دائر بن كونه وعد ا أو بيع ا معلق ا على شرط مجهول -الوعد غير ملزم والبيع املعلق على شرط مجهول غير صحيح -شرط بحث الواقعة أن تكون منتجة -رد الدعوى واخاء سبيل املدعى عليها .","document_number":"33359710","case_number":"156780615","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/7/28","year":"1434","subject":"عقار -تداخل عقارات -قيام طريف اخلصومة بشراء العقار من باقي الورثة وتقسيم امللكية والنسبة املشاعة بينهما -قيام املدعية ببناء بعض اإلنشاءات -االختاف حول النسبة املشاعة -تكييف الدعوى دائر بن كونه وعد ا أو بيع ا معلق ا على شرط مجهول -الوعد غير ملزم والبيع املعلق على شرط مجهول غير صحيح -شرط بحث الواقعة أن تكون منتجة -رد الدعوى واخاء سبيل املدعى عليها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33359710:‬تاريخه‪1433/7/28 :‬هـ‬\n                       ‫رقم الدعوى‪156780615 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34177916‬تاريخه‪1434/4/2 :‬هـ‬\n\n\n      ‫عقــار ‪ -‬تداخــل عقــارات‪ -‬قيــام طــريف اخلصومة بشــراء العقــار من باقي‬\n      ‫الورثــة وتقســيم امللكيــة والنســبة املشــاعة بينهمــا‪ -‬قيــام املدعيــة ببنــاء‬\n      ‫بعــض اإلنشــاءات‪ -‬االختــاف حــول النســبة املشــاعة‪ -‬تكييــف الدعــوى‬\n      ‫دائــر بــن كونــه وعــد ًا أو بيعـ ًا معلقـ ًا علــى شــرط مجهــول‪ -‬الوعــد غيــر‬\n      ‫ملــزم والبيــع املعلــق علــى شــرط مجهــول غيــر صحيــح‪ -‬شــرط بحــث‬\n         ‫الواقعــة أن تكــون منتجــة‪ -‬رد الدعــوى واخــاء ســبيل املدعــى عليهــا ‪.‬‬\n\n\n\n\n      ‫‪ .1‬جــاء يف كشــاف القنــاع (‪( )402/7‬النــوع الثالــث مــن الشــروط‬\n      ‫الفاســدة ‪ :‬أن يشــترط البائــع شــرط ًا يعلــق البيــع عليــه كقولــه‬\n      ‫بعتــك إن جئتنــي بكــذا أو بعتــك إن رضــي فــان وكــذا تعليــق الشــراء‬\n      ‫كقبلــت إن جــاء زيــد ونحــوه فــا يصــح البيــع ألن مقتضــى البيــع نقــل‬\n                                ‫امللــك حــال التبايــع والشــرط هنــا مينعــه) ‪.‬‬\n      ‫‪ .2‬جــاء يف املجمــوع للنــووي ص‪( 28‬وال يجــوز تعليــق البيــع علــى شــرط‬\n      ‫مســتقبل كمجــيء الشــهر وقــدوم احلــاج ألنــه بيــع غــرض مــن غيــر‬\n                                                             ‫حاجــة فلــم يجــز )‪.‬‬\n\n\n\n\n‫‪423‬‬\n\f‫قامــت املدعيــة واملدعــى عليهــا بشــراء عقــار مــن باقــي الورثــة كان‬\n‫مملــوك ًا لوالدهمــا‪ ،‬قامــا بتقســيم ذلــك العقــار فيمــا بينهمــا واتفقــا‬\n‫علــى حتديــد النســبة املشــاعة‪ ،‬كمــا اتفقــا علــى أنــه يف حالــة قيــام‬\n‫املدعيــة ببنــاء إنشــاءات جديــدة يتــم تعديــل النســبة املشــاعة لتكــون‬\n‫مناصفــة فيمــا بينهمــا‪ ،‬األظهــر يف تكييــف مقتضــى هــذه الدعــوى‬\n‫دائــر بــن كونــه وعــد ًا أو بيع ـ ًا معلق ـ ًا علــى شــرط مجهــول واألول غيــر‬\n‫ملــزم والثانــي غيــر صحيــح عنــد اجلمهــور‪ ،‬وألن شــرط بحــث الواقعــة أن‬\n‫تكــون منتجــة‪ ،‬وملــا كانــت هــذه الواقعــة غيــر منتجــة عنــد بحثهــا فقــد‬\n‫حكمــت احملكمــة بعــدم اســتحقاق املدعيــة ملــا تدعيــه ورد دعواهــا‬\n                            ‫صادقــت محكمــة اإلســتئناف علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي باحملكمــة العامــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة الرئيــس‬\n‫برقــم ‪ 15678‬واملقيــدة بأســاس احملكمــة برقــم ‪ 3169016‬وتاريــخ‬\n‫‪1431/7/3‬ه ـ ويف يــوم األربعــاء ‪1433/3/2‬ه ـ حضــرت ‪ .....‬بالســجل‬\n‫املدنــي رقــم ‪.....‬واملعــرف بهــا مــن ‪.....‬بالســجل املدنــي رقــم ‪.....‬وحضــر‬\n‫حلضورهمــا ‪ .....‬بالســجل املدنــي رقــم ‪.....‬وكيــا عــن ‪.....‬مبوجــب صــك‬\n‫الوكالــة الصــادر مــن كتابــة عــدل الثانيــة مبكــة املكرمــة برقــم‬\n‫‪ 22393‬وتاريــخ ‪1426/6/5‬ه ـ واملخــول لــه فيهــا حــق املدافعــة واملرافعــة‬\n‫وســماع الدعــاوي وتقــدمي البينــات وقبــول احلكــم واالعتــراض عليــه‬\n\n                                                                                     ‫‪424‬‬\n\f      ‫وادعــت األولــى قائلــة ‪ :‬لقــد كان مــن اجلــاري يف ملــك والــدي رحمــه‬\n      ‫اهلل كامــل العمــارة أرضــا وبنــاء الكائنــة بالعزيزيــة بالضفــة الغربيــة‬\n      ‫تقســيم أربعــة القطعــة رقــم ‪ 403‬يف املخطــط رقــم ‪ 32/21/1‬ومســاحتها‬\n      ‫شــرقا وغربــا عشــرون متــرا وشــماال وجنوبــا خمســة وعشــرون متــرا‬\n      ‫ويحدهــا شــرقا شــارع عرضــه عشــرة أمتــار وغربــا شــارع عرضــه ســتة‬\n      ‫أمتــار وشــماال القطعــة رقــم ‪ 404‬وجنوبــا القطعــة رقــم ‪ 402‬ومســاحتها‬\n      ‫اإلجماليــة خمســمائة متــر مربــع واملشــتملة حينهــا علــى بــدروم ودوريــن‬\n      ‫متكــرر يف كل دور شــقتني وكل شــقة أربــع غــرف مبنافعهــا‬\n      ‫الشــرعية وشــقة يف الــدور الثالــث مكونــة مــن أربــع غــرف مبنافعهــا‬\n      ‫الشــرعية واململوكــة لــه مبوجــب الصــك الصــادر مــن كتابــة عــدل‬\n      ‫برقــم ‪ 4/122/161‬وتاريــخ ‪1409/4/17‬ه ـ وبعــد أن تــويف والــدي ‪.....‬‬\n      ‫وانحصر ارثه يف ‪..... ..... ..... ..... ..... ..... ..... ..... ..... ..... ..... .....‬قمت أنا‬\n      ‫وشــقيقتي املدعــى عليهــا بشــراء نصيــب البقيــة مبليــون ريــال بعــد أن قــام‬\n      ‫الورثــة بتقســيم العقــار جلزئــن اجلــزء األول البدروم والــدوران املتكرران‬\n      ‫يف كل دور شــقتان وأمــا اجلــزء اآلخــر فهــو الــدور الثالــث املكــون مــن‬\n      ‫شــقة بأربــع غــرف مبنافعهــا مــع الســطح اشــتريت الثانــي ودفعــت مائــة‬\n      ‫وخمســن ألــف ريــال للورثــة والباقــي دفعتــه شــقيقتي مقابــل اجلــزء األول‬\n      ‫علــى أن يكــون لــي احلــق بالتصــرف يف الــدور لــو رغبــت اضافــة أدوار‬\n      ‫أو شــقق أخــرى وأن يكــون مدخــل العمــارة للجميــع وأمــا حصــص املــاء‬\n      ‫والصــرف الصحــي فعلــي الربــع والباقــي عليهــا إال إن أضفــت شــقة يف‬\n      ‫الــدور الثالــث فيكــون علــي الثلــث والثلثــان عليهــا وإن أنشــأت دورا‬\n      ‫رابعــا فعلــي النصــف والنصــف اآلخــر عليهــا وملــا قمنــا بإجــراء اإلفــراغ‬\n      ‫لــدى كتابــة العــدل اتفقــت وإياهــا علــى أن النســبة املشــاعة يف األرض‬\n\n\n‫‪425‬‬\n\f‫خمســة وثمانــن يف املائــة لهــا وخمســة عشــر يف املائــة لــي ‪ ،‬علــى أنــي إن‬\n‫أجريــت أي إضافــة يف املبنــى فتعــدل النســبة املشــاعة يف األرض أي أنــي‬\n‫أن أكملــت الــدور الثالــث وأضفــت الرابــع فتكــون النســبة مناصفــة‬\n‫بيننــا ثــم قمــت بإكمــال الــدور الثالــث وإنشــاء الــدور الرابــع وأكملــت‬\n‫فــوق الرابــع مبيتــات وكنــت يف يــوم األحــد ‪1429/6/10‬ه ـ اتفقــت معها‬\n‫علــى أن احلــوش ملــك ‪.....‬واحلــوش اجلانبــي علــى ميــن الداخــل إلــى العمــارة‬\n‫ممــر مشــترك للجميــع وال يحــق اســتخدامه الشــخصي إال بعــد الرجــوع‬\n‫إلــى املالــك ‪ .....‬واألســطح ملكــي ويجــوز ل‪.....‬االســتفادة مــن ســطح‬\n‫املبيتــات فقــط ملنافــع املــاء وأجهــزة االســتقبال واملصعــد يتــم التنســيق‬\n‫بنــاء علــى وضــع بــاب بالــدور األول فقــط مــن قبــل ‪.....‬و املبانــي حســب‬\n‫املتفــق عليــه البــدروم والــدور األرضــي والــدور األول ملــك ل‪ .....‬والــدور‬\n‫الثانــي والــدور الثالــث والســطح واملبيتــات يكــون لــي وأمــا األرض تبقــى‬\n‫النســبة مبــا يحكــم بــه القضــاء لــذا فقــد أقمــت دعواي لديكــم للفصل‬\n‫يف النســبة املشــاعة مــن األرض وأطلــب تعديلهــا إلــى أن يكــون لــي‬\n‫النصــف مشــاعا مــن األرض والنصــف اآلخــر لهــا هــذه دعــواي وبعرضــه‬\n‫علــى وكيــل املدعــى عليهــا قــال مــا ذكرتــه املدعيــة كلــه صحيــح إال‬\n‫قولهــا بأنهــا اشــترطت أنهــا إن أضافــت أدوارا فتعــدل احلصــص علــى‬\n‫وفــق األنقــاض وأن القســمة حصلــت بــن الورثــة قبــل البيــع فهــذا غيــر‬\n‫صحيــح والصحيــح أن القســمة حصلــت بعــد الشــراء مشــاعا بــن الورثــة‬\n‫وهــل يعقــل أن موكلتــي التــي اشــترت (‪ )%85‬مــن األرض توافــق علــى‬\n‫الســماح لهــا باالرتفــاع علــى قــدر مــا تشــاء وكلمــا ارتفعــت ينقــص حقهــا‬\n‫جبــرا لــذا فــإن موكلتــي تطلــب رد دعواهــا وبعرضــه علــى املدعيــة قالــت‬\n‫الصحيــح مــا ادعيــت بــه ولــم تــأت بذكــر لــأرض علــى انفــراد وعبارتهــا‬\n\n\n                                                                                      ‫‪426‬‬\n\f      ‫التــي قالتهــا لــي إن اضفــت مبانــي فلــك نصــف العمــارة أ‪.‬ه ـ فقــرر وكيل‬\n      ‫املدعــى عليهــا قائــا‪ :‬مــا ذكرتــه مــن هــذه العبــارة ال علــم لي بهــا وأما ما‬\n      ‫ذكرتــه مــن األرض لــم يكــن لهــا ذكــر فصحيــح وموكلتــي تتمســك‬\n      ‫مبــا صــرح بــه يف الصــك أ‪.‬ه ـ ثــم حضــرت املدعيــة أصالــة وحضــرت‬\n      ‫حلضورهــا املدعــى عليهــا ‪ .....‬وحتمــل الســجل املدنــي رقــم ‪.....‬وقــد‬\n      ‫وردنــا االستفســار عــن صــك امللكيــة مــن كتابــة عــدل برقــم ‪1/1928‬‬\n      ‫وتاريــخ ‪1433/3/14‬ه ـ ومضمونــه أن صــورة الصــك رقــم ‪4/122/161‬‬\n      ‫يف ‪1409/4/17‬ه ـ مطابقــة لســجلها وســارية املفعــول حتــى تاريخــه أ‪.‬ه ـ‬\n      ‫فســألتهما إن كان لديهمــا مــا يضيفانــه فأجابــا بالنفــي عليــه وبعــد‬\n      ‫قفــل بــاب املرافعــة وبعــد تأمــل الدعــوى واإلجابــة وألن املدعيــة تطلــب يف‬\n      ‫دعواهــا إنفــاذ مقتضــى مــا تدعيــه مــن اتفــاق بينهــا وبــن املدعــى عليهــا‬\n      ‫بأنهــا متــى قامــت بزيــادة قــدر األنقــاض فإنهــا تســتحق مقابلــه نصيب ـ ًا‬\n      ‫مشــاع ًا مــن األرض وأنهــا قامــت بزيــادة قــدره وتطلــب مقابلــه إفــراغ جــزء‬\n      ‫مشــاع مــن األرض وألن األظهــر يف تكييــف مقتضــى دعــوى املدعيــة‬\n      ‫دائــر بــن كونــه وعــد ًا أو بيع ـ ًا معلق ـ ًا علــى شــرط مجهــول أمــا األول‬\n      ‫فغيــر ملــزم علــى قــول اجلماهيــر وأمــا اآلخــر فغيــر صحيــح علــى قــول‬\n      ‫اجلمهــور قــال يف كشــاف القنــاع (النــوع الثالــث مــن الشــروط الفاســدة‬\n      ‫‪ :‬أن يشــترط البائــع شــرط ًا يعلــق البيــع عليــه كقولــه بعتــك إن جئتنــي‬\n      ‫بكــذا أو بعتــك إن رضــي فــان وكــذا تعليــق الشــراء كقبلــت إن جــاء‬\n      ‫زيــد ونحــوه فــا يصــح البيــع ألن مقتضــى البيــع نقــل امللــك حــال التبايــع‬\n      ‫والشــرط هنــا مينعــه) كتــاب البيــع (‪ )402/7‬وقــال يف املجمــوع للنــووي‬\n      ‫«وال يجــوز تعليــق البيــع علــى شــرط مســتقبل كمجــيء الشــهر وقــدوم‬\n      ‫احلــاج ألنــه بيــع غــرض مــن غيــر حاجــة فلــم يجــز « كتــاب بيــوع ص ‪28‬‬\n\n\n‫‪427‬‬\n\f‫عليــه وألن مــن شــرط بحــث الواقعــة أن تكــون منتجــة وألن دعواهــا وإن‬\n‫ثبتــت غيــر صحيحــة وال يلــزم املدعــى عليهــا شــيئ ًا مبقتضاهــا هــذا مــن‬\n‫جهــة ومــن جهــة أخــرى فــإن املدعيــة أقــرت بــأن املدعــى عليهــا لــم تتفــق‬\n‫ا وارد ًا علــى‬ ‫معهــا علــى األرض علــى انفــراد بــل إقرارهــا كان مجم ـ ً‬\n‫ا لألنقــاض فقــط دون األرض وهــو مــا‬          ‫العمــارة عليــه فيكــون محتم ـ ً‬\n‫ال تنكــره املدعــى عليهــا وبــن األرض واألنقــاض جميعـ ًا ممــا يضعــف‬\n‫دعــوى املدعيــة مــع قيــام هــذا االحتمــال لــذا وملــا تقــدم فلــم يظهــر لــي‬\n‫اســتحقاق املدعيــة ملــا تدعيــه ورددت دعواهــا وأخليــت ســبيل املدعــى‬\n‫عليهــا مــن هــذه املطالبــة وبــه حكمــت وجــرى النطــق بــه يف يــوم الســبت‬\n‫‪1433/7/26‬ه ـ وبعرضــه عليهمــا قــررت املدعــى عليهــا القناعــة وأمــا‬\n‫املدعيــة فعدمهــا وطلبــت متكينهــا مــن االعتــراض فأفهمتهــا مبراجعــة‬\n‫احملكمــة يــوم االثنــن القــادم لهــا مــن بعــده ثالثــون يومـ ًا تقــدم خاللهــا‬\n‫الئحتهــا االعتراضيــة فــإن لــم تفعــل يســقط حقهــا يف االعتــراض‬\n‫ويكتســب احلكــم الصفــة القطعيــة ‪،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                      ‫وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده ويف هــذا اليــوم االثنــن ‪1433/12/27‬ه ـ فتــح‬\n‫ضبــط القضيــة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف برقــم‬\n‫‪ 332125702‬وتاريــخ ‪1433/12/1‬ه ـ وبرفقهــا قــرار الدائــرة احلقوقيــة‬\n‫الثانيــة رقــم ‪ 33469714‬وتاريــخ ‪1433/11/29‬ه ـ ونــص احلاجــة منــه‬\n‫«وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا‬\n‫لفضيلتــه إلرفــاق صــورة مصدقــة مــن ســجل الصــك رقــم ‪5/100/629‬‬\n‫يف ‪1430/10/17‬هـ وما عليها من تهميشات»أ‪.‬هـ عليه أجيب أصحاب‬\n‫الفضيلــة وفقهــم اهلل بأنــه ال يوجــد للصــك ســجل لكونــه انهــاء وهــو يف‬\n\n\n                                                                                       ‫‪428‬‬\n\f      ‫نظــام احلاســب ال ســجل لــه لــذا جــرى إرفــاق صــورة مصدقــه مــن ضبطــه‬\n                     ‫‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده ويف هــذا اليــوم الثالثــاء ‪1434/2/12‬ه ـ فتــح ضبــط‬\n      ‫القضيــة وقــد وردتنــا املعاملة من محكمة االســتئناف برقم ‪34105994‬‬\n      ‫وتاريــخ ‪1434/1/26‬ه ـ وبرفقهــا قــرار الدائــرة احلقوقيــة الثانيــة رقــم‬\n      ‫‪ 3417343‬وتاريــخ ‪1434/1/20‬ه ـ ونــص احلاجــة منــه «وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلتــه إلجــراء‬\n      ‫املقتضــى الشــرعي حيــال دعــوى املدعيــة وذلــك لســماع بينتهــا إن كان‬\n      ‫لهــا بينــة أو حتليــف املدعــى عليهــا «أ‪.‬ه ـ عليــه أجيــب أصحــاب الفضيلــة‬\n      ‫بأنــي أشــرت ملوجــب ‪ ...‬بحــث هــذه الواقعــة وهــو تكييفهــا بأنهــا دائــرة‬\n      ‫بــن كونهــا عقــدا معلقــا علــى شــرط أو وعــدا وكالهمــا غيــر ملزمــن‬\n      ‫وأن مــن شــرط بحــث الواقعــة القضائيــة أن تكــون منتجــة وهــو غيــر‬\n      ‫متحقــق يف هــذه الدعــوى كمــا قــررت ذلــك مفصــا يف تســبيب احلكــم‬\n      ‫لــذا فلــم يظهــر موجــب إلجــراء ذلــك والرجــوع عــن احلكــم وأمــرت‬\n      ‫بإحلاقــه علــى الصــك وســجله وإعادتــه حملكمــة االســتئناف وصلــى اهلل‬\n                            ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 34230600‬وتاريــخ‬\n      ‫‪1434/2/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪.....‬‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪ 33359710‬وتاريــخ‬\n      ‫‪1433/7/28‬ه ـ ‪ ،‬املتضمــن دعــوى ‪.....‬ضــد ‪ ،.....‬وبدراســة الصــك‬\n\n\n‫‪429‬‬\n\f‫وصــورة ضبطــه والئحتــه اإلعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n‫احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                                           ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                    ‫‪430‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":423,"source_page_end":430,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9081de4e238d7b7d1d190e482295f89e460f04f0b91001a336e4d30cd7cb7417","normalized_text_hash":"8febc43940e76e6bb0c912908ab5f173d0f51f24517a45360b88c19e6f34b028","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p423-33359710"},{"id":"3bc949bb-493a-5d04-ba1c-78ae1e03d767","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء منحة أرض -الوعد باإلفراغ -بيع ما ال ميلك - احلكم بإعادة املبلغ وفسخ عقد البيع.","document_number":"33433302","case_number":"333670","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/22","year":"1434","subject":"عقار -شراء منحة أرض -الوعد باإلفراغ -بيع ما ال ميلك - احلكم بإعادة املبلغ وفسخ عقد البيع.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 33433302 :‬تاريخه ‪1433/10/22 :‬هـ‬\n                             ‫رقم الدعوى ‪333670 :‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n        ‫االستئناف‪ 34201062:‬تاريخه‪1434/04/29:‬هـ‬\n\n\n       ‫عقــار ‪ -‬شــراء منحــة أرض ‪ -‬الوعــد باإلفــراغ ‪ -‬بيــع مــا ال ميلــك ‪-‬‬\n                                    ‫احلكــم بإعــادة املبلــغ وفســخ عقــد البيــع‪.‬‬\n\n\n\n\n                         ‫نهي النبي صلى اهلل عليه وسلم عن بيع ما ال ميلك ‪.‬‬\n\n\n\n\n       ‫ادعــى املدعــى بأنــه اشــتري مــن املدعــى عليــه أمــر منحــة أرض وأنــه ســلم‬\n       ‫الثمــن للمدعــى عليــه‪ -‬طلــب املدعــى إلــزام املدعــى عليــه بإفــراغ األرض‬\n       ‫لــه‪ -‬أقــر املدعــى عليــه وكالــة مبــا جــاء يف دعــوى املدعــى وقــرر املدعــى‬\n       ‫عليــه وكالــة بــأن أوراق اعتمــاد املنحــة مازالــت لــدى اجلهــات املختصــة‬\n       ‫ومتــى مــا اســتلم موكلــه األوراق فإنــه مســتعد باإلفــراغ للمدعــى‪ -‬قــرر‬\n       ‫املدعــى بأنــه ســأل عــن املعاملــة ولــم يجــد لهــا أي رقــم وطلــب املدعــى‬\n       ‫إلــزام املدعــى عليــه بإعــادة املبلــغ الــذي اســتلمه منــه‪ -‬حيــث أن املدعــى‬\n       ‫عليــه بــاع مــاال ميلــك لــذ صــدر احلكــم بالــزام املدعــى عليــه بإعــادة املبلــغ‬\n       ‫املدعــى بــه للمدعــى‪ -‬اعتــرض املدعــى عليــه علــى احلكــم‪ -‬لوحــظ علــى‬\n       ‫احلكــم مــن محكمــة االســتئناف بأنــه البــد مــن فســخ العقــد البيــع ثــم‬\n       ‫احلكــم بإعــادة املبلــغ‪ -‬اضــاف القاضــي احلكــم بفســخ عقــد البيــع‬\n                               ‫وبطالنــه‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n‫‪431‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالطائــف برقــم ‪ 333670‬وتاريــخ ‪1433/03/29‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 338426‬وتاريــخ ‪1433/01/01‬ه ـ ففــي يــوم األربعــاء‬\n‫املوافــق ‪1433/06/18‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 34‬وفيهــا‬\n‫حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وحضــر‬\n‫حلضــوره ‪ ...‬ســعودي اجلنســية حســب الســجل املدنــي رقــم ‪ ...‬بصفتــه‬\n‫وكيــا عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الطائــف‬\n‫رقــم ‪ 18350‬يف ‪1433/3/28‬ه ـ وبســؤال املدعــي عــن دعــواه قــال‬\n‫اشــتريت مــن املدعــى عليــه هــذا احلاضــر منحــة أرض مبوجــب عقــد‬\n‫مبــرم بيننــا وأوعدنــي بإعطائــي األمــر الســامي الكــرمي بعــد شــهر‬\n‫مــن تاريــخ العقــد ‪1431/8/28‬ه ـ ولــم يــويف مبــا أوعدنــي اطلــب الزامــه‬\n‫بإفــراغ هــذه األرض هــذه دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب‬\n‫ا لــذا رفعــت‬  ‫قائــا اطلــب مهلــة لإلجابــة علــى هــذه الدعــوى مفص ـ ً‬\n‫اجللســة ويف جلســة أخــرى حضــر الطرفــان وجــري ســؤال املدعــى عليــه‬\n‫هــل أحضــر إجابــة علــى مــا جــاء يف دعــوى املدعــي فقــال نعــم كل مــا‬\n‫جــاء يف دعــوى املدعــي كلــه صحيــح جملــة وتفصيــا وموكلــي قــد بــاع‬\n‫هــذه األرض بقيمــة ســبعة وثالثــن ألــف وخمســمائة ريــال علــى املدعــي‬\n‫وأوراق اعتمادهــا مازالــت موجــوده يف الديــوان امللكــي العتمادهــا‬\n‫ومتــي مــا أســتلم أوراقهــا فهــو مســتعد بإفراغهــا للمدعــي هكــذا أجــاب‬\n‫وبعــرض ذلــك علــى املدعــي قــال مــا جــاء يف أجابتــه مــن أن أوراق األرض‬\n\n                                                                                   ‫‪432‬‬\n\f      ‫مازالــت يف الديــوان امللكــي فهــذا غيــر صحيــح فأنــا ســئلت عنهــا ولــم‬\n      ‫أجــد لهــا أي رقــم وأطلــب إعــادة مــا اســتلمه املدعــى عليــه أصالــه مــن‬\n      ‫مبالــغ البالــغ ســبعة وثالثــن ألــف وخمســمائة ريــال وبنــاء علــى الدعــوي‬\n      ‫واإلجابــة وحيــث أن املدعــى عليــه قــد بــاع علــى املدعــي مــا ال ميلــك وقــد‬\n      ‫نهــي نبينــا محمــد عليــه الصــاة والســام بيــع املســلم ألخيــه املســلم مــاال‬\n      ‫ميلــك فلجميــع مــا ســبق فقــد حكمــت علــى املدعــى عليــه ‪...‬بــأن يرجــع‬\n      ‫للمدعــي ‪...‬املبلــغ املســلم لــه البالــغ ســبعة وثالثــن ألــف وخمســمائة ريــال‬\n      ‫وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليــه وكالــه قــرر عــدم‬\n      ‫القناعــة بهــذا احلكــم وطلــب رفعهــا إلــى محكمــة اإلســتئناف بتقــدمي‬\n      ‫الئحــة اعتراضيــة وجــري تســليمه صــوره مــن هــذا احلكــم يف هــذا‬\n      ‫اليــوم وجــري إفهامــه بــأن لــه ثالثــن يــوم تبــدأ مــن هــذا اليــوم وتنتهــي يف‬\n      ‫‪1433/11/21‬ه ـ ويف حــال عــدم تقدميــه الالئحــة يف التاريــخ املذكــور‬\n      ‫أعــاه يســقط حقــه يف االعتــراض ويكتســب هــذا احلكــم الصفــة‬\n      ‫القطعيــة ففهــم ذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/10/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫برقــم ‪ 34390235‬يف ‪1434/02/17‬ه ـ وبرفقهــا قــرار املالحظــة رقــم‬\n      ‫‪ 3422764‬يف ‪1434/01/26‬ه ـ املتضمــن وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه والئحتــه االعتراضيــة تقــررت إعادتهــا لفضيلــة حاكمهــا‬\n      ‫لكونــه حكــم بــرد املبلــغ ولــم يحكــم بفســخ البيــع فعلــى فضيلتــه‬\n      ‫تضمــن حكمــه بفســخ البيــع أ‪.‬ه ـ عليــه فأجيــب عمــا ذكــره أصحــاب‬\n      ‫الفضيلــة بأنــي أضيــف إلــى مــا حكمــت احلكــم بفســخ البيــع ليكــون‬\n      ‫احلكــم كالتالــي ‪ :‬وبنــاء علــى الدعــوى واإلجابــة وحيــث أن املدعــى‬\n\n\n‫‪433‬‬\n\f‫عليــه قــد بــاع علــى املدعــي مــا ال ميلــك وقــد نهــى نبينــا محمــد عليــه‬\n‫الصــاة والســام بيــع املســلم ألخيــه املســلم مــا ال ميلــك فلجميــع مــا ســبق‬\n‫فقــد حكمــت بفســخ البيــع وبطالنــه وإلــزام املدعــى عليــه ‪...‬بــأن يرجــع‬\n‫للمدعــي ‪...‬املبلــغ املســلم لــه البالــغ ســبعة وثالثــن ألــف وخمســمائة ريــال‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1434/04/01‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا الصــك رقــم ‪ 33433302‬يف ‪1433/10/22‬ه ـ املظهــر عليــه‬\n‫قــرار محكمــة االســتئناف رقــم ‪ 34201062‬يف ‪1434/04/29‬ه ـ‬\n‫املتضمــن املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر وبــاهلل التوفيــق‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                              ‫‪ 1434/05/20‬ه ـ ‪.‬‬\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى احلكــم الصــادر مــن‬\n‫فضيلــة الشــيخ ‪ ...‬القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد‬\n‫‪ 33433302‬وتاريــخ ‪ 1433/10/22‬هـ ـ واملتضمــن دعــوى‪... /‬ضــد‪/‬‬\n                                            ‫‪...‬واحملكــوم فيــه مبــا دون باطنــه ‪.‬‬\n‫وبدراســة احلكــم وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق‪ .‬وصلــى اهلل‬\n                       ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n\n                                                                                      ‫‪434‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":431,"source_page_end":434,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0bb788b9f99a001b8f06c264b51c0993e3c3d2344d101caf3653e9d28864baf1","normalized_text_hash":"80813e71fea37ee7fb64458ad170e52b9780e28133a5e9962653253134a38195","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p431-33433302"},{"id":"1c71f34f-2b9e-5edd-8cc0-90c31ef4a5d6","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -تداخل أراضي -ما تنازل به املدعي يف حكم الساقط والساقط ال يعود -تقدير التداخل يف األرض عن طريق قسم اخلبراء -ال يحل مال امرئ مسلم أال بطيب نفس منه -احلكم برد دعوى املدعي وإخاء سبيل املدعى عليه .","document_number":"342935","case_number":"33476125","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/5","year":"1434","subject":"عقار -تداخل أراضي -ما تنازل به املدعي يف حكم الساقط والساقط ال يعود -تقدير التداخل يف األرض عن طريق قسم اخلبراء -ال يحل مال امرئ مسلم أال بطيب نفس منه -احلكم برد دعوى املدعي وإخاء سبيل املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك‪ 342935:‬تاريخه‪1434/1/5:‬هـ‬\n                       ‫رقم الدعوى‪33476125:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 3443904‬تاريخه‪1434/2/23 :‬هـ‬\n\n\n      ‫عقــار ‪ -‬تداخــل أراضــي ‪ -‬مــا تنــازل بــه املدعــي يف حكــم الســاقط‬\n      ‫والســاقط ال يعــود ‪ -‬تقديــر التداخــل يف األرض عــن طريــق قســم‬\n      ‫اخلبــراء ‪ -‬ال يحــل مــال امــرئ مســلم أال بطيــب نفــس منــه ‪ -‬احلكــم‬\n                         ‫بــرد دعــوى املدعــي وإخــاء ســبيل املدعــى عليــه ‪.‬‬\n\n\n\n\n      ‫‪ .1‬قولــه صلــى اهلل عليــه وســلم (ال يحــل مــال امــرئ مســلم إال بطيــب‬\n                                                                    ‫نفــس منــه)‪.‬‬\n                                      ‫‪ .2‬القاعدة الفقهية‪ :‬الساقط ال يعود ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه ميلــك قطعــة االرض اململوكــة‬\n      ‫بالصــك الصــادر مــن كتابــة عــدل املدينــة املنــورة ويحدهــا قبلــة املربــع‬\n      ‫رقــم واحــد وســبعون واململــوك للمدعــى عليــه وقــد دخــل علــى أرضــه‬\n      ‫بعــرض متــر وثالثــة وثالثــون ســنتمتر بطــول احلــد وطولــه خمســة‬\n      ‫وعشــرون متــر ًا ويطلــب رفــع يــده عنــه هكــذا ادعــى ‪ -‬أجــاب املدعــى‬\n      ‫عليــه بعــدم املصادقــة علــى الدعــوى ‪ -‬جــرى الكتابــة لقســم اخلبــراء‬\n      ‫لتطبيــق الصكــوك علــى املوقــع فــورد جوابهــم املتضمــن أن صــك‬\n      ‫املدعــي يتداخــل مــع صــك املدعــى عليــه وأن املدعــي قــد تنــازل عــن‬\n\n‫‪435‬‬\n\f‫هــذا اجلــزء املتداخــل وذلــك حســب رخصــة االنشــاء املرفقــة صورتهــا ‪-‬‬\n‫صــادق املدعــي علــى تنازلــه عــن التداخــل محــل الدعــوى لــدى املكتــب‬\n‫الهندســي ودفــع بأنــه وقــع مكره ـ ًا لتتــم إجــراءات اســتخراج رخصــة‬\n‫العمــارة ‪ -‬قــرر املدعــي يف جلســة أخــرى بــأن املدعــى عليــه قــد رفــع‬\n‫يــده عمــا هــو داخــل يف رخصتــه وال يطالبــه بخصوصــه بشــيء ويطالبــه‬\n‫مبــا تنــازل عنــه مكرهــا لــدى املكتــب الهندســي ‪ -‬ومبــا أن املدعــي‬\n‫قــد أقــر أنــه تنــازل عمــا يطالــب بــه وذكــر إكراهــا إن ثبــت فهــو ال‬\n‫يؤثــر علــى تنازلــه والســاقط ال يعــود وبتنازلــه فقــد دخــل املتنــازل يف ملــك‬\n‫غيــره وال يحــل مــال امــرئ مســلم إال بطيــب نفــس منــه ومبــا أن املدعــى‬\n‫عليــه قــد رفــع يــده عمــا تداخــل يف ملــك املدعــي ممــا ســبق اإلشــارة‬\n‫إليــه‪ -‬ملــا تقــدم احلكــم بــرد دعــوى املدعــي ‪ -‬قنــع املدعــى عليــه باحلكــم‬\n‫واعتــرض املدعــي بالئحــة ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n             ‫الســابعة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫‪.........‬القاضــي يف احملكمــة العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامة باملدينة املنورة‪/‬املســاعد‬\n‫برقــم ‪ 33476125‬وتاريــخ ‪ 1433/07/20‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 331362501‬وتاريــخ ‪ 1433/07/20‬ه ـ ففــي يــوم االحــد املوافــق‬\n‫‪1433/8/25‬هـ حضر ‪ .........‬ســعودي بالســجل املدني رقم ‪.........‬وادعى‬\n‫ا اننــي‬\n       ‫علــى احلاضــر معــه ‪.........‬ســعودي بالســجل املدنــي رقــم ‪.........‬قائـ ً‬\n‫املــك قطعــة االرض املقامــة بهــا عمــارة والواقعــة خــارج بــاب العنبريــة‬\n\n                                                                                        ‫‪436‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":435,"source_page_end":436,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e39d28be68d3a8112de883dcc8bf4c31493db2581cadf1b58826e1294b6a9a1c","normalized_text_hash":"c091d3b329cc747ff7117c8576d872993270fdee02b45e556b73eec718f27177","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p435-342935"},{"id":"2579073c-548e-5bf6-97f7-cd9ae5484a16","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -تنازع حول ملكية عقار -املطالبة برفع يد عن األرض - توف اإلجراءات النظامية -إيقافصك ملكية األرض لم يس الدعوى حلني استكمال اإلجراءات النظامية للصك -وقف الدعوى تعليقي ا -عدم اكتساب صك حجة االستحكام القطعية إال بعد تصديق محكمة اإلستئناف يف حالة وجود اعتراض -التثبت من صحة الصكوك من اجلهات الرسمية .","document_number":"33479865","case_number":"33408392","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/27","year":"1434","subject":"عقار -تنازع حول ملكية عقار -املطالبة برفع يد عن األرض - توف اإلجراءات النظامية -إيقافصك ملكية األرض لم يس الدعوى حلني استكمال اإلجراءات النظامية للصك -وقف الدعوى تعليقي ا -عدم اكتساب صك حجة االستحكام القطعية إال بعد تصديق محكمة اإلستئناف يف حالة وجود اعتراض -التثبت من صحة الصكوك من اجلهات الرسمية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33479865 :‬تاريخه‪1433/12/27 :‬هـ‬\n                   ‫رقم الدعوى‪33408392 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34201067‬تاريخه‪1434/4/29 :‬هـ‬\n\n\n ‫عقــار ‪ -‬تنــازع حــول ملكيــة عقــار ‪ -‬املطالبــة برفــع يــد عــن األرض ‪-‬‬\n ‫ـتوف اإلجــراءات النظاميــة ‪ -‬إيقــاف‬‫صــك ملكيــة األرض لــم يسـ ِ‬\n ‫الدعوى حلني اســتكمال اإلجراءات النظامية للصك ‪ -‬وقف الدعوى‬\n ‫تعليقيـ ًا ‪ -‬عــدم اكتســاب صــك حجــة االســتحكام القطعيــة إال بعــد‬\n ‫تصديــق محكمــة اإلســتئناف يف حالــة وجــود اعتــراض ‪ -‬التثبــت مــن‬\n                               ‫صحــة الصكــوك مــن اجلهــات الرســمية ‪.‬‬\n\n\n\n       ‫‪ .1‬املادة ‪ 2/83‬من نظام املرافعات الشرعية والئحته التنفيذية ‪.‬‬\n ‫‪ .2‬املــادة الرابعــة واخلمســون بعــد املائتــن مــن نظــام املرافعات الشــرعية‬\n                                                       ‫والئحتــه التنفيذية ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي ضــد املدعــى عليــه بأنــه اعتــدى علــى أرضــه ويطلــب‬\n ‫رفــع يــده عــن األرض ‪ -‬حيــث قــام املدعــى عليــه بتعقيــم معظــم أرض‬\n ‫املدعــي معتدي ـ ًا عليهــا ‪ -‬أجــاب املدعــى عليــه باإلنــكار وأنــه قــام‬\n ‫بتعقيــم األرض التــي حتــت يــده واململوكــة لــه مبوجــب صــك شــرعي‬\n ‫وقــد آلــت لــه عــن طريــق الشــراء ‪ -‬أجــاب املدعــي بــأن األرض قــد آلــت‬\n ‫لــه باألحيــاء مبوجــب حجــة االحــكام الصــادرة مــن احملكمــة ‪ -‬باطــاع‬\n\n                                                                                    ‫‪440‬‬\n\f      ‫ناظــر القضيــة علــى صــك ملكيــة املدعــي وجــد أنــه ُصــرف النظــر عــن‬\n      ‫معارضــة البلديــة ولــم يرفــع لالســتئناف وهــذا اإلجــراء إجــراء ناقــص‬\n      ‫غيــر مكتمــل لإلجــراءات النظاميــة وال يكتســب فيــه احلكــم القطعية‬\n      ‫وذلــك وفقـ ًا ملــا جــاء يف املــادة الرابعــة واخلمســن بعــد املائتــن مــن نظــام‬\n      ‫ـاء علــى املــادة الثالثــة‬\n                               ‫املرافعــات الشــرعية والئحتهــا التنفيذيــة ‪ -‬لــذا وبنـ ً‬\n      ‫والثمانــن مــن نظــام املرافعــات الشــرعية ونصهــا (إذا رأت احملكمــة‬\n      ‫تعليــق حكمهــا يف موضــوع الدعــوى علــى الفصــل يف مســألة أخــرى‬\n      ‫يتوقــف عليهــا احلكــم فتأمــر بوقــف الدعــوى ومبجــرد زوال ســبب‬\n      ‫التوقــف يكــون للخصــوم طلــب الســير يف الدعوى)ا‪.‬ه ـ والالئحــة الثانية‬\n      ‫مــن ذات املــادة ونصهــا(إذا أمــر القاضــي بوقــف الدعــوى حســب هــذه‬\n      ‫املــادة أو رفــض طلــب اخلصــوم فيصــدر قــرار ًا بذلــك ويعامــل مــن لــم يقنــع‬\n      ‫مبوجــب تعليمــات التمييــز)‪ -‬احلكــم بإيقــاف الدعــوى حلــن اســتكمال‬\n      ‫املدعــي أصالــة اإلجــراءات النظاميــة وتصديــق متلكــه مــن محكمــة‬\n      ‫االســتئناف ‪ -‬اعتــرض املدعــي علــى احلكــم بالئحــة ‪ -‬صــدق احلكــم‬\n                                                              ‫مــن محكمــة اإلســتئناف ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بينبــع‪ /‬املســاعد برقــم ‪ 33408392‬وتاريــخ ‪1433/06/17‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 331139502‬وتاريــخ ‪ 1433/06/17‬ه ـ‬\n      ‫ففــي يــوم األحــد املوافــق‪ 1433/08/25‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 11 : 30‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n\n‫‪441‬‬\n\f‫ا عــن ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬    ‫رقــم ‪ ...‬بصفتــه وكيـ ً‬\n‫عــدل محافظــة أملــج ‪ 2/5‬وتاريــخ ‪1433/06/18‬ه ـ والتــي تخولــه حــق‬\n‫املرافعــة واملدافعــة بخصــوص األرض الواقعــة يف ينبــع برقــم ‪1960‬‬\n‫وحضــور اجللســات وقبــول احلكــم واالعتــراض عليــه وطلــب اليمــن‬\n‫والتنــازل واالبــراء والقبــض وإقامــة البينــة وحضــر حلضــوره ‪ ...‬ســعودي‬\n‫ا عــن ‪ ...‬مبوجــب‬  ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بصفتــه وكيـ ً‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جده برقم‬\n‫‪ 18439‬وتاريــخ ‪1431/02/26‬ه ـ والتــي تخولــه حــق املرافعــة واملدافعــة‬\n‫وســماع البينــات واجلــرح والتعديــل واإلقــرار واإلنــكار والصلــح والتنــازل‬\n‫ا يف دعــواه إن‬  ‫والقناعــة باحلكــم ورفضــه وادعــى املدعــي وكالــة قائ ـ ً‬\n‫مــن اجلــاري يف ملــك موكلــي األرض الواقعــة يف (‪ )....‬بالكيلــو الســابع‬\n‫شــرق محافظــة ينبــع ومســاحتها(‪ )75,000‬خمســة وســبعون ألــف متــر‬\n‫ويحدهــا مــن الشــمال ‪ ....‬بطــول (‪ )500‬خمســمائة متــر ومــن اجلنــوب ‪....‬‬\n‫بطــول (‪ )500‬خمســمائة متــر ومــن الشــرق ‪ .....‬بطــول (‪ )300‬ثالثمائــة‬\n‫متــر ومــن الغــرب ملــك ألحــد األشــخاص بطــول(‪ )300‬ثالثمائــة متــر‬\n‫وهــي آيلــة إلــى موكلــي باإلحيــاء الشــرعي مبوجــب الصــك الصــادر‬\n‫مــن محكمــة ينبــع مــن القاضــي بهــا الشــيخ ‪ ...‬رئيــس احملكمــة آن‬\n‫ذاك برقــم ‪ 296‬وتاريــخ ‪1400/06/04‬ه ـ وقــد قــام املدعــى عليــه أصالــة‬\n‫باالعتــداء علــى معظــم أرض موكلــي آنفــة الذكــر وعقمهــا أطلــب رفــع‬\n‫يــد املدعــى عليــه أصالــة عــن اجلــزء املتداخــل مــع أرض موكلــي و مــا‬\n‫ال هكــذا‬  ‫أقامــه عليهــا مــن عقــوم وعــدم التعــرض مللــك موكلــي مســتقب ً‬\n‫ادعــى وبعــرض دعــوى املدعــي وكالــة علــى املدعــى عليــه وكالــة‬\n‫أجــاب بقولــه مــا جــاء يف دعــوى املدعــي وكالــة غيــر صحيــح وموكلــي‬\n\n\n                                                                                  ‫‪442‬‬\n\f      ‫لــم يعقــم غيــر أرضــه التــي حتــت يــده واململوكــة لــه مبوجــب الصــك‬\n      ‫الشــرعي الصــادر مــن كتابــة عــدل ينبــع برقــم ‪ 3/4/839‬وتاريــخ‬\n      ‫‪1410/05/04‬ه ـ واحملــدودة مــن اجلنــوب األســفلت بطــول (‪)1,200‬‬\n      ‫ألــف ومئتــا متــر وشــرق ًا مزرعــة ‪ ...‬بطــول (‪ )1,500‬ألــف وخمســمائة‬\n      ‫متــر وشــما ًال ‪ ...‬بطــول (‪ )1,200‬ألــف ومئتــا متــر وغرب ـ ًا ملــك ‪ ...‬بطــول‬\n      ‫(‪ )1,500‬ألــف وخمســمائة متــر وهــي آيلــة إلــى موكلــي بالشــراء مــن‬\n      ‫‪ ...‬مبوجــب التهميــش املظهــر علــى الصــك هكــذا أجــاب ثــم ســألت‬\n      ‫املدعــي وكالــة عــن صــك متلــك موكلــه لــأرض املدعــى بهــا فأبــرز‬\n      ‫الصــك املذكــور بعاليــه وباالطــاع عليــه وجدتــه كمــا ذكــر املدعــي‬\n      ‫وكالــة وســألت املدعــى عليــه وكالــة عــن صــك متلــك موكلــه لــأرض‬\n      ‫التــي دفــع بتملكهــا فأبــرز الصــك املذكــور بعاليــه وباالطــاع عليــه‬\n      ‫وجدتــه كمــا ذكــر املدعــى عليــه وكالــة ثــم أمــرت بالكشــف علــى‬\n      ‫كال الصكــن بإرســالهما إلــى مصدريهمــا ويف جلســة أخــرى لــدي‬\n      ‫أنــا ‪ ...‬القاضــي باحملكمــة العامــة بينبــع والقائــم بعمــل الشــيخ ‪ ...‬ففــي‬\n      ‫هــذا اليــوم الثالثــاء املوافــق ‪1433/10/10‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫التاســعة صباحــا وفيهــا حضــر وكيــل املدعــي ووكيــل املدعــى عليــه‬\n      ‫وقــد وردنــا خطــاب كاتــب العدل رقــم ‪ 33/7/5/68‬يف ‪1433/9/23‬هـ‬\n      ‫بــأن الصــك رقــم ‪ 3/4/839‬يف ‪1410/5/4‬ه ـ الصــادر مــن كاتــب‬\n      ‫العــدل ‪ ...‬ســاري املفعــول واملفــرغ ‪ ...‬ثــم طلبــت مــن املدعــي توضيــح اجلــزء‬\n      ‫املعتــدى عليــه ووضــع كروكــي لــه وبيــان أطوالــه وحــدوده ويف جلســة‬\n      ‫أخــرى لــدي أنــا ‪ ....‬حضــر الطرفــان وجــرى ســؤال املدعــي وكالــة هــل‬\n      ‫أحضــر املطلــوب منــه يف اجللســة املاضيــة فأجــاب بقولــه إننــي لــم أســتطع‬\n      ‫إحضــار املطلــوب وأطلــب مهلــة جللســة قادمــة فأجبتــه لطلبــه وأفهمتــه‬\n\n\n‫‪443‬‬\n\f‫بــأن املطلــوب منــه جــزء ال يتجــزأ مــن دعــواه فــإن لــم يحضــره يف اجللســة‬\n‫القادمــة فأعتبــره غيــر محــرر لدعــواه ويصــرف النظــر عــن طلبــه ففهــم‬\n‫ذلــك وقــد ســبق الكتابــة لرئيــس قســم الســجالت باحملكمــة باخلطــاب‬\n‫ذي الرقــم ‪ 331613801‬وتاريخ‪1433/08/27‬ه ـ لإلفــادة عــن ســريان‬\n‫مفعــول الصــك رقــم ‪ 514‬وتاريــخ ‪1400/05/03‬ه ـ مــن عدمهــا فوردنــا‬\n‫خطابهــم ذي الرقــم ‪ 331613801‬وتاريــخ ‪1433/08/27‬ه ـ املتضمــن‬\n‫«نفيدكــم أنــه بالبحــث يف ســجالت اإلدارة لدينــا تبــن أن الصــك‬\n‫مطابــق لســجله فقط)ا‪.‬ه ـ ثــم جــرى اطالعــي علــى صــك ملكيــة‬\n‫مــوكل املدعــي الصــادر مــن احملكمــة العامــة بينبــع برقــم ‪ 514‬وتاريــخ‬\n‫‪1400/06/04‬ه ـ املتضمــن ثبــوت متلــك ‪ ....‬لكافــة املزرعــة املذكــورة‬\n‫واحملــدودة واملوضحــة مســاحتها بعاليــه ثبوتـ ًا صحيحـ ًا شــرعي ًا وصــرف‬\n‫النظــر عــن معارضــة البلديــة ا‪.‬ه ـ ومبــا أن صــك حجــة االســتحكام‬\n‫املذكــور آنف ـ ًا معتــرض عليــه مــن البلديــة وقــد صــرف النظــر عــن‬\n‫معارضتهــا ولــم يرفــع احلكــم إلــى محكمــة االســتئناف لتصديقــه‬\n‫وهــذا اإلجــراء إجــراء ناقــص غيــر مكتمــل لإلجــراءات النظاميــة وال‬\n‫يكتســب فيــه احلكــم القطعيــة وذلــك وفق ـ ًا ملــا جــاء يف املــادة الرابعــة‬\n‫واخلمســن بعــد املائتــن مــن نظــام املرافعــات الشــرعية والئحتهــا‬\n‫ـاء علــى املــادة الثالثــة والثمانــن مــن نظــام املرافعــات‬‫التنفيذيــة لــذا وبنـ ً‬\n‫الشــرعية ونصهــا «إذا رأت احملكمــة تعليــق حكمهــا يف موضــوع‬\n‫الدعــوى علــى الفصــل يف مســألة أخــرى يتوقــف عليهــا احلكــم فتأمــر‬\n‫بوقــف الدعــوى ومبجــرد زوال ســبب التوقــف يكــون للخصــوم طلــب‬\n‫الســير يف الدعوى)ا‪.‬ه ـ والالئحــة الثانيــة مــن ذات املــادة ونصهــا(إذا أمــر‬\n‫القاضــي بوقــف الدعــوى حســب هــذه املــادة أو رفــض طلــب اخلصــوم‬\n\n\n                                                                                          ‫‪444‬‬\n\f      ‫فيصــدر قــرار ًا بذلــك ويعامــل مــن لــم يقنع مبوجــب تعليمــات التمييز)ا‪.‬هـ‬\n      ‫فقــد قــررت إيقــاف الدعــوى حلــن اســتكمال املدعــي أصالــة اإلجــراءات‬\n      ‫النظاميــة وتصديــق متلكــه مــن محكمــة االســتئناف وبعــرض ذلــك علــى‬\n      ‫املدعــي وكالــة قــرر عــدم قناعتــه بــه وطلــب االســتئناف مســتعد ًا بتقــدمي‬\n      ‫الئحــة اعتراضيــة فأجبتــه لطلبــه وأفهمتــه بــأن عليــه مراجعــة احملكمــة‬\n      ‫خــال عشــرة أيــام الســتالم نســخة مــن القــرار ومــن ثــم تقــدمي الئحتــه‬\n      ‫االعتراضيــة خــال ثالثــن يومـ ًا مــن تاريــخ االســتالم ففهــم ذلــك وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف ‪ 1433/11/28‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة االســتئناف بالدائــرة احلقوقيــة األولــى مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى احلكــم الصــادر مــن‬\n      ‫فضيلــة الشــيخ ‪ ...‬باحملكمــة العامــة بينبــع واملســجل بعــدد ‪33479865‬‬\n      ‫وتاريــخ ‪ 1433/12/27‬هـ ـ واملتضمــن دعــوى‪ ... /‬ضــد‪ ... /‬واحملكــوم‬\n      ‫فيــه مبــا دون باطنــه وبدراســة احلكــم وصــورة ضبطــه تقــررت املوافقــة‬\n      ‫علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                       ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪445‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":440,"source_page_end":445,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"84a0cad1648f9c111fb36a18316ad7f3b356913662050d9c2ba8fdc5acf928c8","normalized_text_hash":"fd54d77bb952ad29fa9ff81bb8241875c4d2b37440c201be0f3a35f1534aa01c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p440-33479865"},{"id":"092e2bb6-bf92-5249-8590-36f964995025","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقار -شراء عقار باألقساط -مماطلة املدعى عليه يف سداد املبلغ املتبقي -النص يف عقد البيع أنه يف حالة تأخر القسط أكثر من ثالثة أشهر فإن البيع يعتبر الغيا وتكون األقساط املدفوعة مقابل اإليجار -صرف النظر عن دعوى املدعى واخاء سبيل املدعى عليه","document_number":"34169935","case_number":"32540968","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة وبن على املعاملة احملالة لنا","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/23","year":"1434","subject":"عقار -شراء عقار باألقساط -مماطلة املدعى عليه يف سداد املبلغ املتبقي -النص يف عقد البيع أنه يف حالة تأخر القسط أكثر من ثالثة أشهر فإن البيع يعتبر الغيا وتكون األقساط املدفوعة مقابل اإليجار -صرف النظر عن دعوى املدعى واخاء سبيل املدعى عليه","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34169935 :‬تاريخه ‪1434/3/23 :‬هـ‬\n                  ‫رقم الدعوى ‪32540968 :‬‬\n             ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34297874:‬تاريخه‪1434/08/15:‬هـ‬\n\n\n‫عقــار‪ -‬شــراء عقــار باألقســاط‪ -‬مماطلــة املدعــى عليــه يف ســداد املبلــغ‬\n‫املتبقــي‪ -‬النــص يف عقــد البيــع أنــه يف حالــة تأخــر القســط أكثــر مــن‬\n‫ثالثــة أشــهر فــإن البيــع يعتبــر الغيــا وتكــون األقســاط املدفوعــة مقابــل‬\n‫اإليجــار‪ -‬صــرف النظــر عــن دعــوى املدعــى واخــاء ســبيل املدعــى عليــه‬\n                                                            ‫مــن هــذه الدعــوى‬\n\n\n\n        ‫‪ -1‬قول النبي صلى اهلل عليه وسلم ( املسلمون على شروطهم )‬\n‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم ( البينــة علــى املدعــي واليمــن‬\n                                                                ‫علــى مــن أنكــر)‬\n‫‪ -3‬قــال البهوتــي رحمــة اهلل يف كشــاف القنــاع (وإن قــال البائــع ان‬\n‫بعتــك تنقدنــي الثمــن الــى ثالثــة أيــام أو إلــى مــدة معلومــة أقــل مــن‬\n‫ذلــك أو أكثــر وإال فــا بيــع بيننــا صــح البيــع وهــو قــول عمــر كشــرط‬\n‫اخليــار ويفســخ البيــع إن لــم يفعــل أي إن لــم ينقــده املشــترى الثمــن يف‬\n                                                                            ‫املــدة)‬\n                                  ‫‪ -4‬املادة ‪ 55‬من نظام املرافعات الشرعية‬\n\n\n\n\n                                                                                       ‫‪446‬‬\n\f      ‫حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه ووردت إفــادة رئيــس‬\n      ‫املركــز بعــدم جتــاوب املدعــى عليــه لــذا قــرر القاضــي الســير يف نظــر‬\n      ‫الدعــوى غيابي ـ ًا بنــاء علــى املــادة ‪ 55‬مــن نظــام املرافعــات الشــرعية‪-‬‬\n      ‫ادعــى املدعــى وكالــة بــأن موكلــه اشــترى مــن املدعــى عليــه العقــار‬\n      ‫اململــوك لــه ( ذكــر موقــع العقــار ومســتند التملــك ) مببلــغ قــدره مائــه‬\n      ‫وتســعون ألــف ريــال وذلــك بتاريــخ ‪14320/4/1‬هــ‪ ،‬علــى أقســاط‬\n      ‫شــهرية‪ -‬دفــع موكلــه مائــه وأربعــن ألــف ريــال وتبقــي خمســون ألــف‬\n      ‫ريــاال‪ -‬أصبــح املدعــى عليــه مياطلــه يف اســتالم املبلــغ املتبقــي‪ -‬طلــب‬\n      ‫املدعــى وكالــة إلــزام املدعــى عليــه بإفــراغ العقــار ملوكلــه واســتالم‬\n      ‫باقــي القيمــة‪ -‬حضــر املدعــى عليــه وكالــه وصــادق علــى الدعــوى ودفــع‬\n      ‫بــأن املدعــى هــو مــن ماطــل يف ســداد األقســاط يف حينهــا بدايــة مــن‬\n      ‫القســط الــذي حــل بتاريــخ ‪1425/11/30‬ه ـ ومــا بعــده‪ -‬تضمــن العقــد‬\n      ‫شــرط ًا أنــه يف حــال تأخــر القســط أكثــر مــن ثالثــة أشــهر فــان البيــع‬\n      ‫يعتبــر الغي ـ ًا وتكــون األقســاط التــي دفعــت مقابــل إيجــار شــهري‬\n      ‫لكــون املدعــى ســاكن يف العقــار منــذ ذلــك التاريــخ‪ -‬طلــب املدعــى‬\n      ‫عليــه وكالــه فســخ عقــد البيــع وبطالنــه وإلغائــه وإلــزام املدعــى بدفــع‬\n      ‫اإليجــار الواجــب عليــه مــن تاريــخ ‪1425/11/30‬هــ‪ -‬أجــاب املدعــى‬\n      ‫وكالــه بــأن الشــرط املذكــور وان مت ذكــره يف العقــد إال أنــة يعتبــر‬\n      ‫شــرط ًا فاســد ًا ألنــه يحــول البيــع الــذي مت صحيح ـ ًا إلــى إيجــار فيبطــل‬\n      ‫الشــرط ويصــح البيــع‪ -‬قــرر املدعــى أصالــة أن آخــر قســط دفعــه بتاريــخ‬\n      ‫‪1425/10/30‬ه ـ وحصلــت لــه ظــروف وتأخــر يف دفــع قســطني ورفــض‬\n\n‫‪447‬‬\n\f‫البائــع أخــذ املبلــغ بعــد ذلــك‪ -‬جــرى إفهــام املدعــى أصالــة بــأن لــه ميــن‬\n‫املدعــى عليــه علــى امتناعــه عــن اخــذ املبلــغ احلــال يف وقتــه احملــدد فقــال‬\n‫ال أرض بيمينــه‪ -‬لقولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم‬\n‫) وقولــه صلــى اهلل عليــه وســلم (البينــة علــى املدعــى واليمــن علــى مــن‬\n‫أنكــر) فقــدر صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــى وأخلــى‬\n‫ســبيل املدعــى عليــه مــن هــذه الدعــوى وأفهــم املدعــى بــأن له ميــن املدعى‬\n‫عليــه متــى مــاراد كمــا أفهــم املدعــى عليــه بــأن لــه مطالبــة املدعــي‬\n‫بأجــره العقــار بدعــوى مســتقلة بعــد اكتســاب احلكــم القطعيــة‪ -‬لــم‬\n‫يقنــع املدعــى باحلكــم‪ -‬لوحــظ علــى احلكــم مــن محكمــة االســتئناف‬\n‫مبالحظــات أهمهــا أنــه ينبغــي بحــث مســألة أثــر ذلــك الشــرط يف صحــة‬\n‫عقــد البيــع‪ -‬أجــاب القاضــي بــأن اشــتراط البائــع علــى املشــتري بأنــه اذا‬\n‫لــم يســلمه ثمــن البيــع يف مــدة محــدودة وإال فــا بيــع بينهمــا اشــتراط‬\n‫صحيــح ونقــل عــن البهوتــي رحمــة اهلل كالمـ ًا يف ذلــك‪ -‬صــدق احلكــم‬\n                                                       ‫مــن محكمــة االســتئناف‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n‫ـاء‬\n‫فلــدي أنــا ‪...‬القاضــي يف احملكمــة العامــة مبكــة املكرمــة وبنـ ً‬\n‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبكــة‬\n‫املكرمة برقم ‪ 32540968‬وتاريخ ‪1432/11/19‬هـ املقيدة باحملكمة‬\n‫برقــم ‪ 321477680‬وتاريــخ ‪1432/11/19‬ه ـ ففــي يــوم األربعــاء‬\n‫‪1433/2/10‬ه ـ افتتحــت اجللســة الســاعة العاشــرة صباح ـ ًا للنظــر يف‬\n‫دعــوى ‪...‬ضــد ‪ ...‬وفيهــا حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل‬\n\n                                                                                        ‫‪448‬‬\n\f      ‫املدنــي رقــم ‪...‬بالوكالــة عــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل الثانيــة مبكــة‬\n      ‫املكرمــة برقــم ‪ 32899‬يف ‪1432/11/17‬ه ـ واملخــول لــه يف الوكالــة‬\n      ‫حــق إقامــة وســماع عمــوم الدعــاوي واملطالبــات املقامــة منــه أو ضــده ويف‬\n      ‫املرافعــة واملدافعــة ومراجعــة الدوائــر احلكوميــة واحملاكــم الشــرعية‬\n      ‫وحضــور اجللســات وتقــدمي البينــات وســماع احلكــم وقبولــه والقناعــة بــه‬\n      ‫مــن عدمهــا ويف اجلــرح والتعديــل ‪ ...‬الــخ ولــم يحضــر املدعــى عليــه وال مــن‬\n      ‫ميثلــه بوكالــة شــرعية وقــد وردنــا مــن رئيــس مركــز جعرانــة اخلطــاب‬\n      ‫رقــم ‪ 201/8/1‬يف ‪1433/1/1‬ه ـ املتضمــن بــأن املدعــى عليــه ‪...‬غيــر‬\n      ‫متجــاوب حســب إقــرار منــدوب املركــز املرفــق وباالطــاع علــى إقــرار‬\n      ‫املنــدوب وجــد أنــه يتضمــن بــأن املدعــى عليــه اســتعد باملراجعــة ولــم‬\n      ‫يراجــع وهــذا يــدل علــى عــدم جتاوبــه وكان ذلــك بعــد تكــرار إبالغــه‬\n      ‫للمــرة الثالثــة أ‪-‬ه ـ ومرفــق ذلــك يف املعاملــة وحيــث األمــر مــا ذكــر‬\n      ‫ولعــدم جتــاوب املدعــى عليــه لــذا فقــد قــررت النظــر يف القضيــة ضــده‬\n      ‫غيابيـ ًا حســب املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية‬\n      ‫ا ‪-:‬‬ ‫ولوائحهــا التنفيذيــة وبســؤال املدعــي وكالــة عــن دعــواه ادعــى قائـ ً‬\n      ‫إن موكلــي قــد اشــترى مــن املدعــى عليــه العقــار اململــوك لــه والواقــع يف‬\n      ‫اجلعرانــة مبكــة املكرمــة مبوجــب الصــك الصــادر برقــم ‪1/203/62‬‬\n      ‫يف ‪1414/1/9‬ه ـ وال أعلــم مصــدره مببلــغ وقــدره مائــة وتســعون ألــف‬\n      ‫ريــال وذلــك بتاريــخ ‪1420/4/1‬ه ـ علــى أقســاط شــهرية بواقــع ألفــن‬\n      ‫وخمســمائة ريــال ملــدة ســنة ثــم ألفــي ريــال شــهري ًا حتــى نهايــة املبلــغ وقــد‬\n      ‫دفــع للمدعــى عليــه مبلغـ ًا وقــدره مائــة وأربعــون ألــف ريــال وتبقــى يف ذمــة‬\n      ‫موكلــي لــه خمســون ألــف ريــال وقــد أصبــح مياطــل يف اســتالم املبلــغ‬\n\n\n‫‪449‬‬\n\f‫ا أطلــب إلــزام املدعــى‬‫وموكلــي مســتعد بدفــع املبلــغ املتبقــي لــه كامـ ً‬\n‫عليــه بإفــراغ العقــار لــي واســتالم باقــي قيمتــه هــذه دعــواي ولطلــب‬\n‫حضــور املدعــى عليــه وإلحضــار املدعــي وكالــة بيناتــه علــى صحــة‬\n‫دعــواه وحلضــور املدعــي أصالــة ثــم إنــه يف يــوم االثنــن ‪1433/4/26‬ه ـ‬\n‫الســاعة التاســعة والنصــف صباح ـ ًا افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي وكالــة واملدعــي أصالــة ‪......‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدني رقم ‪...‬وحضر حلضورهما ‪...‬ا‪ ...‬ســعودي اجلنســية مبوجب الســجل‬\n‫املدنــي رقــم ‪...‬بالوكالــة عــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدني‬\n‫رقــم ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة مبكــة‬\n‫املكرمــة برقــم ‪ 7792‬يف ‪1433/2/23‬ه ـ جلــد ‪ 5134‬واملخــول لــه يف‬\n‫الوكالــة حــق مراجعــة الدوائــر احلكوميــة القضائيــة واإلداريــة وحضور‬\n‫اجللســات واملرافعــة واملدافعــة وإحضــار البينــات وتعديلهــا وســماع‬\n‫الشــهود وطلــب حتليــف اليمــن واالعتــراض ‪...‬الــخ وبعــرض دعــوى‬\n‫املدعــي وكالــة علــى املدعــى عليــه وكالــة أجــاب قائ ـاً‪ :‬أطلــب مهلــة‬\n‫للرجــوع ملوكلــي وســؤاله وأجيــب يف اجللســة القادمــة فأجبتــه لطلبــه‬\n‫ورفعــت اجللســة لذلــك ثــم إنــه يف يــوم االثنــن ‪1433/6/23‬ه ـ الســاعة‬\n‫احلاديــة عشــرة والنصــف صباحـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه وكالــة وبســؤال املدعــى عليــه وكالــة اإلجابــة‬\n‫علــى دعــوى املدعــي وكالــة أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي وكالــة‬\n‫يف دعــواه مــن كــون موكلــه اشــترى مــن موكلــي العقــار اململــوك لــه‬\n‫والواقــع يف اجلعرانــه يف مكــة املكرمــة مبوجــب الصــك الصــادر برقــم‬\n‫‪ 1/203/62‬يف ‪1414/1/9‬ه ـ مببلــغ وقــدره مائــة وتســعون ألــف ريــال‬\n‫بتاريــخ ‪1420/4/10‬ه ـ علــى أقســاط شــهرية بواقــع ألفــن وخمســمائة‬\n\n\n                                                                                  ‫‪450‬‬\n\f      ‫ريــال ملــدة ســنة ثــم ألفــي ريــال شــهري ًا حتــى نهايــة املبلــغ وأن موكلــي قــد‬\n      ‫اســتلم منــه حتــى اآلن مبلغـ ًا وقــدره مائــة وأربعــون ألــف ريــال فهــذا كلــه‬\n      ‫صحيــح ولكــن املدعــي أصبــح بعــد ذلــك مياطــل يف ســداد األقســاط‬\n      ‫يف حينهــا بدايــة مــن القســط الــذي حــل بتاريــخ ‪1425/11/30‬ه ـ ومــا‬\n      ‫بعــده وقــد تضمــن العقــد شــرط ًا وهــو أنــه يف حالــة تأخــر القســط أكثــر‬\n      ‫مــن ثالثــة أشــهر فــإن البيــع يعتبــر الغيـ ًا وتكــون األقســاط التــي دفعــت‬\n      ‫مقابــل إيجــار شــهري وذلــك لكونــه ســاكن ًا يف العقــار منــذ ذلــك‬\n      ‫التاريــخ وحتــى اآلن والصــك األساســي يف حوزتــي وباســمي حالي ـ ًا لــذا‬\n      ‫فــإن موكلــي يطلــب احلكــم بفســخ عقــد البيــع وبطالنــه وإلغائــه وإلــزام‬\n      ‫املدعــى عليــه بدفــع اإليجــار الواجــب عليــه مــن تاريــخ ‪1425/11/30‬ه ـ‬\n                      ‫وحتــى اآلن بواقــع ألفــن ريــال شــهري ًا هكــذا أجــاب وقــرر‬\n      ‫احلمــد هلل وحــده وبعــد‪ ،‬ففــي يــوم االثنــن ‪1433/4/26‬ه ـ الســاعة‬\n      ‫التاســعة والنصــف صباح ـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n      ‫وكالــة واملدعــي أصالــة ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪...‬وحضــر حلضورهمــا ‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدني‬\n      ‫رقــم ‪...‬بالوكالــة عــن ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪...‬مبوجــب الوكالــة الصــادرة مــن كتابة العــدل الثانية مبكة املكرمة‬\n      ‫برقــم ‪ 7792‬يف ‪1433/2/23‬ه ـ جلــد ‪ 5134‬واملخــول لــه يف الوكالــة‬\n      ‫حــق مراجعــة الدوائــر احلكوميــة القضائيــة واإلداريــة وحضــور اجللســات‬\n      ‫واملرافعــة واملدافعــة وإحضــار البينــات وتعديلهــا وســماع الشــهود وطلــب‬\n      ‫حتليــف اليمــن واالعتــراض ‪...‬الــخ وبعــرض دعــوى املدعــي وكالــة‬\n      ‫علــى املدعــى عليــه وكالــة أجــاب قائـاً‪ :‬أطلــب مهلــة للرجــوع ملوكلــي‬\n      ‫وســؤاله وأجيــب يف اجللســة القادمــة فأجبتــه لطلبــه ورفعــت اجللســة لذلك‬\n\n\n‫‪451‬‬\n\f‫إلــى يــوم االثنــن ‪1433/6/23‬ه ـ الســاعة احلاديــة عشــرة صباحـاً‪ ،‬وباهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                              ‫يف ‪1433/4/26‬ه ـ‬\n‫احلمــد هلل وحــده‪ ،‬وبعــد‪ ،‬ففــي يــوم االثنــن ‪1433/6/23‬ه ـ الســاعة‬\n‫احلاديــة عشــرة والنصــف صباحـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي‬\n‫وكالــة واملدعــى عليــه وكالــة وبســؤال املدعــى عليــه وكالــة اإلجابــة‬\n‫علــى دعــوى املدعــي وكالــة أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي وكالــة‬\n‫يف دعــواه مــن كــون موكلــه اشــترى مــن موكلــي العقــار اململــوك لــه‬\n‫والواقــع يف اجلعرانــه يف مكــة املكرمــة مبوجــب الصــك الصــادر برقــم‬\n‫‪ 1/203/62‬يف ‪1414/1/9‬ه ـ مببلــغ وقــدره مائــة وتســعون ألــف ريــال‬\n‫بتاريــخ ‪1420/4/10‬ه ـ علــى أقســاط شــهرية بواقــع ألفــن وخمســمائة‬\n‫ريــال ملــدة ســنة ثــم ألفــي ريــال شــهري ًا حتــى نهايــة املبلــغ وأن موكلــي قــد‬\n‫اســتلم منــه حتــى اآلن مبلغـ ًا وقــدره مائــة وأربعــون ألــف ريــال فهــذا كلــه‬\n‫صحيــح ولكــن املدعــي أصبــح بعــد ذلــك مياطــل يف ســداد األقســاط‬\n‫يف حينهــا بدايــة مــن القســط الــذي حــل بتاريــخ ‪1425/11/30‬ه ـ ومــا‬\n‫بعــده وقــد تضمــن العقــد شــرط ًا وهــو أنــه يف حالــة تأخــر القســط أكثــر‬\n‫مــن ثالثــة أشــهر فــإن البيــع يعتبــر الغيـ ًا وتكــون األقســاط التــي دفعــت‬\n‫مقابــل إيجــار شــهري وذلــك لكونــه ســاكن ًا يف العقــار منــذ ذلــك‬\n‫التاريــخ وحتــى اآلن والصــك األساســي يف حوزتــي وباســمي حالي ـ ًا لــذا‬\n‫فــإن موكلــي يطلــب احلكــم بفســخ عقــد البيــع وبطالنــه وإلغائــه وإلــزام‬\n‫املدعــى عليــه بدفــع اإليجــار الواجــب عليــه مــن تاريــخ ‪1425/11/30‬ه ـ‬\n‫وحتــى اآلن بواقــع ألفــن ريــال شــهري ًا هكــذا أجــاب وقــرر وبعــرض‬\n‫ذلــك علــى املدعــي وكالــة قــال أطلــب مهلــة للرجــوع ملوكلــي وســؤاله‬\n\n\n                                                                                           ‫‪452‬‬\n\f      ‫وأجيــب يف اجللســة القادمــة فأجبتــه لطلبــه ورفعــت اجللســة لذلــك إلــى‬\n      ‫يــوم الثالثــاء ‪1433/9/12‬ه ـ الســاعة احلاديــة عشــرة صباح ـ ًا ‪ ،‬وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                                      ‫يف ‪1433/6/23‬ه ـ‬\n      ‫وبعــرض ذلــك علــى املدعــي وكالــة قــال أطلــب مهلــة للرجــوع ملوكلــي‬\n      ‫وســؤاله وأجيــب يف اجللســة القادمــة فأجبتــه لطلبــه ثم إنــه يف يوم الثالثاء‬\n      ‫‪1433/9/12‬ه ـ الســاعة احلاديــة عشــرة صباحــا افتتحــت اجللســة وفيهــا‬\n      ‫حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه وال مــن ميثلــه بوكالــة‬\n      ‫شــرعية وكان قــد قــدم املدعــى عليــه وكالــة اعتــذرا عــن حضــور هــذه‬\n      ‫اجللســة لعــدم تواجــده يف مكــة وبســؤال املدعــي وكالــة عمــا وعــد بــه‬\n      ‫يف اجللســة املاضيــة مــن إحضــار رده علــى إجابــة املدعــى عليــه وكالــة‬\n      ‫أبــرز ردا مكونــا مــن ورقتــن ومطبــوع باحلاســب اآللــي ومــؤرخ يف‬\n      ‫‪1433/9/11‬ه ـ وهــذا نصــه ‪ « :‬تقــدم املدعــى عليــه مبذكــرة دفــع مــن‬\n      ‫خاللهــا بــأن العقــد هــو شــريعة املتعاقديــن وبــأن العقــد احلاكــم للعالقــة‬\n      ‫العقديــة بــن الطرفــن حــوى علــى شــرط يقول بأن العقد يعتبر مفســوخا‬\n      ‫والغيــا وال يعمــل بــه ويكــون البيــت املبــاع مؤجــرا علــى املشــتري يف حالة‬\n      ‫عــدم التــزام املشــتري بدفــع ثمــن املنــزل خــال ثالثــة أشــهر‪ (.‬الـ ــرد ) أوال‬\n      ‫‪ :‬املدعــى عليــه ارتكــن علــى شــرط فاســخ لــم يتحقــق فالبيــع صحيــح‬\n      ‫حيــث اســتوفى كافــة شــروطه الشــرعية الالزمــة إلجنــازه مــن إيجــاب‬\n      ‫وقبــول وتراضــي بــن البائــع واملشــتري ووقــع البيــع علــى مــا يجــوز بيعــة‬\n      ‫شــرعا وال توجــد شــائبة تشــوب البيــع‪ .‬ثانيــا ‪ :‬املشــتري هــو مــن جلــأ إلــى‬\n      ‫القضــاء الشــرعي إلجبــار البائــع علــى إكمــال العقــد وال توجــد قرينــة‬\n      ‫تثبــت أن املدعــي امتنــع عــن تســليم باقــي ثمــن البيــت حيــث قــام بســداد‬\n\n\n‫‪453‬‬\n\f‫مبلــغ مائــة وأربعــون ألــف ريــال مــن إجمالــي ثمــن األرض والبائــع هــو مــن‬\n‫رفــض اســتالم باقــي املبلــغ‪ .‬ثالثــا ‪ :‬مــن جلــأ إلــى القضــاء الشــرعي هــو‬\n‫املشــتري وليــس البائــع ومــن ثــم فــا ميكــن للبائــع أن يطلــب االعتــداد‬\n‫بالتأخــر عــن إكمــال باقــي ثمــن املنــزل ألنــه لــو كان حريصــا علــى‬\n‫ذلــك لــكان هــو مــن بــدر باللجــوء للقضــاء الشــرعي طالبـ ًا إعمــال ذلــك‬\n‫الشــرط ولكــن مــن جلــأ للقضــاء هــو املشــتري طالبــا إلــزام البائــع بعــدم‬\n‫املماطلــة يف اســتالم باقــي قيمــة املنــزل وإلــزام املالــك باإلفــراغ الشــرعي‬\n‫للمنــزل مــع مالحظــة أن مــا قــام بــه موكلــي مــن صيانة وبنــاء تقدر مبائة‬\n‫ون‬ ‫وخمســن ألــف ريــال‪ .‬رابعــا ‪ :‬قو ُلــه ص َّلــى اهلل عليــه وسـلَّم‪ْ (( :‬ال ُْسـل ُِم َ‬\n    ‫ا ًال )) ‪ ،‬وقــولُ‬    ‫امــا‪َ ،‬أ ْو َحـ َّـر َم َح ـ َ‬\n                                                        ‫وطه ِْم‪ِ ،‬إال َشـ ْـر ًطا َأ َحــلَّ َح َر ً‬\n                                                                                                  ‫َع َلــى ُشـ ُـر ِ‬\n ‫ـروط ))‪ .‬فهــذا يــدلُّ‬      ‫الشـ ِ‬     ‫ـوق عنـ َـد ُّ‬‫قاطـ ُـع احلقـ ِ‬ ‫اهلل عنــه‪َ (( :‬م ِ‬  ‫رضــي ُ‬    ‫عمـ َـر ِ‬\n‫ـف‬    ‫ـزوم الوفــا ِء بهــا‪ ،‬مــا لــم ُتخا ِلـ ِ‬  ‫الص َّحـ ُة ولـ ُ‬\n                                                                   ‫ـروط ِّ‬  ‫الشـ ِ‬    ‫علــى أن األصــلَ يف ُّ‬\n‫الشــريع َة والشــرط الــذي يحتــج بــه املدعــى عليــه البائــع هــو شــرط فاســد‬                             ‫َّ‬\n‫كونــه يحــول البيــع الــذي مت صحيحــا إلــى إيجــار فيبطل الشــرط ويصح‬\n‫البيــع‪ .‬لــذا وبنــاء علــى كل مــا تقــدم نلتمــس احلكــم بإلــزام البائــع‬\n‫باســتالم باقــي الثمــن وقــدرة خمســون ألــف ريــال وإلزامــه باإلفــراغ‬\n‫الشــرعي للمنــزل» مقدمــه املدعــي وكالــة وحلضــور املدعــى عليــه أو‬\n‫وكيلــه فقــد رفعــت اجللســة ثــم إنــه يف يــوم الثالثــاء ‪1433/12/28‬ه ـ‬\n‫الســاعة العاشــرة صباحـ ًا افتتحــت اجللســة وفيهــا حضــر املدعــي وكالــة‬\n‫واملدعــي أصالــة واملدعــى عليــه وكالــة واملدعــى عليــه أصالــة ‪...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وقــد جــرى منــي االطــاع علــى‬\n‫عقــد املبايعــة املبــرم بــن الطرفــن برقــم ‪ 54‬يف ‪1420/4/10‬ه ـ مطبــوع‬\n‫علــى ورق تابــع ملكتــب ‪...‬للخدمــات العقاريــة فوجــد يتضمــن بيــع املدعــى‬\n\n\n                                                                                                                       ‫‪454‬‬\n\f      ‫عليــه ‪ ...‬علــى املدعــي ‪...‬عقــاره الواقــع يف اجلعرانــة اململــوك لــه مبوجــب‬\n      ‫الصــك رقــم ‪ 1/203/62‬يف ‪1414/1/9‬ه ـ مببلــغ وقــدره مائــة وتســعون‬\n      ‫ألــف ريــال علــى أقســاط شــهرية بواقــع ألفــن وخمســمائة ريــال شــهري ًا‬\n      ‫ا وقــد‬ ‫ملــدة ســنة والباقــي ألفــن ريــال شــهري ًا حتــى نهايــة املبلــغ كام ـ ً‬\n      ‫تضمــن العقــد شــرطان همــا‪ -1 :‬عــدم اإلفــراغ إال بعــد التســديد ‪ -2‬إذا‬\n      ‫تأخــر القســط أكثــر مــن ثالثــة أشــهر فيعتبــر البيــع الغي ـ ًا واألقســاط‬\n      ‫التــي دفعــت مقابــل إيجــار شــهري ويف آخــرة توقيــع البائــع وبصمــة إبهــام‬\n      ‫املشــتري وشــهادة كل مــن ‪...‬و‪...‬أ‪.‬ه ـ مرفــق صــورة منــه يف املعاملــة‬\n      ‫وبعــرض العقــد علــى املدعــي أصالــة قــال العقــد صحيــح وقــد بصمــت‬\n      ‫عليــه هكــذا قــرر وبســؤاله هــل أنــت حالي ـ ًا ســاكن يف العقــار؟ فقــال‬\n      ‫نعــم ســاكن فيــه هكــذا قــرر وبســؤال املدعــى عليــه وكالــة عــن‬\n      ‫صــك العقــار محــل الدعــوى أبــرز صــورة منــه وهــو صــادر مــن كتابــة‬\n      ‫العــدل األولــى مبكــة املكرمــة برقــم ‪ 1/203/62‬يف ‪1414/1/9‬ه ـ‬\n      ‫فوجــد يتضمــن متلــك ‪ ...‬للعقــار املوصــوف باطنــه والواقــع يف اجلعرانــة‬\n      ‫شــرق مســجد ‪ ...‬ومرفــق صــورة منــه يف املعاملــة وبســؤال املدعــي متــى‬\n      ‫آخــر قســط قمــت بدفعــه للمدعــى عليــه؟ فقــال أخــر قســط هــو بتاريــخ‬\n      ‫‪1425/10/30‬ه ـ ومــا بعــده لــم يتــم دفعــه هكــذا قــرر وبســؤاله عــن‬\n      ‫ســبب عــدم دفعــه باقــي األقســاط التــي حلــت؟ فقــال حصــل لــي ظــرف‬\n      ‫وتأخــرت يف دفــع بعــض األقســاط وعنــد ذهابــي لدفعهــا رفــض املدعــى‬\n      ‫عليــه ذلــك هكــذا قــرر وبســؤاله كــم األقســاط التــي قمــت بالتأخــر‬\n      ‫يف دفعهــا يف حينهــا؟ فقــال شــهران فقــط ورفــض البائــع أخــذ املبلــغ بعــد‬\n                                                                     ‫ذلــك هكــذا قــرر‬\n      ‫احلمد هلل وحده وبعد ففي يوم الثالثاء‪1434/3/17‬هـ الســاعة العاشــرة‬\n\n\n‫‪455‬‬\n\f‫والنصــف صباحـ ًا افتتحــت اجللســة وفيها حضر املدعــي وكالة واملدعي‬\n‫أصالــة واملدعــى عليــه وكالــة واملدعــى عليــه أصالــة فجــرت محاولــة‬\n‫الصلــح بــن الطرفــن فلــم يصطلحــا وكان قــد جــرت الكتابــة منــي‬\n‫لرئيــس كتابــة العــدل األولــى مبكــة املكرمــة باخلطــاب رقــم ‪341355‬‬\n‫يف ‪1434/1/3‬ه ـ مــن أجــل االستفســار عــن الصــك رقــم ‪ 1/203/62‬يف‬\n‫‪1414/1/9‬هـ فوردنا اجلواب برقم ‪ 345104‬يف ‪1434/1/19‬هـ مفاده ‪:‬‬\n‫بأن صورة الصك رقم ‪ 1/203/62‬يف ‪1414/1/19‬هـ مطابقة لســجلها‬\n‫وســارية املفعــول حتــى تاريخــه أ‪.‬ه ـ عنــد ذلــك أفهمــت املدعــي أصالــة بأن‬\n‫لــه ميــن املدعــى عليــه علــى امتناعــه عــن أخــذ املبلــغ احلــال يف وقته احملدد‬\n‫فقــال ‪ :‬ال أرضــى بيمينــه فجــرى ســؤال الطرفــن هــل لديكمــا مــا‬\n‫تريــدان إضافتــه ؟ فقــاال ‪ :‬ليــس لدينــا ســوى مــا قدمنــاه ونطلــب الفصــل‬\n‫يف القضيــة هكــذا قــررا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وبعــد دراســة القضيــة وتأملهــا وبعــد االطــاع علــى العقــد املبــرم بــن‬\n‫الطرفــن برقــم ‪ 54‬يف ‪1420/4/10‬ه ـ واملتضمــن شــرط بأنــه إذا تأخــر‬\n‫القســط أكثــر مــن ثالثــة أشــهر فيعتبــر البيــع الغي ـ ًا واألقســاط التــي‬\n‫دفعــت مقابــل إيجــار شــهري ونظــرا ملصادقــة الطرفــن عليــه وإلقــرار‬\n‫املدعــي بتأخــره عــن ســداد بعــض األقســاط يف وقتهــا احملــدد ولقــول‬\n‫النبــي صلــى اهلل عليــه وســلم ‪ « :‬املســلمون علــى شــروطهم « ومبــا أنــه ال‬\n‫بينــة للمدعــي علــى امتنــاع املدعــى عليــه علــى اســتالم بعــض األقســاط‬\n‫يف وقتهــا احملــدد ولــم يــرض بيمــن املدعــى عليــه ولقــول النبــي صلــى‬\n‫اهلل عليــه وســلم ‪ « :‬البينــة علــى املدعــي واليمــن علــى مــن أنكــر «‬\n‫لذلــك كلــه فقــد صرفــت النظــر عــن دعــوى املدعــي وأخليــت ســبيل‬\n‫املدعــى عليــه مــن هــذه الدعــوى وبذلــك حكمــت وأفهمــت املدعــي بــأن‬\n\n\n                                                                                        ‫‪456‬‬\n\f      ‫لــه ميــن املدعــى عليــه متــى مــا أراد كمــا أفهمــت املدعــى عليــه بــأن لــه‬\n      ‫مطالبــة املدعــي بأجــرة العقــار بدعــوى مســتقلة بعــد اكتســاب احلكــم‬\n      ‫القطعيــة‪ ،‬وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة‬\n      ‫بــه واملدعــي عدمهــا وطلــب االســتئناف بالئحــة اعتراضيــة فجــرى‬\n      ‫إفهامــه بــأن عليــه التقــدم للمحكمــة يــوم األحــد القــادم ‪1434/3/22‬ه ـ‬\n      ‫الســتالم نســخة مــن صــك احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن‬\n      ‫يومــا مــن التاريــخ املذكــور وإذا لــم يتقــدم بذلــك خــال املــدة املذكــورة‬\n      ‫فسيســقط حقــه بطلــب االســتئناف وسيكتســب احلكــم القطعيــة‪،‬‬\n      ‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم‪ .‬حــرر يف ‪1434/3/17‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده‪ ،‬وبعــد ‪ :‬ففــي يــوم األحــد ‪1434/7/16‬ه ـ افتتحــت‬\n      ‫اجللســة وكان قــد جــرى منــي بعــث املعاملــة حملكمة االســتئناف مبكة‬\n      ‫املكرمــة باخلطــاب رقــم ‪ 321477680‬يف ‪1434/5/21‬ه ـ فعــادت إلــي‬\n      ‫بخطــاب فضيلــة رئيــس محكمــة االســتئناف مبكة املكرمــة املكلف‬\n      ‫رقــم ‪ 321477680‬يف ‪1434/6/20‬ه ـ وبرفقــه قــرار الدائــرة احلقوقيــة‬\n      ‫الثانيــة مبحكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 34243845‬يف‬\n      ‫‪1434/6/18‬ه ـ املتضمــن بعــد املقدمــة مــا نصــه ‪ « :‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه تقــرر باألكثريــة إعادتهــا لفضيلتــه ملالحظــة مــا يلــي‬\n      ‫‪ -1 -:‬بحــث مســألة أثــر ذلــك الشــرط يف صحــة عقــد البيــع ‪ -2‬املدعــي‬\n      ‫ذكــر بأنــه لــم يتأخــر إال عــن شــهرين فــا بــد مــن عــرض ذلــك علــى‬\n      ‫املدعــى عليــه وأخــذ إجابتــه علــى ذلــك ‪ -3‬حكــم فضيلتــه يحتــاج إلــى‬\n      ‫تأمــل وإعــادة نظــر لترجــح جانــب املدعــي نظــر ًا الرتفــاع أســعار العقارات‬\n      ‫يف الوقــت الراهــن ارتفاع ـ ًا فاحش ـ ًا قــد يجعــل بعــض البائعــن يســعون‬\n\n\n‫‪457‬‬\n\f‫إلبطــال البيــع وفســخه طمعـ ًا يف املــال وعلــى فضيلتــه أخــذ هــذا اجلانــب‬\n‫بعــن االعتبــار ‪ -4‬املدعــى عليــه ذكــر يف دفعــه أن العقد يتضمن شــرط ًا‬\n‫وهــو أنــه يف حالــة تأخــر القســط أكثــر مــن ثالثــة أشــهر فــإن البيــع يعتبر‬\n‫الغيــا فــإن املتعــن علــى مصــدر الصــك مطالبــة املدعــى عليــه بصحــة مــا‬\n‫دفــع بــه مــن تأخــر املدعــي عــن ثالثــة أقســاط وســماع بينتــه ويف حــال‬\n‫عــدم وجــود البينــة يفهــم بــأن لــه ميــن املدعــي علــى نفــي مــا دفــع بــه‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ ،،،‬قاضي اســتئناف ‪...‬توقيعه وختمه الشــخصي قاضي اســتئناف ‪...‬‬\n‫توقيعــه وختمــه الشــخصي رئيــس الدائــرة ‪...‬توقيعــه وختمــه الشــخصي‬\n‫موافــق علــى احلكــم « وعليــه أجيــب أصحــاب الفضيلــة وفقنــي اهلل‬\n‫وإياهــم للعلــم النافــع والعمــل الصالــح مبــا يلــي ‪ :‬أوال ‪ :‬اشــتراط البائــع‬\n‫علــى املشــتري بأنــه يف حالــة إذا لــم يســلمه ثمــن املبيــع يف مــدة محــددة‬\n‫وإال فــا بيــع بينهمــا اشــتراط صحيــح وقــد نــص علــى ذلــك العلمــاء‬\n‫رحمهــم اهلل قــال البهوتــي رحمــه اهلل يف كشــاف القنــاع مــا نصــه ‪:‬‬\n‫« وإن قــال البائــع إن بعتــك تنقدنــي الثمــن إلــى ثالثــة أيــام أو إلــى مــدة‬\n‫معلومــة أقــل مــن ذلــك أو أكثــر وإال فــا بيــع بيننــا صــح البيــع وهــو‬\n‫قــول عمــر كشــرط اخليــار وينفســخ البيــع إن لــم يفعــل أي إن لــم ينقــده‬\n‫املشــتري الثمــن يف املــدة « ثانيــا ‪ :‬مفهــوم مــن كالم املدعــى عليــه يف‬\n‫إجابتــه علــى الدعــوى ومــا بعدهــا مــن أن املشــتري الــذي هــو املدعــي قــد‬\n‫تأخــر عــن الســداد أكثــر مــن ثالثــة أشــهر ولذلــك جــرى طلــب البينــة‬\n‫منــه علــى ذلــك ثالثــا ‪ :‬جــرى منــي ســابقا طلــب البينــة مــن املدعــى عليــه‬\n‫علــى أن املدعــي قــد تأخــر عــن ســداد ثالثــة أقســاط وجــرى رصــد بينتــه‬\n‫يف ضبــط القضيــة يف الصفحــة رقــم ( ‪ ) 3‬لذلــك وبعــد اإلجابــة لــم يظهــر‬\n\n\n                                                                                      ‫‪458‬‬\n\f      ‫لــي ســوى مــا أجريتــه وحكمــت بــه‪ ،‬وأمــرت بإحلــاق ذلــك يف صكــه‬\n      ‫وســجله‪ ،‬وإعــادة املعاملــة حملكمــة االســتئناف مبكــة املكرمــة‬\n      ‫إلكمــال الزمهــا‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/7/16‬ه ـ‬\n      ‫تظهيــرات الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف مبكــة‬\n      ‫املكرمــة احلمــد هلل وحــده وبعــد ‪ ،‬فقــد اطلعنــا علــى هــذا الصــك رقــم‬\n      ‫‪ 34169935‬وتاريــخ ‪1434/3/23‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪...‬‬\n      ‫القاضــي باحملكمــة العامــة مبكــة املكرمــة وأصدرنــا القــرار رقــم‬\n      ‫‪ 34297874‬وتاريــخ ‪1434/8/15‬ه ـ املتضمــن املوافقــة باألكثريــة‬\n      ‫علــى احلكــم بعــد اإلجــراء األخيــر ‪ ،‬قاضــي اســتئناف ‪ ...‬توقيعــه ختمــه‬\n      ‫الشــخصي قاضــي اســتئناف ‪ ...‬توقيعــه ختمــه الشــخصي رئيــس الدائــرة‬\n      ‫‪...‬توقيعــه ختمــه الشــخصي ولــه وجهــة نظــر أه ـ وحتــى ال يخفــى جــرى‬\n      ‫بيانــه ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه صحبــه‬\n                                                    ‫وســلم حــرر يف ‪1434/9/13‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 321477680‬وتاريــخ‬\n      ‫‪1434/7/25‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪...‬القاضــي باحملكمــة العامــة مبكــة املكرمــة برقــم ‪34169935‬‬\n      ‫وتاريــخ ‪1434/3/23‬ه ـ ‪ ،‬املتضمــن دعــوى ‪ ...‬ضــد ‪ ،...‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n      ‫احلكــم بعــد االجــراء االخيــر ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n                                                 ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫‪459‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"93dd85ab-6567-5a2e-a7fd-a294170a7530","source_page_start":446,"source_page_end":459,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b6833a4eccebb1ebaa3fbc9ac784817a282768850aad8d9f1f0991818195012d","normalized_text_hash":"90cebdba84e4c560f1cd46f89e560ea06ed547dbd366b83e52306f8d8667d440","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v5-p446-34169935"}]$archive_payload$::jsonb) AS x LIMIT 25
